INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc55c3cf-6402-4a40-90a9-ef27a55cab14', '上樂使君救康成公', '上乐使君救康成公', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["曾夢諸侯笑，康囚議脫枷。","千根池裏藕，一朵火中花。"]', '["曾梦諸侯笑，康囚議脫枷。","千根池裏藕，一朵火中花。"]', '诗', 'shi', '', NULL, '上樂使君救康成公 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c12b6bbb-2b96-47a1-8edb-1c9a4aa2bb04', '[昆]明池泛舟', '[昆]明池泛舟', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["一枝青竹榜，泛泛綠萍裏。","不見釣魚人，漸入秋塘水。"]', '["一枝青竹榜，泛泛綠萍裏。","不见釣鱼人，漸入秋塘水。"]', '诗', 'shi', '', NULL, '[昆]明池泛舟 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de7938d0-3a30-4f1c-b41d-50deffe65172', '送僧', '送僧', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["大內曾持論，天南化俗行。","舊房山雪在，春草岳陽生。","曉了蓮經義，堪任寶蓋迎。","王侯皆護法，何寺講鐘鳴。"]', '["大內曾持論，天南化俗行。","旧房山雪在，春草岳陽生。","晓了蓮經義，堪任寶蓋迎。","王侯皆護法，何寺講鐘鳴。"]', '诗', 'shi', '', NULL, '送僧 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f48a5781-5706-4ab7-a503-1a9c5683d0e3', '送劉知新往襄陽', '送劉知新往襄陽', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["此別誠堪恨，荆襄是舊游。","眼光懸欲落，心緒亂難收。","花木三層寺，煙波五相樓。","因君兩地去，長使夢悠悠。"]', '["此別誠堪恨，荆襄是旧游。","眼光懸欲落，心緒亂难收。","花木三層寺，煙波五相楼。","因君兩地去，长使梦悠悠。"]', '诗', 'shi', '', NULL, '送劉知新往襄陽 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66203a48-5628-4a89-98e5-1773d73500f7', '寄慈恩寺郁上人', '寄慈恩寺郁上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["中秋期夕望，虛室省相容。","北斗生清漏，南山出碧重。","露寒鳩宿竹，鴻過月圓鐘。","此夜情應切，衡陽舊住峯。"]', '["中秋期夕望，虛室省相容。","北斗生清漏，南山出碧重。","露寒鳩宿竹，鴻過月圓鐘。","此夜情應切，衡陽旧住峯。"]', '诗', 'shi', '', NULL, '寄慈恩寺郁上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f06fae6-65c7-4788-b168-454604827e92', '送饒州張使君', '送饒州張使君', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["終南雲雨連城闕，去路西江白浪頭。","滁上郡齋離昨日，鄱陽農事勸今秋。","道心生向前朝寺，文思來因靜夜樓。","借問泊帆干謁者，誰人曾聽峽猨愁。"]', '["終南云雨連城闕，去路西江白浪头。","滁上郡斋離昨日，鄱陽農事勸今秋。","道心生向前朝寺，文思来因静夜楼。","借问泊帆干謁者，誰人曾听峽猨愁。"]', '诗', 'shi', '', NULL, '送饒州張使君 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c4710c-1451-4e49-9bdd-71824debf987', '觀冬設上東川楊尚書', '观冬設上东川楊尚书', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["匏革奏冬非獨樂，軍城未曉啓重門。","何時却入三台貴，此日空知八座尊。","羅綺舞中收雨點，貔貅閫外卷雲根。","逐遷屬吏隨賓列，撥櫂扁舟不忘恩。"]', '["匏革奏冬非独乐，軍城未晓啓重门。","何时却入三台貴，此日空知八座尊。","羅綺舞中收雨点，貔貅閫外卷云根。","逐遷屬吏隨賓列，撥櫂扁舟不忘恩。"]', '诗', 'shi', '', NULL, '觀冬設上東川楊尚書 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aa69371-e08d-482d-8c80-bf7835c779f9', '巴興作', '巴兴作', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["三年未省聞鴻呌，九月何曾見草枯。","寒暑氣均思白社，星辰位正憶皇都。","蘇卿持節終還漢，葛相行師自渡瀘。","鄉味朔山林果別，北歸期挂海帆孤。"]', '["三年未省闻鴻呌，九月何曾见草枯。","寒暑氣均思白社，星辰位正憶皇都。","蘇卿持節終還漢，葛相行師自渡瀘。","乡味朔山林果別，北归期挂海帆孤。"]', '诗', 'shi', '', NULL, '巴興作 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('632cfbf5-9713-4213-9836-dc982f074042', '早蟬', '早蟬', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["早蟬孤抱芳槐葉，噪向殘陽意度秋。","也任一聲催我老，堪聽兩耳畏吟休。","得非下第無高韻，須是青山隱白頭。","若問此心嗟嘆否，天人不可怨而尤。"]', '["早蟬孤抱芳槐葉，噪向殘陽意度秋。","也任一声催我老，堪听兩耳畏吟休。","得非下第無高韻，須是青山隐白头。","若问此心嗟嘆否，天人不可怨而尤。"]', '诗', 'shi', '', NULL, '早蟬 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87b172d7-eb10-4fdb-8ff8-de7e578bcf67', '投元郎中', '投元郎中', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["心在瀟湘歸未期，卷中多是得名詩。","高臺聊望清秋色，片水堪留白鷺鷥。","省宿有時聞急雨，朝迴盡日伴禪師。","舊文去歲曾將獻，蒙與人來說始知。"]', '["心在瀟湘归未期，卷中多是得名诗。","高台聊望清秋色，片水堪留白鷺鷥。","省宿有时闻急雨，朝迴尽日伴禪師。","旧文去歲曾將獻，蒙與人来说始知。"]', '诗', 'shi', '', NULL, '投元郎中 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea048c96-7ee0-4af8-b89e-d06ecc14d4aa', '阮籍嘯臺', '阮籍嘯台', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["如聞長嘯春風裏，荆棘叢邊訪舊蹤。","地接蘇門山近遠，荒臺突兀抵高峰。"]', '["如闻长嘯春风裏，荆棘叢邊訪旧蹤。","地接蘇门山近远，荒台突兀抵高峰。"]', '诗', 'shi', '', NULL, '阮籍嘯臺 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf244021-c3cf-4c94-9a20-db719d7036e9', '滕校書使院小池', '滕校书使院小池', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["小池誰見鑿時初，走水南來十里餘。","樓上日斜吹暮角，院中人出鎖遊魚。"]', '["小池誰见鑿时初，走水南来十里餘。","楼上日斜吹暮角，院中人出鎖游鱼。"]', '诗', 'shi', '', NULL, '滕校書使院小池 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ed511f-3b9a-4519-b7de-eba88f3a89c8', '送陝府王建司馬', '送陝府王建司马', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["司馬雖然聽曉鐘，尚猶高枕恣疎慵。","請詩僧過三門水，賣藥人歸五老峰。","移舫綠陰深處息，登樓涼夜此時逢。","杜陵惆悵臨相餞，未寢月前多屐蹤。"]', '["司马雖然听晓鐘，尚猶高枕恣疎慵。","請诗僧過三门水，賣藥人归五老峰。","移舫綠陰深处息，登楼涼夜此时逢。","杜陵惆悵臨相餞，未寢月前多屐蹤。"]', '诗', 'shi', '', NULL, '送陝府王建司馬 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f1960e1-5280-4a75-9521-71557978f7b9', '上谷旅夜', '上谷旅夜', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["世難那堪恨旅遊，龍鍾更是對窮秋。","故園千里數行淚，鄰杵一聲終夜愁。","月到寒窗空皓皛，風翻落葉更颼飀。","此心不向常人說，倚識平津萬戶侯。"]', '["世难那堪恨旅游，龙鍾更是对窮秋。","故园千里數行泪，鄰杵一声終夜愁。","月到寒窗空皓皛，风翻落葉更颼飀。","此心不向常人说，倚識平津万戶侯。"]', '诗', 'shi', '', NULL, '上谷旅夜 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('579805b9-d4c7-4d0f-9b48-165ead38e0c6', '寄無得頭陀', '寄無得头陀', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["夏臘今應三十餘，不離樹下塚間居。","貌堪良匠抽毫寫，行稱高僧續傳書。","落澗水聲來遠遠，當空月色自如如。","白衣只在青門裏，心每相親跡且疎。"]', '["夏臘今應三十餘，不離樹下塚间居。","貌堪良匠抽毫寫，行稱高僧續傳书。","落澗水声来远远，當空月色自如如。","白衣只在青门裏，心每相親跡且疎。"]', '诗', 'shi', '', NULL, '寄無得頭陀 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f309673-cce0-4721-b472-318a1dd75e39', '崔卿池上雙白鷺', '崔卿池上雙白鷺', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["鷺雛相逐出深籠，頂各有絲莖數同。","灑石多霜移足冷，隔城遠樹挂巢空。","其如盡在灘聲外，何似雙飛浦色中。","見此池潭卿自鑿，清泠太液底潛通。"]', '["鷺雛相逐出深籠，頂各有絲莖數同。","灑石多霜移足冷，隔城远樹挂巢空。","其如尽在灘声外，何似雙飞浦色中。","见此池潭卿自鑿，清泠太液底潛通。"]', '诗', 'shi', '', NULL, '崔卿池上雙白鷺 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d06bbf3-c860-4af6-a1e9-4213692b9673', '送胡道士', '送胡道士', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["短褐身披滿漬苔，靈溪深處觀門開。","却從城裏移琴去，許到山中寄藥來。","臨水古壇秋醮罷，宿杉幽鳥夜飛迴。","丹梯願逐真人上，日夕歸心白髮催。"]', '["短褐身披满漬苔，靈溪深处观门开。","却從城裏移琴去，許到山中寄藥来。","臨水古壇秋醮罷，宿杉幽鸟夜飞迴。","丹梯願逐真人上，日夕归心白髮催。"]', '诗', 'shi', '', NULL, '送胡道士 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8395644-390a-487e-9d7c-8bade82c9940', '寄韓潮州愈', '寄韓潮州愈', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["此心曾與木蘭舟，直到天南潮水頭。","隔嶺篇章來華岳，出關書信過瀧流。","峰懸驛路殘雲斷，海浸城根老樹秋。","一夕瘴煙風卷盡，月明初上浪西樓。"]', '["此心曾與木蘭舟，直到天南潮水头。","隔嶺篇章来华岳，出关书信過瀧流。","峰懸驛路殘云斷，海浸城根老樹秋。","一夕瘴煙风卷尽，月明初上浪西楼。"]', '诗', 'shi', '', NULL, '寄韓潮州愈 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e396e0f-3a6d-4d6b-9a02-2df35747d3a8', '詶張籍王建', '詶張籍王建', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["疎林荒宅古坡前，久住還因太守憐。","漸老更思深處隱，多閑數得上方眠。","鼠拋貧屋收田日，鴈度寒江擬雪天。","身是龍鍾應是分，水曹芸閣枉來篇。"]', '["疎林荒宅古坡前，久住還因太守怜。","漸老更思深处隐，多闲數得上方眠。","鼠拋貧屋收田日，鴈度寒江擬雪天。","身是龙鍾應是分，水曹芸閣枉来篇。"]', '诗', 'shi', '', NULL, '詶張籍王建 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('570100e7-dd0c-4162-9564-6cc67ee6b16a', '逢博陵故人彭兵曹', '逢博陵故人彭兵曹', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["曲陽分散會京華，見說三年住海涯。","別後解餐蓬虆子，向前未識牡丹花。","偶逢日者敎求祿，終傍泉聲擬置家。","蹋雪攜琴相就宿，夜深開戶斗牛斜。"]', '["曲陽分散會京华，见说三年住海涯。","別後解餐蓬虆子，向前未識牡丹花。","偶逢日者敎求祿，終傍泉声擬置家。","蹋雪携琴相就宿，夜深开戶斗牛斜。"]', '诗', 'shi', '', NULL, '逢博陵故人彭兵曹 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22d7340e-94bc-4f5f-a5ad-7d5efb23a72e', '贈牛山人', '贈牛山人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["二十年中餌茯苓，致書半是老君經。","東都舊住商人宅，南國新修道士亭。","鑿石養蜂休買蜜，坐山秤藥不爭星。","古來隱者多能卜，欲就先生問丙丁。"]', '["二十年中餌茯苓，致书半是老君經。","东都旧住商人宅，南国新修道士亭。","鑿石養蜂休買蜜，坐山秤藥不爭星。","古来隐者多能卜，欲就先生问丙丁。"]', '诗', 'shi', '', NULL, '贈牛山人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2caaa2-7ac0-45df-b883-7b8de963ccc5', '送于中丞使回紇冊立', '送于中丞使回紇冊立', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["君立天驕發使車，冊文字字著金書。","漸通青塚鄉山盡，欲達皇情譯語初。","調角寒城邊色動，下霜秋磧鴈行疎。","旌旗來往幾多日，應向途中見歲除。"]', '["君立天驕發使车，冊文字字著金书。","漸通青塚乡山尽，欲達皇情譯語初。","調角寒城邊色动，下霜秋磧鴈行疎。","旌旗来往幾多日，應向途中见歲除。"]', '诗', 'shi', '', NULL, '送于中丞使回紇冊立 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb829964-dd5a-4cf5-8b0b-76da1891e2cd', '送劉侍御重使江西', '送劉侍御重使江西', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["時當苦熱遠行人，石壁飛泉濺馬身。","又到鍾陵知務大，還浮湓浦屬秋新。","早程猨呌雲深極，宿館禽驚葉動頻。","前者已聞廉使薦，兼言有畫靜邊塵。"]', '["时當苦熱远行人，石壁飞泉濺马身。","又到鍾陵知務大，還浮湓浦屬秋新。","早程猨呌云深極，宿館禽驚葉动頻。","前者已闻廉使薦，兼言有畫静邊塵。"]', '诗', 'shi', '', NULL, '送劉侍御重使江西 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6b8454d-8c53-446a-86f6-75c5480a6d6b', '贈圓上人', '贈圓上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["誦經千紙得爲僧，麈尾持行不拂蠅。","古塔月高聞呪水，新壇日午見燒燈。","一雙童子澆紅藥，百八真珠貫綵繩。","且說近來心裏事，仇讎相對似親朋。"]', '["誦經千紙得爲僧，麈尾持行不拂蠅。","古塔月高闻呪水，新壇日午见燒灯。","一雙童子澆紅藥，百八真珠貫綵繩。","且说近来心裏事，仇讎相对似親朋。"]', '诗', 'shi', '', NULL, '贈圓上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f3761d5-9e2e-418f-ad19-1c505cd31839', '處州李使君改任遂州因寄贈', '处州李使君改任遂州因寄贈', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["庭樹幾株陰入戶，主人何在客聞蟬。","鑰開原上高樓鎖，瓶汲池東古井泉。","趂靜野禽曾後到，休吟鄰叟始安眠。","仙都山水誰能憶，西去風濤書滿船。"]', '["庭樹幾株陰入戶，主人何在客闻蟬。","鑰开原上高楼鎖，瓶汲池东古井泉。","趂静野禽曾後到，休吟鄰叟始安眠。","仙都山水誰能憶，西去风濤书满船。"]', '诗', 'shi', '', NULL, '處州李使君改任遂州因寄贈 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f921067-eb63-4575-85e6-6dc5f1f0841c', '酬慈恩寺文郁上人', '酬慈恩寺文郁上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["袈裟影入禁池清，猶憶鄉山近赤城。","籬落罅間寒蟹過，莓苔石上晚蛩行。","期登野閣閑應甚，阻宿山房疾未平。","聞說又尋南岳去，無端詩思忽然生。"]', '["袈裟影入禁池清，猶憶乡山近赤城。","籬落罅间寒蟹過，莓苔石上晚蛩行。","期登野閣闲應甚，阻宿山房疾未平。","闻说又尋南岳去，無端诗思忽然生。"]', '诗', 'shi', '', NULL, '酬慈恩寺文郁上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d3c5fed-5305-4b58-97fa-ee458ae5eee0', '訪鑒玄師姪', '訪鑒玄師姪', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["維摩青石講初休，緣訪親宗到普州。","我有軍持憑弟子，岳陽溪裏汲寒流。"]', '["維摩青石講初休，緣訪親宗到普州。","我有軍持憑弟子，岳陽溪裏汲寒流。"]', '诗', 'shi', '', NULL, '訪鑒玄師姪 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f220a485-b9cf-44ee-92ac-9dfd9e52b51c', '夜坐', '夜坐', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["蟋蟀漸多秋不淺，蟾蜍已沒夜應深。","三更兩鬢幾枝雪，一念雙峰四祖心。"]', '["蟋蟀漸多秋不淺，蟾蜍已沒夜應深。","三更兩鬢幾枝雪，一念雙峰四祖心。"]', '诗', 'shi', '', NULL, '夜坐 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0c4e0c4-801a-422b-b20d-3b75910570eb', '送別', '送別', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["門外便伸千里別，無車不得到河梁。","高樓直上百餘尺，今日爲君南望長。"]', '["门外便伸千里別，無车不得到河梁。","高楼直上百餘尺，今日爲君南望长。"]', '诗', 'shi', '', NULL, '送別 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97ad574a-7895-4d98-adbc-08c621f7f48c', '聞蟬感懷', '闻蟬感懷', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["新蟬忽發最高枝，不覺立聽無限時。","正遇友人來告別，一心分作兩般悲。"]', '["新蟬忽發最高枝，不覺立听無限时。","正遇友人来告別，一心分作兩般悲。"]', '诗', 'shi', '', NULL, '聞蟬感懷 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b676f4-ff69-42d6-9325-5b7d3f9a63e1', '夏夜上谷宿開元寺', '夏夜上谷宿开元寺', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["詩成一夜月中題，便臥松風到曙雞。","帶月時聞山鳥語，郡城知近武陵溪。"]', '["诗成一夜月中題，便臥松风到曙雞。","带月时闻山鸟語，郡城知近武陵溪。"]', '诗', 'shi', '', NULL, '夏夜上谷宿開元寺 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8325674d-a4a3-447c-b828-4d5d41c8ac03', '送于總持歸京', '送于總持归京', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["出家初隷何方寺，上國西明御水東。","却見舊房堦下樹，別來二十一春風。"]', '["出家初隷何方寺，上国西明御水东。","却见旧房堦下樹，別来二十一春风。"]', '诗', 'shi', '', NULL, '送于總持歸京 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('172ac0dc-f264-4c00-ba3b-213ca0d6d916', '崔卿池上鶴', '崔卿池上鹤', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["月中時呌葉紛紛，不異洞庭霜夜聞。","翎羽如今從放長，猶能飛起向孤雲。"]', '["月中时呌葉紛紛，不異洞庭霜夜闻。","翎羽如今從放长，猶能飞起向孤云。"]', '诗', 'shi', '', NULL, '崔卿池上鶴 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e30d6701-1d8a-4d9b-95ea-325f5065eda5', '登田中丞高亭', '登田中丞高亭', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["高亭林表迥嵯峨，獨坐秋宵不寢多。","玉兔玉人歌裏出，白雲難似莫相和。"]', '["高亭林表迥嵯峨，独坐秋宵不寢多。","玉兔玉人歌裏出，白云难似莫相和。"]', '诗', 'shi', '', NULL, '登田中丞高亭 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4d56c7c-df1f-4dc1-9637-1a594faef343', '友人婚楊氏催妝', '友人婚楊氏催妝', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["不知今夕是何夕，催促陽臺近鏡臺。","誰道芙蓉水中種，青銅鏡裏一枝開。"]', '["不知今夕是何夕，催促陽台近镜台。","誰道芙蓉水中種，青銅镜裏一枝开。"]', '诗', 'shi', '', NULL, '友人婚楊氏催妝 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e71b6625-f5ea-496a-967a-75e294b41406', '酬朱侍御望月見寄', '酬朱侍御望月见寄', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["他寢此時吾不寢，近秋三五日逢晴。","相思唯有霜臺月，望盡孤光見却生。"]', '["他寢此时吾不寢，近秋三五日逢晴。","相思唯有霜台月，望尽孤光见却生。"]', '诗', 'shi', '', NULL, '酬朱侍御望月見寄 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('363b8932-110c-4914-9908-1cbc43c9dc69', '題韋雲叟草堂', '題韋云叟草堂', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["新起此堂開北窗，當窗山隔一重江。","白茅草苫重重密，愛此秋天夜雨淙。"]', '["新起此堂开北窗，當窗山隔一重江。","白茅草苫重重密，愛此秋天夜雨淙。"]', '诗', 'shi', '', NULL, '題韋雲叟草堂 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fbb8ad9-85d1-4e8c-af90-10c309744ac3', '和韓吏部泛南溪', '和韓吏部泛南溪', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["溪裏晚從池岸出，石泉秋急夜深聞。","木蘭船共山人上，月映渡頭零落雲。"]', '["溪裏晚從池岸出，石泉秋急夜深闻。","木蘭船共山人上，月映渡头零落云。"]', '诗', 'shi', '', NULL, '和韓吏部泛南溪 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8593c7b-a58c-4f96-9b69-1b7f30b9b58d', '方鏡', '方镜', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["背如刀截機頭錦，面似升量澗底泉。","銅雀臺南秋日後，照來照去已三年。"]', '["背如刀截機头錦，面似升量澗底泉。","銅雀台南秋日後，照来照去已三年。"]', '诗', 'shi', '', NULL, '方鏡 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbae4436-47c4-4df0-81ad-062bab528c81', '詶姚合', '詶姚合', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["黍穗豆苗侵古道，晴原午後早秋時。","故人相憶僧來說，楊柳無風蟬滿枝。"]', '["黍穗豆苗侵古道，晴原午後早秋时。","故人相憶僧来说，楊柳無风蟬满枝。"]', '诗', 'shi', '', NULL, '詶姚合 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a94fc010-0cd4-462a-a738-53245b9442a1', '送靈應上人', '送靈應上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["遍參尊宿遊方久，名岳奇峰問此公。","五月半間看瀑布，青城山裏白雲中。"]', '["遍參尊宿游方久，名岳奇峰问此公。","五月半间看瀑布，青城山裏白云中。"]', '诗', 'shi', '', NULL, '送靈應上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c2326d-0fb5-4188-979c-332a54ceea94', '贈丘先生', '贈丘先生', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["常言喫藥全勝飯，華岳松邊採茯神。","不遣髭鬚一莖白，擬爲白日上昇人。"]', '["常言喫藥全勝飯，华岳松邊採茯神。","不遣髭鬚一莖白，擬爲白日上昇人。"]', '诗', 'shi', '', NULL, '贈丘先生 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89ef4498-db55-4011-b531-c9f49b8ec723', '渡桑乾', '渡桑乾', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["客舍幷州已十霜，歸心日夜憶咸陽。","無端更渡桑乾水，却望幷州是故鄉。"]', '["客舍幷州已十霜，归心日夜憶咸陽。","無端更渡桑乾水，却望幷州是故乡。"]', '诗', 'shi', '', NULL, '渡桑乾 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73498ff0-87e4-4229-ae32-531fdc32c339', '夜期嘯客呂逸人不至', '夜期嘯客呂逸人不至', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["逸人期宿石牀中，遣我開扉對晚空。","不知何處嘯秋月，閑著松門一夜風。"]', '["逸人期宿石牀中，遣我开扉对晚空。","不知何处嘯秋月，闲著松门一夜风。"]', '诗', 'shi', '', NULL, '夜期嘯客呂逸人不至 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81eb208-19b7-4d0f-97c8-fada6606d205', '夜集烏行中所居', '夜集烏行中所居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["環爐促席復持杯，松院雙扉向月開。","座上同聲半先達，名山獨入此心來。"]', '["环爐促席复持杯，松院雙扉向月开。","座上同声半先達，名山独入此心来。"]', '诗', 'shi', '', NULL, '夜集烏行中所居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ebfe239-c6b5-4a84-9f9c-8ade495d1521', '贈梁浦秀才斑竹拄杖', '贈梁浦秀才斑竹拄杖', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["揀得林中最細枝，結根石上長身遲。","莫嫌滴瀝紅斑少，恰似湘妃淚盡時。"]', '["揀得林中最細枝，結根石上长身遲。","莫嫌滴瀝紅斑少，恰似湘妃泪尽时。"]', '诗', 'shi', '', NULL, '贈梁浦秀才斑竹拄杖 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cd53d54-86dd-439a-a5fe-b09f2c181b47', '尋石甕寺上方', '尋石甕寺上方', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["野寺入時春雪後，崎嶇得到此房前。","老僧不出迎朝客，已住上方三十年。"]', '["野寺入时春雪後，崎嶇得到此房前。","老僧不出迎朝客，已住上方三十年。"]', '诗', 'shi', '', NULL, '尋石甕寺上方 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcabcef4-8664-48db-aa56-9d13c10c72a1', '早秋寄題天竺靈隱寺', '早秋寄題天竺靈隐寺', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["峰前峰後寺新秋，絕頂高窗見沃洲。","人在定中聞蟋蟀，鶴從棲處挂獼猴。","山鐘夜渡空江水，汀月寒生古石樓。","心憶懸帆身未遂，謝公此地昔年遊。"]', '["峰前峰後寺新秋，絕頂高窗见沃洲。","人在定中闻蟋蟀，鹤從棲处挂獼猴。","山鐘夜渡空江水，汀月寒生古石楼。","心憶懸帆身未遂，謝公此地昔年游。"]', '诗', 'shi', '', NULL, '早秋寄題天竺靈隱寺 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e980ce8b-0977-4361-a9b6-ab7923c63c2b', '黎陽寄姚合', '黎陽寄姚合', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["魏都城裏曾遊熟，才子齋中止泊多。","去日綠楊垂紫陌，歸時白草夾黃河。","新詩不覺千迴詠，古鏡曾經幾度磨。","惆悵心思滑臺北，滿杯濃酒與愁和。"]', '["魏都城裏曾游熟，才子斋中止泊多。","去日綠楊垂紫陌，归时白草夾黄河。","新诗不覺千迴詠，古镜曾經幾度磨。","惆悵心思滑台北，满杯濃酒與愁和。"]', '诗', 'shi', '', NULL, '黎陽寄姚合 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b463925b-db0a-4a6c-8dbe-841b2fc0ef39', '送崔約秀才', '送崔約秀才', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["歸寧髣髴三千里，月向船窗見幾宵。","野鼠獨偷高樹果，前山漸見短禾苗。","更深柵鎖淮波疾，葦動風生雨氣遙。","重入石頭城下寺，南朝杉老未乾燋。"]', '["归寧髣髴三千里，月向船窗见幾宵。","野鼠独偷高樹果，前山漸见短禾苗。","更深柵鎖淮波疾，葦动风生雨氣遙。","重入石头城下寺，南朝杉老未乾燋。"]', '诗', 'shi', '', NULL, '送崔約秀才 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9569ee4-9de8-42bc-bf26-49e45c131651', '詠懷', '詠懷', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["縱把書看未省勤，一生生計秖長貧。","可能在世無成事，不覺離家作老人。","中嶽深林秋獨往，南原多草夜無鄰。","經年抱疾誰來問，野鳥相過啄木頻。"]', '["縱把书看未省勤，一生生計秖长貧。","可能在世無成事，不覺離家作老人。","中嶽深林秋独往，南原多草夜無鄰。","經年抱疾誰来问，野鸟相過啄木頻。"]', '诗', 'shi', '', NULL, '詠懷 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37bf2ec4-65ce-482d-a196-f3ddb690dd28', '夏日寄高洗馬', '夏日寄高洗马', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["三十年來長在客，兩三行淚忽然垂。","白衣蒼鬢經過嬾，赤日朱門偃息遲。","花發應耽新熟酒，草顛還寫早朝詩。","不緣馬死西州去，畫角堪聽是曉吹。"]', '["三十年来长在客，兩三行泪忽然垂。","白衣蒼鬢經過嬾，赤日朱门偃息遲。","花發應耽新熟酒，草顛還寫早朝诗。","不緣马死西州去，畫角堪听是晓吹。"]', '诗', 'shi', '', NULL, '夏日寄高洗馬 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f56545-b2b9-4c61-a498-a0a23c0c6542', '送周判官元範赴越', '送周判官元範赴越', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["原下相逢便別離，蟬鳴關路使迴時。","過淮漸有懸帆興，到越應將墜葉期。","城上秋山生菊早，驛西寒渡落潮遲。","已曾幾遍隨旌斾，去謁荒郊大禹祠。"]', '["原下相逢便別離，蟬鳴关路使迴时。","過淮漸有懸帆兴，到越應將墜葉期。","城上秋山生菊早，驛西寒渡落潮遲。","已曾幾遍隨旌斾，去謁荒郊大禹祠。"]', '诗', 'shi', '', NULL, '送周判官元範赴越 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b59434e-c8cf-4069-992f-fd1bd734fbb5', '送羅少府歸牛渚', '送羅少府归牛渚', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["作尉長安始三日，忽思牛渚夢天台。","楚山遠色獨歸去，灞水空流相送回。","霜覆鶴身松子落，月分螢影石房開。","白雲多處應頻到，寒澗泠泠漱古苔。"]', '["作尉长安始三日，忽思牛渚梦天台。","楚山远色独归去，灞水空流相送回。","霜覆鹤身松子落，月分螢影石房开。","白云多处應頻到，寒澗泠泠漱古苔。"]', '诗', 'shi', '', NULL, '送羅少府歸牛渚 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb3e2e1e-d92a-472c-9ae7-641921da44e3', '題童真上人', '題童真上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["江上修持積歲年，灘聲未擬住潺湲。","誓從五十身披衲，便向三千界坐禪。","月峽青城那有滯，天台廬岳豈無緣。","昨宵忽夢遊滄海，萬里波濤在目前。"]', '["江上修持積歲年，灘声未擬住潺湲。","誓從五十身披衲，便向三千界坐禪。","月峽青城那有滯，天台廬岳豈無緣。","昨宵忽梦游滄海，万里波濤在目前。"]', '诗', 'shi', '', NULL, '題童真上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e28c9090-68c5-4f47-8dd4-af0996ce8f21', '贈溫觀主', '贈溫观主', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["一別羅浮竟未還，觀深廊古院多關。","君來幾日行虛洞，仙去空壇在遠山。","胎息存思當黑處，井華懸綆取朝間。","弊廬道室雖鄰近，自樂冬陽炙背閑。"]', '["一別羅浮竟未還，观深廊古院多关。","君来幾日行虛洞，仙去空壇在远山。","胎息存思當黑处，井华懸綆取朝间。","弊廬道室雖鄰近，自乐冬陽炙背闲。"]', '诗', 'shi', '', NULL, '贈溫觀主 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92623899-f54d-4c7a-9f2a-12e8d910465d', '賀龐少尹除太常少卿', '賀龐少尹除太常少卿', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["太白山前終日見，十旬假滿擬秋尋。","中峰絕頂非無路，北闕除書阻入林。","朝謁此時閑野屐，宿齋何處止鳴砧？","省中石鐙陪隨步，唯賞煙霞不厭深。"]', '["太白山前終日见，十旬假满擬秋尋。","中峰絕頂非無路，北闕除书阻入林。","朝謁此时闲野屐，宿斋何处止鳴砧？","省中石鐙陪隨步，唯賞煙霞不厭深。"]', '诗', 'shi', '', NULL, '賀龐少尹除太常少卿 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dda96013-c1b9-45a1-8931-c179a70ae5f9', '上邠寧邢司徒', '上邠寧邢司徒', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["箭頭破帖渾無敵，杖底敲毬遠有聲。","馬走千蹄朝萬乘，地分三郡擁雙旌。","春風欲盡山花發，曉角初吹客夢驚。","不是邢公來鎮此，長安西北未能行。"]', '["箭头破帖渾無敵，杖底敲毬远有声。","马走千蹄朝万乘，地分三郡擁雙旌。","春风欲尽山花發，晓角初吹客梦驚。","不是邢公来鎮此，长安西北未能行。"]', '诗', 'shi', '', NULL, '上邠寧邢司徒 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24557993-a632-4a04-8260-9477252f3506', '欲遊嵩岳留別李少尹益', '欲游嵩岳留別李少尹益', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["孤策遲迴洛水湄，孤禽嘹唳幸人知。","嵩岳望中常待我，河梁欲上未題詩。","新秋愛月愁多雨，古觀逢仙看盡棋。","微眇此來將敢問，鳳凰何日定歸池。"]', '["孤策遲迴洛水湄，孤禽嘹唳幸人知。","嵩岳望中常待我，河梁欲上未題诗。","新秋愛月愁多雨，古观逢仙看尽棋。","微眇此来將敢问，鳳凰何日定归池。"]', '诗', 'shi', '', NULL, '欲遊嵩岳留別李少尹益 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('442b31d4-0c7e-4e45-820f-edb5f62f27f6', '病鶻吟', '病鶻吟', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["俊鳥還投高處栖，騰身戛戛下雲梯。","有時透霧凌空去，無事隨風入草迷。","迅疾月邊捎玉兔，遲迴日裏拂金雞。","不緣毛羽遭零落，焉肯雄心向爾低。"]', '["俊鸟還投高处栖，腾身戛戛下云梯。","有时透霧凌空去，無事隨风入草迷。","迅疾月邊捎玉兔，遲迴日裏拂金雞。","不緣毛羽遭零落，焉肯雄心向爾低。"]', '诗', 'shi', '', NULL, '病鶻吟 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6df361-6f48-42e9-be2e-cbfb6e8d3564', '贈僧', '贈僧', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["從來多是遊山水，省泊禪舟月下濤。","初過石橋年尚少，久辭天柱臘應高。","青松帶雪懸銅錫，白髮如霜落鐵刀。","常恐畫工援筆寫，身長七尺有眉毫。"]', '["從来多是游山水，省泊禪舟月下濤。","初過石橋年尚少，久辞天柱臘應高。","青松带雪懸銅錫，白髮如霜落鐵刀。","常恐畫工援笔寫，身长七尺有眉毫。"]', '诗', 'shi', '', NULL, '贈僧 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0ceccdb-f542-46cd-9331-052937e7bbe0', '贈翰林', '贈翰林', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["清重無過知內制，從前禮絕外庭人。","看花在處多隨駕，召宴無時不及身。","馬自賜來騎覺穩，詩緣見徹語長新。","應憐獨向名場苦，曾十餘年浪過春。"]', '["清重無過知內制，從前禮絕外庭人。","看花在处多隨駕，召宴無时不及身。","马自賜来騎覺穩，诗緣见徹語长新。","應怜独向名場苦，曾十餘年浪過春。"]', '诗', 'shi', '', NULL, '贈翰林 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63284c9b-55c9-4757-94c0-f3ec7f79bc21', '頌德上賈常侍', '頌德上賈常侍', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["邊臣說使朝天子，發語轟然激夏雷。","高節羽書期獨傳，分符絳郡滯長材。","啁啾鳥恐鷹鸇起，流散人歸父母來。","自顧此身無所立，恭談祖德朵頤開。"]', '["邊臣说使朝天子，發語轟然激夏雷。","高節羽书期独傳，分符絳郡滯长材。","啁啾鸟恐鷹鸇起，流散人归父母来。","自顧此身無所立，恭談祖德朵頤开。"]', '诗', 'shi', '', NULL, '頌德上賈常侍 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d2edcb0-f992-4d49-8aa6-56fd4c8e7725', '田將軍書院', '田將軍书院', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["滿庭花木半新栽，石自平湖遠岸來。","筍迸鄰家還長竹，地經山雨幾層苔。","井當深夜泉微上，閣入高秋戶盡開。","行背曲江誰到此，琴書鎖著未朝迴。"]', '["满庭花木半新栽，石自平湖远岸来。","筍迸鄰家還长竹，地經山雨幾層苔。","井當深夜泉微上，閣入高秋戶尽开。","行背曲江誰到此，琴书鎖著未朝迴。"]', '诗', 'shi', '', NULL, '田將軍書院 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a0a3c22-a5bb-482f-8380-0eeee3258d3f', '投龐少尹', '投龐少尹', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["閉戶息機搔白首，中庭一樹有清陰。","年年不改風塵趣，日日轉多泉石心。","病起望山臺上立，覺來聽雨燭前吟。","龐公相識元和歲，眷分依依直至今。"]', '["閉戶息機搔白首，中庭一樹有清陰。","年年不改风塵趣，日日轉多泉石心。","病起望山台上立，覺来听雨燭前吟。","龐公相識元和歲，眷分依依直至今。"]', '诗', 'shi', '', NULL, '投龐少尹 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff4b7e44-8cc5-43e2-93b4-8c5eaf86e0be', '夏夜登南樓', '夏夜登南楼', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["水岸寒樓帶月躋，夏林初見岳陽溪。","一㸃新螢報秋信，不知何處是菩提。"]', '["水岸寒楼带月躋，夏林初见岳陽溪。","一㸃新螢報秋信，不知何处是菩提。"]', '诗', 'shi', '', NULL, '夏夜登南樓 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f43b52da-d474-4712-92e0-cd619dcdf49f', '題青龍寺', '題青龙寺', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["碣石山人一軸詩，終南山北數人知。","擬看青龍寺裏月，待無一點夜雲時。"]', '["碣石山人一軸诗，終南山北數人知。","擬看青龙寺裏月，待無一点夜云时。"]', '诗', 'shi', '', NULL, '題青龍寺 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54e48a8e-9032-4b01-8c8f-cbc17bc1df06', '贈李文通', '贈李文通', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["營當萬勝岡頭下，誓立千年不朽功。","天子手擎新鉞斧，諫官請贈李文通。"]', '["營當万勝岡头下，誓立千年不朽功。","天子手擎新鉞斧，諫官請贈李文通。"]', '诗', 'shi', '', NULL, '贈李文通 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b433d2de-3186-43a7-8af7-65497fb0f9ab', '題虢州三堂贈吳郎中', '題虢州三堂贈吳郎中', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["無窮草樹昔誰栽，新起臨湖白石臺。","半岸泥沙孤鶴立，三堂風雨四門開。","荷翻團露驚秋近，柳轉斜陽過水來。","昨夜北樓堪朗詠，虢城初鎖月裴回。"]', '["無窮草樹昔誰栽，新起臨湖白石台。","半岸泥沙孤鹤立，三堂风雨四门开。","荷翻團露驚秋近，柳轉斜陽過水来。","昨夜北楼堪朗詠，虢城初鎖月裴回。"]', '诗', 'shi', '', NULL, '題虢州三堂贈吳郎中 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f015d3d-d269-4ac4-b181-32aa8635b0f8', '送僧', '送僧', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["池上時時松雪落，焚香煙起見孤燈。","靜夜憶誰來對坐，曲江南岸寺中僧。"]', '["池上时时松雪落，焚香煙起见孤灯。","静夜憶誰来对坐，曲江南岸寺中僧。"]', '诗', 'shi', '', NULL, '送僧 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d3133e-3019-4178-99d9-fe02bfc5c8d2', '三月晦日贈劉評事', '三月晦日贈劉評事', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["三月正當三十日，風光別我苦吟身。","共君今夜不須睡，未到曉鐘猶是春。"]', '["三月正當三十日，风光別我苦吟身。","共君今夜不須睡，未到晓鐘猶是春。"]', '诗', 'shi', '', NULL, '三月晦日贈劉評事 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b01872c-7a21-44e6-841f-2d6664c0570a', '送張道者', '送張道者', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["新歲抱琴何處去，洛陽三十六峰西。","生來未識山人面，不得一聽烏夜啼。"]', '["新歲抱琴何处去，洛陽三十六峰西。","生来未識山人面，不得一听烏夜啼。"]', '诗', 'shi', '', NULL, '送張道者 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9783c660-9f08-4d74-86f3-37490cd51315', '題魚尊師院', '題鱼尊師院', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["老子堂前花萬樹，先生曾見幾迴春。","夜煎白石平明喫，不擬敎人哭此身。"]', '["老子堂前花万樹，先生曾见幾迴春。","夜煎白石平明喫，不擬敎人哭此身。"]', '诗', 'shi', '', NULL, '題魚尊師院 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34c7501c-ceec-4cb0-81fe-a330770c1e57', '宿村家亭子', '宿村家亭子', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["牀頭枕是溪中石，井底泉通竹下池。","宿客未眠過夜半，獨聞山雨到來時。"]', '["牀头枕是溪中石，井底泉通竹下池。","宿客未眠過夜半，独闻山雨到来时。"]', '诗', 'shi', '', NULL, '宿村家亭子 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef551c0-e97a-45d0-9347-954c5a3ccd4e', '送稱上人', '送稱上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["歸蜀擬從巫峽過，何時得入舊房禪。","寺中來後誰身化，起塔栽松向野田。"]', '["归蜀擬從巫峽過，何时得入旧房禪。","寺中来後誰身化，起塔栽松向野田。"]', '诗', 'shi', '', NULL, '送稱上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1297ee3c-04a7-4db1-828c-a46976f2b8f1', '楊祕書新居', '楊祕书新居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["城角新居鄰靜寺，時從新閣上經樓。","南山泉入宮中去，先向詩人門外流。"]', '["城角新居鄰静寺，时從新閣上經楼。","南山泉入宮中去，先向诗人门外流。"]', '诗', 'shi', '', NULL, '楊祕書新居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fefce49d-d646-459b-848a-901eb3839979', '聽樂山人彈易水', '听乐山人彈易水', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["朱絲弦底燕泉急，燕將雲孫白日彈。","嬴氏歸山陵已掘，聲聲猶帶髮衝冠。"]', '["朱絲弦底燕泉急，燕將云孫白日彈。","嬴氏归山陵已掘，声声猶带髮衝冠。"]', '诗', 'shi', '', NULL, '聽樂山人彈易水 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b1eaa81-600a-479f-b574-fa7cfb9c762e', '經蘇秦墓', '經蘇秦墓', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["沙埋古篆折碑文，六國興亡事繫君。","今日淒涼無處說，亂山秋盡有寒雲。"]', '["沙埋古篆折碑文，六国兴亡事繫君。","今日淒涼無处说，亂山秋尽有寒云。"]', '诗', 'shi', '', NULL, '經蘇秦墓 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37709253-66f8-47a5-9867-1c5f995acee3', '題戴勝', '題戴勝', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["星點花冠道士衣，紫陽宮女化身飛。","能傳上界春消息，若到蓬山莫放歸。"]', '["星点花冠道士衣，紫陽宮女化身飞。","能傳上界春消息，若到蓬山莫放归。"]', '诗', 'shi', '', NULL, '題戴勝 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f4685d-bbac-4c17-bdcb-4b7cd0a1f791', '題隱者居', '題隐者居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["雖有柴門常不關，片雲孤木伴身閑。","猶嫌住久人知處，見擬移家更上山。"]', '["雖有柴门常不关，片云孤木伴身闲。","猶嫌住久人知处，见擬移家更上山。"]', '诗', 'shi', '', NULL, '題隱者居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('844d0a76-b26f-4627-ac69-a893cec76b0e', '哭孟東野', '哭孟东野', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["蘭無香氣鶴無聲，哭盡秋天月不明。","自從東野先生死，側近雲山得散行。"]', '["蘭無香氣鹤無声，哭尽秋天月不明。","自從东野先生死，側近云山得散行。"]', '诗', 'shi', '', NULL, '哭孟東野 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c2ecc0-7b90-43da-a1c6-820252d48eb8', '過京索先生墳', '過京索先生墳', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["京索先生三尺墳，秋風漠漠吐寒雲。","從來有恨君多哭，今日何人更哭君。"]', '["京索先生三尺墳，秋风漠漠吐寒云。","從来有恨君多哭，今日何人更哭君。"]', '诗', 'shi', '', NULL, '過京索先生墳 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f7eca7-c17b-4d82-8384-38c3e7c328bb', '客思', '客思', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["促織聲尖尖似針，更深刺著旅人心。","獨言獨語月明裏，驚覺眠童與宿禽。"]', '["促织声尖尖似針，更深刺著旅人心。","独言独語月明裏，驚覺眠童與宿禽。"]', '诗', 'shi', '', NULL, '客思 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1c01e1b-eb4f-4e7f-8a5b-dfa71145e483', '鹽池院觀鹿', '鹽池院观鹿', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["條峰五老勢相連，此鹿來從若箇邊。","別有野麋人不見，一生長飲白雲泉。"]', '["條峰五老勢相連，此鹿来從若箇邊。","別有野麋人不见，一生长饮白云泉。"]', '诗', 'shi', '', NULL, '鹽池院觀鹿 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e2ef634-8a82-4cb0-b469-ad3e2f03018d', '黃鵠下太液池', '黄鵠下太液池', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["高飛空外鵠，下向禁中池。","岸印行蹤淺，波搖立影危。","來從千里島，舞拂萬年枝。","踉蹌孤風起，裴回水沫移。","幽音清露滴，野性白雲隨。","太液無彈射，靈禽翅不垂。"]', '["高飞空外鵠，下向禁中池。","岸印行蹤淺，波搖立影危。","来從千里島，舞拂万年枝。","踉蹌孤风起，裴回水沫移。","幽音清露滴，野性白云隨。","太液無彈射，靈禽翅不垂。"]', '诗', 'shi', '', NULL, '黃鵠下太液池 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61e12a1-8c99-4ae1-bdd7-3cc7022c1266', '代舊將', '代旧將', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["舊事說如夢，誰當信老夫。","戰場幾處在，部曲一人無。","落日收病馬，晴天曬陣圖。","猶希聖朝用，自鑷白髭鬚。"]', '["旧事说如梦，誰當信老夫。","戰場幾处在，部曲一人無。","落日收病马，晴天曬陣圖。","猶希聖朝用，自鑷白髭鬚。"]', '诗', 'shi', '', NULL, '代舊將 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d33e6652-56be-4268-aa9d-e7e487352970', '老將', '老將', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["膽壯亂鬚白，金瘡蠹百骸。","旌旗猶入夢，歌舞不開懷。","燕雀來鷹架，塵埃滿箭靫。","自誇勳業重，開府是官階。"]', '["膽壯亂鬚白，金瘡蠹百骸。","旌旗猶入梦，歌舞不开懷。","燕雀来鷹架，塵埃满箭靫。","自誇勳業重，开府是官階。"]', '诗', 'shi', '', NULL, '老將 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc3282c-e9fa-4052-b52c-fd3c9561e9e4', '春行', '春行', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["去去行人遠，塵隨馬不窮。","旅情斜日後，春色早煙中。","流水穿空館，閑花發故宮。","舊鄉千里思，池上綠楊風。"]', '["去去行人远，塵隨马不窮。","旅情斜日後，春色早煙中。","流水穿空館，闲花發故宮。","旧乡千里思，池上綠楊风。"]', '诗', 'shi', '', NULL, '春行 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e63e4109-37bc-4567-9b90-c79b5f1f409c', '題鄭常侍廳前竹', '題鄭常侍廳前竹', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["綠竹臨詩酒，嬋娟思不窮。","亂枝低積雪，繁葉亞寒風。","蕭颯疑泉過，縈迴有逕通。","侵庭根出土，隔壁筍成叢。","疎影紗窗外，清音寶瑟中。","卷簾終日看，欹枕幾秋同。","萬頃歌王子，千竿伴阮公。","露光憐片片，雨潤愛濛濛。","嶰谷蠻湖北，湘川灀水東。","何如軒檻側，蒼翠褭長空。"]', '["綠竹臨诗酒，嬋娟思不窮。","亂枝低積雪，繁葉亞寒风。","蕭颯疑泉過，縈迴有逕通。","侵庭根出土，隔壁筍成叢。","疎影紗窗外，清音寶瑟中。","卷簾終日看，欹枕幾秋同。","万頃歌王子，千竿伴阮公。","露光怜片片，雨潤愛濛濛。","嶰谷蠻湖北，湘川灀水东。","何如軒檻側，蒼翠褭长空。"]', '诗', 'shi', '', NULL, '題鄭常侍廳前竹 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6302604c-8e12-4e1e-8f0a-d2021f8fad00', '早行', '早行', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["早起赴前程，鄰雞尚未鳴。","主人燈下別，羸馬暗中行。","蹋石新霜滑，穿林宿鳥驚。","遠山鐘動後，曙色漸分明。"]', '["早起赴前程，鄰雞尚未鳴。","主人灯下別，羸马暗中行。","蹋石新霜滑，穿林宿鸟驚。","远山鐘动後，曙色漸分明。"]', '诗', 'shi', '', NULL, '早行 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56489b17-c484-467b-9956-c8bfdab8b687', '送人南歸', '送人南归', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["分手向天涯，迢迢泛海波。","雖然南地遠，見說北人多。","山暖花常發，秋深鴈不過。","炎方饒勝事，此去莫蹉跎。"]', '["分手向天涯，迢迢泛海波。","雖然南地远，见说北人多。","山暖花常發，秋深鴈不過。","炎方饒勝事，此去莫蹉跎。"]', '诗', 'shi', '', NULL, '送人南歸 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72536b70-ce00-4598-8818-a409527a18d4', '送人南遊', '送人南游', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["此別天涯遠，孤舟泛海中。","夜行常認火，帆去每因風。","蠻國人多富，炎方語不同。","鴈飛難度嶺，書信若爲通。"]', '["此別天涯远，孤舟泛海中。","夜行常認火，帆去每因风。","蠻国人多富，炎方語不同。","鴈飞难度嶺，书信若爲通。"]', '诗', 'shi', '', NULL, '送人南遊 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c80fd603-a4ef-4410-a4e5-221ced7c04e2', '送道者', '送道者', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["獨向山中見，今朝又別離。","一心無挂住，萬里獨何之。","到處絕煙火，逢人話古時。","此行無弟子，白犬自相隨。"]', '["独向山中见，今朝又別離。","一心無挂住，万里独何之。","到处絕煙火，逢人話古时。","此行無弟子，白犬自相隨。"]', '诗', 'shi', '', NULL, '送道者 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf7085d-c0f6-4a2b-b3a1-55472f356f14', '風蟬', '风蟬', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["風蟬旦夕鳴，伴葉送新聲。","故里客歸盡，水邊身獨行。","噪軒高樹合，驚枕暮山橫。","聽處無人見，塵埃滿甑生。"]', '["风蟬旦夕鳴，伴葉送新声。","故里客归尽，水邊身独行。","噪軒高樹合，驚枕暮山橫。","听处無人见，塵埃满甑生。"]', '诗', 'shi', '', NULL, '風蟬 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9965c0bc-cdc4-4c46-bc75-cbc600456505', '清明日園林寄友人', '清明日园林寄友人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["今日清明節，園林勝事偏。","晴風吹柳絮，新火起廚煙。","杜草開三逕，文章憶二賢。","幾時能命駕，對酒落花前。"]', '["今日清明節，园林勝事偏。","晴风吹柳絮，新火起廚煙。","杜草开三逕，文章憶二賢。","幾时能命駕，对酒落花前。"]', '诗', 'shi', '', NULL, '清明日園林寄友人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3efc3cf0-67fb-4e3d-8d01-9de558b43d13', '上杜駙馬', '上杜駙马', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["玉山突兀壓乾坤，出得朱門入戟門。","妻是九重天子女，身爲一品令公孫。","鴛鴦殿裏參皇后，龍鳳堂前賀至尊。","今日澧陽非久駐，佇爲霖雨拜新恩。"]', '["玉山突兀壓乾坤，出得朱门入戟门。","妻是九重天子女，身爲一品令公孫。","鴛鴦殿裏參皇后，龙鳳堂前賀至尊。","今日澧陽非久駐，佇爲霖雨拜新恩。"]', '诗', 'shi', '', NULL, '上杜駙馬 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('543f20a9-4178-4f2c-b280-cdf690cf93f8', '蓮峰歌', '蓮峰歌', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["錦礫潺湲玉溪水，曉來微雨藤花紫。","冉冉山雞紅尾長，一聲樵斧驚飛起。","松刺梳空石差齒，煙香風軟人參蕊。","陽崖一夢伴雲根，仙菌靈芝夢魂裏。"]', '["錦礫潺湲玉溪水，晓来微雨藤花紫。","冉冉山雞紅尾长，一声樵斧驚飞起。","松刺梳空石差齒，煙香风軟人參蕊。","陽崖一梦伴云根，仙菌靈芝梦魂裏。"]', '诗', 'shi', '', NULL, '蓮峰歌 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45f99d63-b306-40c3-8d4a-cf71c7057e51', '壯士吟', '壯士吟', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["壯士不曾悲，悲即無回期。","如何易水上，未歌先淚垂。"]', '["壯士不曾悲，悲即無回期。","如何易水上，未歌先泪垂。"]', '诗', 'shi', '', NULL, '壯士吟 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51943122-8340-42b6-be85-c36a901b9087', '題興化園亭', '題兴化园亭', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["破却千家作一池，不栽桃李種薔薇。","薔薇花落秋風起，荆棘滿庭君始知。"]', '["破却千家作一池，不栽桃李種薔薇。","薔薇花落秋风起，荆棘满庭君始知。"]', '诗', 'shi', '', NULL, '題興化園亭 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4860b7-5585-40aa-86ec-d4dbde20efb6', '竹', '竹', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["籬外清陰接藥欄，曉風交戛碧琅玕。","子猷沒後知音少，粉節霜筠漫歲寒。"]', '["籬外清陰接藥欄，晓风交戛碧琅玕。","子猷沒後知音少，粉節霜筠漫歲寒。"]', '诗', 'shi', '', NULL, '竹 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73bb067c-775a-44c7-a367-27f9080ec92b', '李斯井', '李斯井', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["井存上蔡南門外，置此井時來相秦。","斷綆數尋垂古甃，取將寒水是何人。"]', '["井存上蔡南门外，置此井时来相秦。","斷綆數尋垂古甃，取將寒水是何人。"]', '诗', 'shi', '', NULL, '李斯井 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('563c81a7-b98e-426c-bd78-2dc7e0939d3c', '題詩後', '題诗後', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["二句三年得，一吟雙淚流。","知音如不賞，歸臥故山秋。"]', '["二句三年得，一吟雙泪流。","知音如不賞，归臥故山秋。"]', '诗', 'shi', '', NULL, '題詩後 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('471b6883-689e-407a-bc38-4ebc94ba3da9', '送友人之南陵', '送友人之南陵', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["莫歎徒勞向宦途，不羣氣岸有誰如。","南陵暫掌仇香印，北闕終行賈誼書。","好趂江山尋勝境，莫辭韋杜別幽居。","少年躍馬同心使，免得詩中道跨驢。"]', '["莫歎徒勞向宦途，不羣氣岸有誰如。","南陵暫掌仇香印，北闕終行賈誼书。","好趂江山尋勝境，莫辞韋杜別幽居。","少年躍马同心使，免得诗中道跨驢。"]', '诗', 'shi', '', NULL, '送友人之南陵 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8fd4040-6538-4696-89b5-1f65219f096f', '尋人不遇', '尋人不遇', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["聞說到揚州，吹簫有舊遊。","人來多不見，莫是上迷樓。"]', '["闻说到揚州，吹簫有旧游。","人来多不见，莫是上迷楼。"]', '诗', 'shi', '', NULL, '尋人不遇 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f6575cc-12cc-4986-8bfc-5cedac7bb68f', '尋隱者不遇', '尋隐者不遇', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["松下問童子，言師採藥去。","只在此山中，雲深不知處。"]', '["松下问童子，言師採藥去。","只在此山中，云深不知处。"]', '诗', 'shi', '', NULL, '尋隱者不遇 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca3bd849-1b60-4fe1-9825-ce24b1848af6', '行次漢上', '行次漢上', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["習家池沼草萋萋，嵐樹光中信馬蹄。","漢主廟前湘水碧，一聲風角夕陽低。"]', '["習家池沼草萋萋，嵐樹光中信马蹄。","漢主廟前湘水碧，一声风角夕陽低。"]', '诗', 'shi', '', NULL, '行次漢上 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c15631-b181-46bd-8815-96bc407b77df', '馬嵬', '马嵬', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["長川幾處樹青青，孤驛危樓對翠屏。","一自上皇惆悵後，至今來往馬蹄腥。"]', '["长川幾处樹青青，孤驛危楼对翠屏。","一自上皇惆悵後，至今来往马蹄腥。"]', '诗', 'shi', '', NULL, '馬嵬 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3252596-3479-4349-8080-ea61ff3be551', '冬夜送人', '冬夜送人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["平明走馬上村橋，花落梅溪雪未消。","日短天寒愁送客，楚山無限路迢迢。"]', '["平明走马上村橋，花落梅溪雪未消。","日短天寒愁送客，楚山無限路迢迢。"]', '诗', 'shi', '', NULL, '冬夜送人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d96c31-f4c6-49c6-9c68-872d584c5b74', '句', '句', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["晴風吹柳絮，新火起廚煙。","長江風送客，孤館雨留人。","古岸崩將盡，平沙長未休。","不如牛與羊，猶得日暮歸。"]', '["晴风吹柳絮，新火起廚煙。","长江风送客，孤館雨留人。","古岸崩將尽，平沙长未休。","不如牛與羊，猶得日暮归。"]', '诗', 'shi', '', NULL, '句 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fd87152-66cb-4ee9-9932-82b48cad138a', '雞鳴埭曲', '雞鳴埭曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["南朝天子射雉時，銀河耿耿星參差。","銅壺漏斷夢初覺，寶馬塵高人未知。","魚躍蓮東蕩宮沼，濛濛御柳懸棲鳥。","紅妝萬戶鏡中春，碧樹一聲天下曉。","盤踞勢窮三百年，朱方殺氣成愁煙。","彗星拂地浪連海，戰鼓渡江塵漲天。","繡龍畫雉填宮井，野火風驅燒九鼎。","殿巢江燕砌生蒿，十二金人霜炯炯。","芊綿平綠臺城基，暖色春容荒古陂。","寧知玉樹後庭曲，留待野棠如雪枝。"]', '["南朝天子射雉时，銀河耿耿星參差。","銅壺漏斷梦初覺，寶马塵高人未知。","鱼躍蓮东蕩宮沼，濛濛御柳懸棲鸟。","紅妝万戶镜中春，碧樹一声天下晓。","盤踞勢窮三百年，朱方殺氣成愁煙。","彗星拂地浪連海，戰鼓渡江塵漲天。","繡龙畫雉填宮井，野火风驱燒九鼎。","殿巢江燕砌生蒿，十二金人霜炯炯。","芊綿平綠台城基，暖色春容荒古陂。","寧知玉樹後庭曲，留待野棠如雪枝。"]', '诗', 'shi', '', NULL, '雞鳴埭曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('218ef7e6-38d1-4b4a-ad51-312bfd07cc90', '織錦詞', '织錦词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["丁東細漏侵瓊瑟，影轉高梧月初出。","簇簌金梭萬縷紅，鴛鴦豔錦初成匹。","錦中百結皆同心，蘂亂雲盤相間深。","此意欲傳傳不得，玫瑰作柱朱弦琴。","爲君裁破合歡被，星斗迢迢共千里。","象尺熏爐未覺秋，碧池已有新蓮子。"]', '["丁东細漏侵瓊瑟，影轉高梧月初出。","簇簌金梭万縷紅，鴛鴦豔錦初成匹。","錦中百結皆同心，蘂亂云盤相间深。","此意欲傳傳不得，玫瑰作柱朱弦琴。","爲君裁破合歡被，星斗迢迢共千里。","象尺熏爐未覺秋，碧池已有新蓮子。"]', '诗', 'shi', '', NULL, '織錦詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39ec68ae-7037-4d89-8c33-a80243289f75', '夜宴謠', '夜宴謠', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["長釵墜髮雙蜻蜓，碧盡山斜開畫屏。","虬鬚公子五侯客，一飲千鍾如建瓴。","鸞咽奼唱圓無節，眉歛湘煙袖迴雪。","清夜恩情四座同，莫令溝水東西別。","亭亭蠟淚香珠殘，暗露曉風羅幕寒。","飄颻戟帶儼相次，二十四枝龍畫竿。","裂管縈弦共繁曲，芳樽細浪傾春醁。","高樓客散杏花多，脉脉新蟾如瞪目。"]', '["长釵墜髮雙蜻蜓，碧尽山斜开畫屏。","虬鬚公子五侯客，一饮千鍾如建瓴。","鸾咽奼唱圓無節，眉歛湘煙袖迴雪。","清夜恩情四座同，莫令溝水东西別。","亭亭蠟泪香珠殘，暗露晓风羅幕寒。","飄颻戟带儼相次，二十四枝龙畫竿。","裂管縈弦共繁曲，芳樽細浪傾春醁。","高楼客散杏花多，脉脉新蟾如瞪目。"]', '诗', 'shi', '', NULL, '夜宴謠 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8da5c20-a77c-4bca-b863-81bed34191fe', '蓮浦謠', '蓮浦謠', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["鳴橈軋軋溪溶溶，廢綠平煙吳苑東。","水清蓮媚兩相向，鏡裏見愁愁更紅。","白馬金鞭大堤上，西江日夕多風浪。","荷心有露似驪珠，不是真圓亦搖蕩。"]', '["鳴橈軋軋溪溶溶，廢綠平煙吳苑东。","水清蓮媚兩相向，镜裏见愁愁更紅。","白马金鞭大堤上，西江日夕多风浪。","荷心有露似驪珠，不是真圓亦搖蕩。"]', '诗', 'shi', '', NULL, '蓮浦謠 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b130568d-ec30-48db-ae64-7883c77f10b7', '郭處士擊甌歌', '郭处士擊甌歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["佶栗金虬石潭古，勺陂瀲灩幽脩語。","湘君寶馬上神雲，碎佩叢鈴滿煙雨。","吾聞三十六宮花離離，軟風吹春星斗稀。","玉晨冷磬破昏夢，天露未乾香著衣。","蘭釵委墜垂雲髮，小響丁當逐迴雪。","晴碧煙滋重疊山，羅屏半掩桃花月。","太平天子駐雲車，龍鑪勃鬱雙蟠拏。","宮中近臣抱扇立，侍女低鬟落翠花。","亂珠觸續正跳蕩，傾頭不覺金烏斜。","我亦爲君長歎息，緘情遠寄愁無色。","莫霑香夢綠楊絲，千里春風正無力。"]', '["佶栗金虬石潭古，勺陂瀲灩幽脩語。","湘君寶马上神云，碎佩叢鈴满煙雨。","吾闻三十六宮花離離，軟风吹春星斗稀。","玉晨冷磬破昏梦，天露未乾香著衣。","蘭釵委墜垂云髮，小响丁當逐迴雪。","晴碧煙滋重叠山，羅屏半掩桃花月。","太平天子駐云车，龙鑪勃鬱雙蟠拏。","宮中近臣抱扇立，侍女低鬟落翠花。","亂珠觸續正跳蕩，傾头不覺金烏斜。","我亦爲君长歎息，緘情远寄愁無色。","莫霑香梦綠楊絲，千里春风正無力。"]', '诗', 'shi', '', NULL, '郭處士擊甌歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a017556-7bd9-405e-b792-093428c88cab', '遐水謠', '遐水謠', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["天兵九月渡遐水，馬踏沙鳴驚雁起。","殺氣空高萬里情，塞寒如箭傷眸子。","狼煙堡上霜漫漫，枯葉號風天地乾。","犀帶鼠裘無暖色，清光炯冷黃金鞍。","虜塵如霧昏亭障，隴首年年漢飛將。","麟閣無名期未歸，樓中思婦徒相望。"]', '["天兵九月渡遐水，马踏沙鳴驚雁起。","殺氣空高万里情，塞寒如箭傷眸子。","狼煙堡上霜漫漫，枯葉號风天地乾。","犀带鼠裘無暖色，清光炯冷黄金鞍。","虜塵如霧昏亭障，隴首年年漢飞將。","麟閣無名期未归，楼中思婦徒相望。"]', '诗', 'shi', '', NULL, '遐水謠 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f3bd91b-92b1-4cd3-933e-eb4bad31ebb6', '曉仙謠', '晓仙謠', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["玉妃喚月歸海宮，月色澹白涵春空。","銀河欲轉星靨靨，碧浪疊山埋早紅。","宮花有露如新淚，小苑叢叢入寒翠。","綺閣空傳唱漏聲，網軒未辨凌雲字。","遙遙珠帳連湘煙，鶴扇如霜金骨仙。","碧簫曲盡彩霞動，下視九州皆悄然。","秦王女騎紅尾鳳，半空回首晨雞弄。","霧蓋狂塵億兆家，世人猶作牽情夢。"]', '["玉妃喚月归海宮，月色澹白涵春空。","銀河欲轉星靨靨，碧浪叠山埋早紅。","宮花有露如新泪，小苑叢叢入寒翠。","綺閣空傳唱漏声，網軒未辨凌云字。","遙遙珠帳連湘煙，鹤扇如霜金骨仙。","碧簫曲尽彩霞动，下視九州皆悄然。","秦王女騎紅尾鳳，半空回首晨雞弄。","霧蓋狂塵億兆家，世人猶作牽情梦。"]', '诗', 'shi', '', NULL, '曉仙謠 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a9475d-6686-4421-9d18-f11b5819071d', '錦城曲', '錦城曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蜀山攢黛留晴雪，簝笋蕨芽縈九折。","江風吹巧剪霞綃，花上千枝杜鵑血。","杜鵑飛入巖下叢，夜呌思歸山月中。","巴水漾情情不盡，文君織得春機紅。","怨魄未歸芳草死，江頭學種相思子。","樹成寄與望鄉人，白帝荒城五千里。"]', '["蜀山攢黛留晴雪，簝笋蕨芽縈九折。","江风吹巧剪霞綃，花上千枝杜鵑血。","杜鵑飞入巖下叢，夜呌思归山月中。","巴水漾情情不尽，文君织得春機紅。","怨魄未归芳草死，江头学種相思子。","樹成寄與望乡人，白帝荒城五千里。"]', '诗', 'shi', '', NULL, '錦城曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1c56a8f-0b6a-4402-8d56-d2382a44d77f', '生禖屏風歌', '生禖屏风歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["玉墀暗接昆侖井，井上無人金索冷。","畫壁陰森九子堂，階前細月鋪花影。","繡屏銀鴨香蓊濛，天上夢歸花繞叢。","宜男漫作後庭草，不似櫻桃千子紅。"]', '["玉墀暗接昆侖井，井上無人金索冷。","畫壁陰森九子堂，階前細月鋪花影。","繡屏銀鴨香蓊濛，天上梦归花繞叢。","宜男漫作後庭草，不似櫻桃千子紅。"]', '诗', 'shi', '', NULL, '生禖屏風歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a352cadf-ae4d-45bc-9df5-c10ce5de5ae1', '嘲春風', '嘲春风', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["春風何處好，別殿饒芳草。","苒嫋轉鸞旗，萎蕤吹雉葆。","揚芳歷九門，澹蕩入蘭蓀。","爭奈白團扇，時時偷主恩。"]', '["春风何处好，別殿饒芳草。","苒嫋轉鸾旗，萎蕤吹雉葆。","揚芳歷九门，澹蕩入蘭蓀。","爭奈白團扇，时时偷主恩。"]', '诗', 'shi', '', NULL, '嘲春風 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34eb8904-b418-40ee-8fda-fab1b71af496', '舞衣曲', '舞衣曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["藕腸纖縷抽輕春，煙機漠漠嬌娥嚬。","金梭淅瀝透空薄，剪落交刀吹斷雲。","張家公子夜聞雨，夜向蘭堂思楚舞。","蟬衫麟帶壓愁香，偷得鶯簧鏁金縷。","管含蘭氣嬌語悲，胡槽雪腕鴛鴦絲。","芙蓉力弱應難定，楊柳風多不自持。","迴嚬笑語西牕客，星斗寥寥波脉脉。","不逐秦王卷象牀，滿樓明月梨花白。"]', '["藕腸纖縷抽轻春，煙機漠漠嬌娥嚬。","金梭淅瀝透空薄，剪落交刀吹斷云。","張家公子夜闻雨，夜向蘭堂思楚舞。","蟬衫麟带壓愁香，偷得鶯簧鏁金縷。","管含蘭氣嬌語悲，胡槽雪腕鴛鴦絲。","芙蓉力弱應难定，楊柳风多不自持。","迴嚬笑語西牕客，星斗寥寥波脉脉。","不逐秦王卷象牀，满楼明月梨花白。"]', '诗', 'shi', '', NULL, '舞衣曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aab693a7-a1dc-40d4-a2fa-58ddf3087340', '張靜婉採蓮歌', '張静婉採蓮歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蘭膏墜髮紅玉春，燕釵拖頸拋盤雲。","城邊楊柳向嬌晚，門前溝水波粼粼。","麒麟公子朝天客，珂馬璫璫度春陌。","掌中無力舞衣輕，剪斷鮫綃破春碧。","抱月飄煙一尺腰，麝臍龍髓憐嬌嬈。","秋羅拂水碎光動，露重花多香不銷。","鸂鶒交交塘水滿，綠芒如粟蓮莖短。","一夜西風送雨來，粉痕零落愁紅淺。","船頭折藕絲暗牽，藕根蓮子相留連。","郎心似月月未缺，十五十六清光圓。"]', '["蘭膏墜髮紅玉春，燕釵拖頸拋盤云。","城邊楊柳向嬌晚，门前溝水波粼粼。","麒麟公子朝天客，珂马璫璫度春陌。","掌中無力舞衣轻，剪斷鮫綃破春碧。","抱月飄煙一尺腰，麝臍龙髓怜嬌嬈。","秋羅拂水碎光动，露重花多香不銷。","鸂鶒交交塘水满，綠芒如粟蓮莖短。","一夜西风送雨来，粉痕零落愁紅淺。","船头折藕絲暗牽，藕根蓮子相留連。","郎心似月月未缺，十五十六清光圓。"]', '诗', 'shi', '', NULL, '張靜婉採蓮歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('637ab18d-596b-4458-bed8-d6c6d6f18b2f', '湘宮人歌', '湘宮人歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["池塘芳草濕，夜半東風起。","生綠畫羅屏，金壺貯春水。","黃粉楚宮人，芳花玉刻鱗。","娟娟照棊燭，不語兩含嚬。"]', '["池塘芳草濕，夜半东风起。","生綠畫羅屏，金壺貯春水。","黄粉楚宮人，芳花玉刻鱗。","娟娟照棊燭，不語兩含嚬。"]', '诗', 'shi', '', NULL, '湘宮人歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8bae9fe-b06f-4907-b243-9b16e16a5aeb', '黃曇子歌', '黄曇子歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["參差綠蒲短，搖豔雲塘滿。","紅瀲蕩融融，鶯翁鸂鶒暖。","萋芊小成路，馬上修蛾嬾。","羅衫褭回風，點粉金鸝卵。"]', '["參差綠蒲短，搖豔云塘满。","紅瀲蕩融融，鶯翁鸂鶒暖。","萋芊小成路，马上修蛾嬾。","羅衫褭回风，点粉金鸝卵。"]', '诗', 'shi', '', NULL, '黃曇子歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ea8bb3d-29e3-4f4d-8ddb-556ff7d68951', '觱篥歌', '觱篥歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蠟煙如纛新蟾滿，門外平沙草芽短。","黑頭丞相九天歸，夜聽飛瓊吹朔管。","情遠氣調蘭蕙薰，天香瑞彩含絪緼。","皓然纖指都揭血，日暖碧霄無片雲。","含商咀徵雙幽咽，軟縠疎羅共蕭屑。","不盡長圓疊翠愁，柳風吹破澄潭月。","鳴梭淅瀝金絲蘂，恨語殷勤隴頭水。","漢將營前萬里沙，更深一一霜鴻起。","十二樓前花正繁，交枝簇蔕連壁門。","景陽宮女正愁絕，莫使此聲催斷魂。"]', '["蠟煙如纛新蟾满，门外平沙草芽短。","黑头丞相九天归，夜听飞瓊吹朔管。","情远氣調蘭蕙薰，天香瑞彩含絪緼。","皓然纖指都揭血，日暖碧霄無片云。","含商咀徵雙幽咽，軟縠疎羅共蕭屑。","不尽长圓叠翠愁，柳风吹破澄潭月。","鳴梭淅瀝金絲蘂，恨語殷勤隴头水。","漢將營前万里沙，更深一一霜鴻起。","十二楼前花正繁，交枝簇蔕連壁门。","景陽宮女正愁絕，莫使此声催斷魂。"]', '诗', 'shi', '', NULL, '觱篥歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c8ec5b0-7744-4b41-8218-7e0ef6d5db42', '照影曲', '照影曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["景陽妝罷瓊牕暖，欲照澄明香步嬾。","橋上衣多抱彩雲，金鱗不動春塘滿。","黃印額山輕爲塵，翠鱗紅穉俱含嚬。","桃花百媚如欲語，曾爲無雙今兩身。"]', '["景陽妝罷瓊牕暖，欲照澄明香步嬾。","橋上衣多抱彩云，金鱗不动春塘满。","黄印額山轻爲塵，翠鱗紅穉俱含嚬。","桃花百媚如欲語，曾爲無雙今兩身。"]', '诗', 'shi', '', NULL, '照影曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bfbcd29-e1c6-449a-b506-37fa8cd97d09', '拂舞詞', '拂舞词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["黃河怒浪連天來，大響谹谹如殷雷。","龍伯驅風不敢上，百川噴雪高崔嵬。","二十三弦何太哀，請公勿渡立徘徊。","下有狂蛟鋸爲尾，裂帆截櫂磨霜齒。","神椎鑿石塞神潭，白馬䟃𧽼赤塵起。","公乎躍馬揚玉鞭，滅沒高蹄日千里。"]', '["黄河怒浪連天来，大响谹谹如殷雷。","龙伯驱风不敢上，百川噴雪高崔嵬。","二十三弦何太哀，請公勿渡立徘徊。","下有狂蛟鋸爲尾，裂帆截櫂磨霜齒。","神椎鑿石塞神潭，白马䟃𧽼赤塵起。","公乎躍马揚玉鞭，滅沒高蹄日千里。"]', '诗', 'shi', '', NULL, '拂舞詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a719c277-bb80-4b9a-a329-b7884474e154', '太液池歌', '太液池歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["腥鮮龍氣連清防，花風漾漾吹細光。","疊瀾不定照天井，倒影蕩搖晴翠長。","平碧淺春生綠塘，雲容雨態連青蒼。","夜深銀漢通柏梁，二十八宿朝玉堂。"]', '["腥鲜龙氣連清防，花风漾漾吹細光。","叠瀾不定照天井，倒影蕩搖晴翠长。","平碧淺春生綠塘，云容雨態連青蒼。","夜深銀漢通柏梁，二十八宿朝玉堂。"]', '诗', 'shi', '', NULL, '太液池歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37a211de-64db-4498-90fd-045bf1e274e2', '雉場歌', '雉場歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["茭葉萋萋接煙曙，雞鳴埭上梨花露。","彩杖鏘鏘已合圍，繡翎白頸遙相妬。","雕尾扇張金縷高，碎鈴素拂驪駒豪。","綠場紅跡未相接，箭發銅牙傷彩毛。","麥隴桑陰小山晚，六虬歸去凝笳遠。","城頭却望幾含情，青畝春蕪連石苑。"]', '["茭葉萋萋接煙曙，雞鳴埭上梨花露。","彩杖鏘鏘已合圍，繡翎白頸遙相妬。","雕尾扇張金縷高，碎鈴素拂驪駒豪。","綠場紅跡未相接，箭發銅牙傷彩毛。","麦隴桑陰小山晚，六虬归去凝笳远。","城头却望幾含情，青畝春蕪連石苑。"]', '诗', 'shi', '', NULL, '雉場歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4b9a87-3ea2-4322-9f00-9f0676e99763', '雍臺歌', '雍台歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["太子池南樓百尺，入窓新樹疎簾隔。","黃金鋪首畫鉤陳，羽葆停幢拂交戟。","盤紆闌楯臨高臺，帳殿臨流鸞扇開。","早鴈驚鳴細波起，映花鹵簿龍飛迴。"]', '["太子池南楼百尺，入窓新樹疎簾隔。","黄金鋪首畫鉤陳，羽葆停幢拂交戟。","盤紆闌楯臨高台，帳殿臨流鸾扇开。","早鴈驚鳴細波起，映花鹵簿龙飞迴。"]', '诗', 'shi', '', NULL, '雍臺歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b64c895-f608-4595-9a77-42332271cdf9', '吳苑行', '吳苑行', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["錦雉雙飛梅結子，平春遠綠牕中起。","吳江澹畫水連空，三尺屏風隔千里。","小苑有門紅扇開，天絲舞蝶共徘徊。","綺戶雕楹長若此，韶光歲歲如歸來。"]', '["錦雉雙飞梅結子，平春远綠牕中起。","吳江澹畫水連空，三尺屏风隔千里。","小苑有门紅扇开，天絲舞蝶共徘徊。","綺戶雕楹长若此，韶光歲歲如归来。"]', '诗', 'shi', '', NULL, '吳苑行 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ea100ee-aae2-4b7f-ac7b-26ddfa221071', '常林歡歌', '常林歡歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["宜城酒熟花覆橋，沙晴綠鴨鳴咬咬。","穠桑繞舍麥如尾，幽軋鳴機雙燕巢。","馬聲特特荆門道，蠻水揚光色如草。","錦薦金爐夢正長，東家咿喔雞鳴早。"]', '["宜城酒熟花覆橋，沙晴綠鴨鳴咬咬。","穠桑繞舍麦如尾，幽軋鳴機雙燕巢。","马声特特荆门道，蠻水揚光色如草。","錦薦金爐梦正长，东家咿喔雞鳴早。"]', '诗', 'shi', '', NULL, '常林歡歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2c005e0-2468-4fc7-b7e8-1ee6c06a9075', '塞寒行', '塞寒行', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["燕弓弦勁霜封瓦，樸簌寒鵰睇平野。","一點黃塵起鴈喧，白龍堆下千蹄馬。","河源怒濁風如刀，剪斷朔雲天更高。","晚出榆關逐征北，驚沙飛迸衝貂袍。","心許凌煙名不滅，年年錦字傷離別。","彩毫一畫竟何榮，空使青樓淚成血。"]', '["燕弓弦勁霜封瓦，樸簌寒鵰睇平野。","一点黄塵起鴈喧，白龙堆下千蹄马。","河源怒濁风如刀，剪斷朔云天更高。","晚出榆关逐征北，驚沙飞迸衝貂袍。","心許凌煙名不滅，年年錦字傷離別。","彩毫一畫竟何榮，空使青楼泪成血。"]', '诗', 'shi', '', NULL, '塞寒行 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba3be8c-3434-48e5-a239-9fcc54e2486f', '湖陰詞', '湖陰词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["祖龍黃鬚珊瑚鞭，鐵驄金面青連錢。","虎髯拔劒欲成夢，日壓賊營如血鮮。","海旗風急驚眠起，甲重光搖照湖水。","蒼黃追騎塵外歸，森索妖星陣前死。","五陵愁碧春萋萋，霸川玉馬空中嘶。","羽書如電入青璅，雪腕如槌催畫鞞。","白虬天子金煌鋩，高臨帝座迴龍章。","吳波不動楚山晚，花壓闌干春晝長。"]', '["祖龙黄鬚珊瑚鞭，鐵驄金面青連錢。","虎髯拔劒欲成梦，日壓賊營如血鲜。","海旗风急驚眠起，甲重光搖照湖水。","蒼黄追騎塵外归，森索妖星陣前死。","五陵愁碧春萋萋，霸川玉马空中嘶。","羽书如電入青璅，雪腕如槌催畫鞞。","白虬天子金煌鋩，高臨帝座迴龙章。","吳波不动楚山晚，花壓闌干春晝长。"]', '诗', 'shi', '', NULL, '湖陰詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d0ab06b-fbef-4b43-9b75-91edfbc504e1', '蔣侯神歌', '蔣侯神歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["楚神鐵馬金鳴珂，夜動蛟潭生素波。","商風刮水報西帝，廟前古樹蟠白虵。","吳王赤斧斫雲陣，畫堂列壁叢霜刃。","巫娥傳意托悲絲，鐸語琅琅理雙鬢。","湘煙刷翠湘山斜，東方日出飛神鴉。","青雲自有黑龍子，潘妃莫結丁香花。"]', '["楚神鐵马金鳴珂，夜动蛟潭生素波。","商风刮水報西帝，廟前古樹蟠白虵。","吳王赤斧斫云陣，畫堂列壁叢霜刃。","巫娥傳意托悲絲，鐸語琅琅理雙鬢。","湘煙刷翠湘山斜，东方日出飞神鴉。","青云自有黑龙子，潘妃莫結丁香花。"]', '诗', 'shi', '', NULL, '蔣侯神歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('086c429a-99ec-45d8-9b9a-0c4b9355d775', '漢皇迎春詞', '漢皇迎春词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["春草芊芊晴掃煙，宮城大錦紅殷鮮。","海日初融照仙掌，淮王小隊纓鈴響。","獵獵東風燄赤旗，畫神金甲葱蘢網。","鉅公步輦迎句芒，複道掃塵燕彗長。","豹尾竿前趙飛燕，柳風吹盡眉間黃。","碧草含情杏花喜，上林鶯囀遊絲起。","寶馬搖環萬騎歸，恩光暗入簾櫳裏。"]', '["春草芊芊晴掃煙，宮城大錦紅殷鲜。","海日初融照仙掌，淮王小隊纓鈴响。","獵獵东风燄赤旗，畫神金甲葱蘢網。","鉅公步輦迎句芒，複道掃塵燕彗长。","豹尾竿前趙飞燕，柳风吹尽眉间黄。","碧草含情杏花喜，上林鶯囀游絲起。","寶马搖环万騎归，恩光暗入簾櫳裏。"]', '诗', 'shi', '', NULL, '漢皇迎春詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d522dba-b5dd-43b4-af06-a5bead6a0a4a', '蘭塘詞', '蘭塘词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["塘水汪汪鳧唼喋，憶上江南木蘭檝。","繡頸金鬚蕩倒光，團團皺綠雞頭葉。","露凝荷卷珠淨圓，紫菱刺短浮根纏。","小姑歸晚紅妝淺，鏡裏芙蓉照水鮮。","東溝潏潏勞迴首，欲寄一杯瓊液酒。","知道無郎却有情，長敎月照相思柳。"]', '["塘水汪汪鳧唼喋，憶上江南木蘭檝。","繡頸金鬚蕩倒光，團團皺綠雞头葉。","露凝荷卷珠淨圓，紫菱刺短浮根纏。","小姑归晚紅妝淺，镜裏芙蓉照水鲜。","东溝潏潏勞迴首，欲寄一杯瓊液酒。","知道無郎却有情，长敎月照相思柳。"]', '诗', 'shi', '', NULL, '蘭塘詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d4e879d-9cf7-4890-8780-49af2c1b2136', '晚歸曲', '晚归曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["格格水禽飛帶波，孤光斜起夕陽多。","湖西山淺似相笑，菱刺惹衣攢黛蛾。","青絲繫船向江木，蘭芽出土吳江曲。","水極晴搖泛灩紅，草平春染煙綿綠。","玉鞭騎馬楊叛兒，刻金作鳳光參差。","丁丁暖漏滴花影，催入景陽人不知。","彎堤弱柳遙相矚，雀扇團圓掩香玉。","蓮塘艇子歸不歸，柳暗桑穠聞布穀。"]', '["格格水禽飞带波，孤光斜起夕陽多。","湖西山淺似相笑，菱刺惹衣攢黛蛾。","青絲繫船向江木，蘭芽出土吳江曲。","水極晴搖泛灩紅，草平春染煙綿綠。","玉鞭騎马楊叛兒，刻金作鳳光參差。","丁丁暖漏滴花影，催入景陽人不知。","彎堤弱柳遙相矚，雀扇團圓掩香玉。","蓮塘艇子归不归，柳暗桑穠闻布穀。"]', '诗', 'shi', '', NULL, '晚歸曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fcbdb24-5988-45e1-abad-580a0b9148d5', '故城曲', '故城曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["漠漠沙堤煙，堤西雉子斑。","雉聲何角角，麥秀桑陰閑。","遊絲蕩平綠，明滅時相續。","白馬金絡頭，東風故城曲。","故城殷貴嬪，曾占未來春。","自從香骨化，飛作馬蹄塵。"]', '["漠漠沙堤煙，堤西雉子斑。","雉声何角角，麦秀桑陰闲。","游絲蕩平綠，明滅时相續。","白马金絡头，东风故城曲。","故城殷貴嬪，曾占未来春。","自從香骨化，飞作马蹄塵。"]', '诗', 'shi', '', NULL, '故城曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d3ff2e5-a6c6-4e3d-a77b-87e52009262e', '昆明池水戰詞', '昆明池水戰词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["汪汪積水光連空，重疊細紋晴漾紅。","赤帝龍孫鱗甲怒，臨流一盼生陰風。","鼉鼓三聲報天子，雕旌獸艦凌波起。","雷吼濤驚白石山，石鯨眼裂蟠蛟死。","溟池海浦俱喧豗，青幟白旌相次來。","箭羽槍纓三百萬，踏翻西海生塵埃。","茂陵仙去菱花老，唼唼遊魚近煙島。","渺莽殘陽釣艇歸，綠頭江鴨眠沙草。"]', '["汪汪積水光連空，重叠細紋晴漾紅。","赤帝龙孫鱗甲怒，臨流一盼生陰风。","鼉鼓三声報天子，雕旌獸艦凌波起。","雷吼濤驚白石山，石鯨眼裂蟠蛟死。","溟池海浦俱喧豗，青幟白旌相次来。","箭羽槍纓三百万，踏翻西海生塵埃。","茂陵仙去菱花老，唼唼游鱼近煙島。","渺莽殘陽釣艇归，綠头江鴨眠沙草。"]', '诗', 'shi', '', NULL, '昆明池水戰詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89e9397e-4e89-45f3-9a5f-d2b35c65b1d9', '謝公墅歌', '謝公墅歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["朱雀航南繞香陌，謝郎東墅連春碧。","鳩眠高柳日方融，綺榭飄颻紫庭客。","文楸方罫花參差，心陣未成星滿池。","四座無喧梧竹靜，金蟬玉柄俱持頤。","對局含情見千里，都城已得長虵尾。","江南王氣繫疎襟，未許苻堅過淮水。"]', '["朱雀航南繞香陌，謝郎东墅連春碧。","鳩眠高柳日方融，綺榭飄颻紫庭客。","文楸方罫花參差，心陣未成星满池。","四座無喧梧竹静，金蟬玉柄俱持頤。","对局含情见千里，都城已得长虵尾。","江南王氣繫疎襟，未許苻堅過淮水。"]', '诗', 'shi', '', NULL, '謝公墅歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('445b69dd-9702-4b83-8ecf-81c3bbd8cb4a', '罩魚歌', '罩鱼歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["朝罩罩城南，暮罩罩城西。","兩漿鳴幽幽，蓮子相高低。","持罩入深水，金鱗大如手。","魚尾迸圓波，千珠落湘藕。","風颸颸，雨離離，菱尖茭刺鸂鶒飛。","水連網眼白如影，淅瀝篷聲寒點微。","楚岸有花花蓋屋，金塘柳色前溪曲。","悠溶杳若去無窮，五色澄潭鴨頭綠。"]', '["朝罩罩城南，暮罩罩城西。","兩漿鳴幽幽，蓮子相高低。","持罩入深水，金鱗大如手。","鱼尾迸圓波，千珠落湘藕。","风颸颸，雨離離，菱尖茭刺鸂鶒飞。","水連網眼白如影，淅瀝篷声寒点微。","楚岸有花花蓋屋，金塘柳色前溪曲。","悠溶杳若去無窮，五色澄潭鴨头綠。"]', '诗', 'shi', '', NULL, '罩魚歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('396c09e9-dc8b-4650-bc25-acf554e59745', '春洲曲', '春洲曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["韶光染色如蛾翠，綠濕紅鮮水容媚。","蘇小慵多蘭渚閑，融融浦日鵁鶄寐。","紫騮蹀躞金銜嘶，岸上揚鞭煙草迷。","門外平橋連柳堤，歸來晚樹黃鶯啼。"]', '["韶光染色如蛾翠，綠濕紅鲜水容媚。","蘇小慵多蘭渚闲，融融浦日鵁鶄寐。","紫騮蹀躞金銜嘶，岸上揚鞭煙草迷。","门外平橋連柳堤，归来晚樹黄鶯啼。"]', '诗', 'shi', '', NULL, '春洲曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12526081-cca9-439a-9a23-6e7b681ef2f5', '臺城曉朝曲', '台城晓朝曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["司馬門前火千炬，蘭干星斗天將曙。","朱網龕鬖丞相車，曉隨疊鼓朝天去。","博山鏡樹香䒠茸，褭褭浮航金畫龍。","大江歛勢避辰極，兩闕深嚴煙翠濃。"]', '["司马门前火千炬，蘭干星斗天將曙。","朱網龕鬖丞相车，晓隨叠鼓朝天去。","博山镜樹香䒠茸，褭褭浮航金畫龙。","大江歛勢避辰極，兩闕深嚴煙翠濃。"]', '诗', 'shi', '', NULL, '臺城曉朝曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aca5d1d1-7bce-42b6-b025-2d23c81624bc', '走馬樓三更曲', '走马楼三更曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["春姿暖氣昏神沼，李樹拳枝紫芽小。","玉皇夜入未央宮，長火千條照棲鳥。","馬過平橋通畫堂，虎幡龍戟風飄揚。","簾間清唱報寒點，丙舍無人遺燼香。"]', '["春姿暖氣昏神沼，李樹拳枝紫芽小。","玉皇夜入未央宮，长火千條照棲鸟。","马過平橋通畫堂，虎幡龙戟风飄揚。","簾间清唱報寒点，丙舍無人遺燼香。"]', '诗', 'shi', '', NULL, '走馬樓三更曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da0c9f4e-4db4-404d-8d98-b415cf93dcad', '達摩支曲', '達摩支曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["擣麝成塵香不滅，拗蓮作寸絲難絕。","紅淚文姬洛水春，白頭蘇武天山雪。","君不見無愁高緯花漫漫，漳浦宴餘清露寒。","一旦臣僚共囚虜，欲吹羌管先汍瀾。","舊臣頭鬢霜華早，可惜雄心醉中老。","萬古春歸夢不歸，鄴城風雨連天草。"]', '["擣麝成塵香不滅，拗蓮作寸絲难絕。","紅泪文姬洛水春，白头蘇武天山雪。","君不见無愁高緯花漫漫，漳浦宴餘清露寒。","一旦臣僚共囚虜，欲吹羌管先汍瀾。","旧臣头鬢霜华早，可惜雄心醉中老。","万古春归梦不归，鄴城风雨連天草。"]', '诗', 'shi', '', NULL, '達摩支曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b85033bc-2e60-4226-8bc8-75749b3536c0', '陽春曲', '陽春曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["雲母空牕曉煙薄，香昏龍氣凝暉閣。","霏霏霧雨杏花天，簾外春威著羅幕。","曲闌伏檻金麒麟，沙苑芳郊連翠茵。","廐馬何能嚙芳草，路人不敢隨流塵。"]', '["云母空牕晓煙薄，香昏龙氣凝暉閣。","霏霏霧雨杏花天，簾外春威著羅幕。","曲闌伏檻金麒麟，沙苑芳郊連翠茵。","廐马何能嚙芳草，路人不敢隨流塵。"]', '诗', 'shi', '', NULL, '陽春曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29b32830-adc6-4711-9694-a693002585a4', '湘東宴曲', '湘东宴曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["湘東夜宴金貂人，楚女含情嬌翠嚬。","玉管將吹插鈿帶，錦囊斜拂雙麒麟。","重城漏斷孤帆去，唯恐瓊籤報天曙。","萬戶沈沈碧樹圓，雲飛雨散知何處。","欲上香車俱脉脉，清歌響斷銀屏隔。","堤外紅塵蠟炬歸，樓前澹月連江白。"]', '["湘东夜宴金貂人，楚女含情嬌翠嚬。","玉管將吹插鈿带，錦囊斜拂雙麒麟。","重城漏斷孤帆去，唯恐瓊籤報天曙。","万戶沈沈碧樹圓，云飞雨散知何处。","欲上香车俱脉脉，清歌响斷銀屏隔。","堤外紅塵蠟炬归，楼前澹月連江白。"]', '诗', 'shi', '', NULL, '湘東宴曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ea1677a-dbc9-4dd5-8373-62f8fab1acba', '東郊行', '东郊行', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["鬬雞臺下東西道，柳覆班騅蝶縈草。","坱靄韶容鏁澹愁，青筐葉盡蠶應老。","綠渚幽香生白蘋，差差小浪吹魚鱗。","王孫騎馬有歸意，林彩着空如細塵。","安得人生各相守，燒船破棧休馳走。","世上方應無別離，路傍更長千株柳。"]', '["鬬雞台下东西道，柳覆班騅蝶縈草。","坱靄韶容鏁澹愁，青筐葉尽蠶應老。","綠渚幽香生白蘋，差差小浪吹鱼鱗。","王孫騎马有归意，林彩着空如細塵。","安得人生各相守，燒船破棧休驰走。","世上方應無別離，路傍更长千株柳。"]', '诗', 'shi', '', NULL, '東郊行 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e6fb299-803e-4e6b-bb02-d9d0c7f343f1', '水仙謠', '水仙謠', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["水客夜騎紅鯉魚，赤鸞雙鶴蓬瀛書。","輕塵不起雨新霽，萬里孤光含碧虛。","露魄冠輕見雲髮，寒絲七炷香泉咽。","夜深天碧亂山姿，光碎平波滿船月。"]', '["水客夜騎紅鯉鱼，赤鸾雙鹤蓬瀛书。","轻塵不起雨新霽，万里孤光含碧虛。","露魄冠轻见云髮，寒絲七炷香泉咽。","夜深天碧亂山姿，光碎平波满船月。"]', '诗', 'shi', '', NULL, '水仙謠 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4117787f-d5ee-478b-9d97-eaf731645697', '東峯歌', '东峯歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["錦礫潺湲玉溪水，曉來微雨藤花紫。","冉冉山雞紅尾長，一聲樵斧驚飛起。","松刺梳空石差齒，煙香風軟人參蘂。","陽崖一夢伴雲根，仙菌靈芝夢魂裏。"]', '["錦礫潺湲玉溪水，晓来微雨藤花紫。","冉冉山雞紅尾长，一声樵斧驚飞起。","松刺梳空石差齒，煙香风軟人參蘂。","陽崖一梦伴云根，仙菌靈芝梦魂裏。"]', '诗', 'shi', '', NULL, '東峯歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e2d7e5b-43cf-4f60-8fbf-0a07bc37566d', '會昌丙寅豐歲歌', '會昌丙寅豐歲歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["丙寅歲，休牛馬。","風如吹煙，日如渥赭。","九重天子調天下，春綠將年到西野。","西野翁，生兒童。","門前好樹青䒠茸，䒠茸單衣麥田路。","村南娶婦桃花紅，新姑車右及門柱，粉項韓憑雙扇中。","喜氣自能成歲豐，農祥爾物來爭功。"]', '["丙寅歲，休牛马。","风如吹煙，日如渥赭。","九重天子調天下，春綠將年到西野。","西野翁，生兒童。","门前好樹青䒠茸，䒠茸單衣麦田路。","村南娶婦桃花紅，新姑车右及门柱，粉項韓憑雙扇中。","喜氣自能成歲豐，農祥爾物来爭功。"]', '诗', 'shi', '', NULL, '會昌丙寅豐歲歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4458131-dd91-425b-b517-292310925fd7', '碌碌古詞', '碌碌古词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["左亦不碌碌，右亦不碌碌。","野草自根肥，羸牛生健犢。","融蠟作杏蒂，男兒不戀家。","春風破紅意，女頰如桃花。","忠言未見信，巧語翻咨嗟。","一鞘無兩刃，徒勞油壁車。"]', '["左亦不碌碌，右亦不碌碌。","野草自根肥，羸牛生健犢。","融蠟作杏蒂，男兒不戀家。","春风破紅意，女頰如桃花。","忠言未见信，巧語翻咨嗟。","一鞘無兩刃，徒勞油壁车。"]', '诗', 'shi', '', NULL, '碌碌古詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93c6e6e8-bcdc-43c6-96af-e0c3418376ef', '春野行', '春野行', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["草淺淺，春如剪。","花壓李娘愁，飢蠶欲成繭。","東城年少氣堂堂，金丸驚起雙鴛鴦。","含羞更問衛公子，月到枕前春夢長。"]', '["草淺淺，春如剪。","花壓李娘愁，飢蠶欲成繭。","东城年少氣堂堂，金丸驚起雙鴛鴦。","含羞更问衛公子，月到枕前春梦长。"]', '诗', 'shi', '', NULL, '春野行 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b70e35-54e7-466c-aae9-b8632fb6c1b4', '醉歌', '醉歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["簷柳初黃燕新乳，曉碧芊綿過微雨。","樹色深含臺榭情，鶯聲巧作煙花主。","錦袍公子陳杯觴，撥醅百甕春酒香。","入門下馬問誰在，降堦握手登華堂。","臨邛美人連山眉，低抱琵琶含怨思。","朔風繞指我先笑，明月入懷君自知。","勸君莫惜金樽酒，年少須臾如覆手。","辛勤到老慕簞瓢，於我悠悠竟何有。","洛陽盧仝稱文房，妻子脚禿舂黃糧。","阿耋光顏不識字，指麾豪儁如驅羊。","天犀壓斷朱鼹鼠，瑞錦驚飛金鳳皇。","其餘豈足霑牙齒，欲用何能報天子。","駑馬垂頭搶暝塵，驊騮一日行千里。","但有沈冥醉客家，支頤瞪目持流霞。","唯恐南國風雨落，碧蕪狼籍棠梨花。"]', '["簷柳初黄燕新乳，晓碧芊綿過微雨。","樹色深含台榭情，鶯声巧作煙花主。","錦袍公子陳杯觴，撥醅百甕春酒香。","入门下马问誰在，降堦握手登华堂。","臨邛美人連山眉，低抱琵琶含怨思。","朔风繞指我先笑，明月入懷君自知。","勸君莫惜金樽酒，年少須臾如覆手。","辛勤到老慕簞瓢，於我悠悠竟何有。","洛陽盧仝稱文房，妻子脚禿舂黄糧。","阿耋光顏不識字，指麾豪儁如驱羊。","天犀壓斷朱鼹鼠，瑞錦驚飞金鳳皇。","其餘豈足霑牙齒，欲用何能報天子。","駑马垂头搶暝塵，驊騮一日行千里。","但有沈冥醉客家，支頤瞪目持流霞。","唯恐南国风雨落，碧蕪狼籍棠梨花。"]', '诗', 'shi', '', NULL, '醉歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d36d62-b954-4bf7-b93b-2a28cc1bfd05', '江南曲', '江南曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["妾家白蘋浦，日上芙蓉檝。","軋軋搖漿聲，移舟入茭葉。","溪長茭葉深，作底難相尋。","避郎郎不見，鸂鶒自浮沈。","拾萍萍無根，採蓮蓮有子。","不作浮萍生，寧爲藕花死。","岸傍騎馬郎，烏帽紫遊韁。","含愁復含笑，回首問橫塘。","妾住金陵浦，門前朱雀航。","流蘇持作帳，芙蓉持作梁。","出入金犢幰，兄弟侍中郎。","前年學歌舞，定得郎相許。","連娟眉繞山，依約腰如杵。","鳳管悲若咽，鸞弦嬌欲語。","扇薄露紅鉛，羅輕壓金縷。","明月西南樓，珠簾玳瑁鉤。","橫波巧能笑，彎蛾不識愁。","花開子留樹，草長根依土。","早聞金溝遠，底事歸郎許。","不學楊白花，朝朝淚如雨。"]', '["妾家白蘋浦，日上芙蓉檝。","軋軋搖漿声，移舟入茭葉。","溪长茭葉深，作底难相尋。","避郎郎不见，鸂鶒自浮沈。","拾萍萍無根，採蓮蓮有子。","不作浮萍生，寧爲藕花死。","岸傍騎马郎，烏帽紫游韁。","含愁复含笑，回首问橫塘。","妾住金陵浦，门前朱雀航。","流蘇持作帳，芙蓉持作梁。","出入金犢幰，兄弟侍中郎。","前年学歌舞，定得郎相許。","連娟眉繞山，依約腰如杵。","鳳管悲若咽，鸾弦嬌欲語。","扇薄露紅鉛，羅轻壓金縷。","明月西南楼，珠簾玳瑁鉤。","橫波巧能笑，彎蛾不識愁。","花开子留樹，草长根依土。","早闻金溝远，底事归郎許。","不学楊白花，朝朝泪如雨。"]', '诗', 'shi', '', NULL, '江南曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9791443-723d-4d0d-bc59-1c5b7eae5803', '堂堂曲', '堂堂曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["錢唐岸上春如織，淼淼寒潮帶睛色。","淮南遊客馬連嘶，碧草迷人歸不得。","風飄客意如吹煙，纖指殷勤傷雁弦。","一曲堂堂紅燭筵，長鯨瀉酒如飛泉。"]', '["錢唐岸上春如织，淼淼寒潮带睛色。","淮南游客马連嘶，碧草迷人归不得。","风飄客意如吹煙，纖指殷勤傷雁弦。","一曲堂堂紅燭筵，长鯨瀉酒如飞泉。"]', '诗', 'shi', '', NULL, '堂堂曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d89c3568-7852-4241-ba7b-d3c98807ba0f', '惜春詞', '惜春词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["百舌問花花不語，低迴似恨橫塘雨。","蜂爭粉蘂蝶分香，不似垂楊惜金縷。","願君留得長妖韶，莫逐東風還蕩搖。","秦女含嚬向煙月，愁紅帶露空迢迢。"]', '["百舌问花花不語，低迴似恨橫塘雨。","蜂爭粉蘂蝶分香，不似垂楊惜金縷。","願君留得长妖韶，莫逐东风還蕩搖。","秦女含嚬向煙月，愁紅带露空迢迢。"]', '诗', 'shi', '', NULL, '惜春詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6098df4a-d47d-4882-86a3-09b33dbadf92', '春愁曲', '春愁曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["紅絲穿露珠簾冷，百尺啞啞下纖綆。","遠翠愁山入臥屏，兩重雲母空烘影。","涼簪墜髮春眠重，玉兔煴香柳如夢。","錦疊空牀委墮紅，颸颸掃尾雙金鳳。","蜂喧蝶駐俱悠揚，柳拂赤欄纖草長。","覺後梨花委平綠，春風和雨吹池塘。"]', '["紅絲穿露珠簾冷，百尺啞啞下纖綆。","远翠愁山入臥屏，兩重云母空烘影。","涼簪墜髮春眠重，玉兔煴香柳如梦。","錦叠空牀委墮紅，颸颸掃尾雙金鳳。","蜂喧蝶駐俱悠揚，柳拂赤欄纖草长。","覺後梨花委平綠，春风和雨吹池塘。"]', '诗', 'shi', '', NULL, '春愁曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ec12e46-6e5d-4889-bda3-436cb0266864', '蘇小小歌', '蘇小小歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["買蓮莫破券，買酒莫解金。","酒裏春容抱離恨，水中蓮子懷芳心。","吳宮女兒腰似束，家在錢唐小江曲。","一自檀郎逐便風，門前春水年年綠。"]', '["買蓮莫破券，買酒莫解金。","酒裏春容抱離恨，水中蓮子懷芳心。","吳宮女兒腰似束，家在錢唐小江曲。","一自檀郎逐便风，门前春水年年綠。"]', '诗', 'shi', '', NULL, '蘇小小歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7a0d6a9-c4fe-4f42-80ad-9ec2c2a0522f', '春江花月夜詞', '春江花月夜词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["玉樹歌闌海雲黑，花庭忽作青蕪國。","秦淮有水水無情，還向金陵漾春色。","楊家二世安九重，不御華芝嫌六龍。","百幅錦帆風力滿，連天展盡金芙蓉。","珠翠丁星復明滅，龍頭劈浪哀笳發。","千里涵空澄水魂，萬枝破鼻飄香雪。","漏轉霞高滄海西，頗黎枕上聞天雞。","蠻弦代寫曲如語，一醉昏昏天下迷。","四方傾動煙塵起，猶在濃香夢魂裏。","後主荒宮有曉鶯，飛來只隔西江水。"]', '["玉樹歌闌海云黑，花庭忽作青蕪国。","秦淮有水水無情，還向金陵漾春色。","楊家二世安九重，不御华芝嫌六龙。","百幅錦帆风力满，連天展尽金芙蓉。","珠翠丁星复明滅，龙头劈浪哀笳發。","千里涵空澄水魂，万枝破鼻飄香雪。","漏轉霞高滄海西，頗黎枕上闻天雞。","蠻弦代寫曲如語，一醉昏昏天下迷。","四方傾动煙塵起，猶在濃香梦魂裏。","後主荒宮有晓鶯，飞来只隔西江水。"]', '诗', 'shi', '', NULL, '春江花月夜詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01af79c-7a30-4fae-8556-c36e4bbdf555', '懊惱曲', '懊惱曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["藕絲作線難勝鍼，蘂粉染黃那得深。","玉白蘭芳不相顧，青樓一笑輕千金。","莫言自古皆如此，健劒刜鐘鉛繞指。","三秋庭綠盡迎霜，惟有荷花守紅死。","廬江小吏朱斑輪，柳縷吐芽香玉春。","兩股金釵已相許，不令獨作空成塵。","悠悠楚水流如馬，恨紫愁紅滿平野。","野土千年怨不平，至今燒作鴛鴦瓦。"]', '["藕絲作線难勝鍼，蘂粉染黄那得深。","玉白蘭芳不相顧，青楼一笑轻千金。","莫言自古皆如此，健劒刜鐘鉛繞指。","三秋庭綠尽迎霜，惟有荷花守紅死。","廬江小吏朱斑輪，柳縷吐芽香玉春。","兩股金釵已相許，不令独作空成塵。","悠悠楚水流如马，恨紫愁紅满平野。","野土千年怨不平，至今燒作鴛鴦瓦。"]', '诗', 'shi', '', NULL, '懊惱曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d22d5225-8079-4bd5-99b1-91e7ba2fbd29', '三洲詞', '三洲词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["團圓莫作波中月，潔白莫爲枝上雪。","月隨波動碎潾潾，雪似梅花不堪折。","李娘十六青絲髮，畫帶雙花爲君結。","門前有路輕別離，唯恐歸來舊香滅。"]', '["團圓莫作波中月，潔白莫爲枝上雪。","月隨波动碎潾潾，雪似梅花不堪折。","李娘十六青絲髮，畫带雙花爲君結。","门前有路轻別離，唯恐归来旧香滅。"]', '诗', 'shi', '', NULL, '三洲詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bde15c6c-785e-4ae8-81a2-a8b47e4197dc', '春曉曲', '春晓曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["家臨長信往來道，乳燕雙雙拂煙草。","油壁車輕金犢肥，流蘇帳曉春雞早。","籠中嬌鳥暖猶睡，簾外落花閑不掃。","衰桃一樹近前池，似惜紅顏鏡中老。"]', '["家臨长信往来道，乳燕雙雙拂煙草。","油壁车轻金犢肥，流蘇帳晓春雞早。","籠中嬌鸟暖猶睡，簾外落花闲不掃。","衰桃一樹近前池，似惜紅顏镜中老。"]', '诗', 'shi', '', NULL, '春曉曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f90a58c4-7b3e-4e33-a76a-fe0891190458', '獵騎辭', '獵騎辞', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["早辭平扆殿，夕奉湘南宴。","香兔抱微煙，重鱗疊輕扇。","蠶飢使君馬，雁避將軍箭。","寶柱惜離弦，流黃悲赤縣。","理釵低舞鬢，換袖迴歌面。","晚柳未如絲，春花已如霰。","所嗟故里曲，不及青樓宴。"]', '["早辞平扆殿，夕奉湘南宴。","香兔抱微煙，重鱗叠轻扇。","蠶飢使君马，雁避將軍箭。","寶柱惜離弦，流黄悲赤縣。","理釵低舞鬢，換袖迴歌面。","晚柳未如絲，春花已如霰。","所嗟故里曲，不及青楼宴。"]', '诗', 'shi', '', NULL, '獵騎辭 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('934920aa-3eb2-47d9-809e-a4ed081160d6', '西州詞', '西州词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["悠悠復悠悠，昨日下西州。","西州風色好，遙見武昌樓。","武昌何鬱鬱，儂家定無匹。","小婦被流黃，登樓撫瑤瑟。","朱弦繁復輕，素手直淒清。","一彈三四解，掩抑似含情。","南樓登且望，西江廣復平。","艇子搖兩槳，催過石頭城。","門前烏臼樹，慘澹天將曙。","鸂鶒飛復還，郎隨早帆去。","迴頭語同伴，定復負情儂。","去帆不安幅，作抵使西風。","他日相尋索，莫作西州客。","西州人不歸，春草年年碧。"]', '["悠悠复悠悠，昨日下西州。","西州风色好，遙见武昌楼。","武昌何鬱鬱，儂家定無匹。","小婦被流黄，登楼撫瑤瑟。","朱弦繁复轻，素手直淒清。","一彈三四解，掩抑似含情。","南楼登且望，西江廣复平。","艇子搖兩槳，催過石头城。","门前烏臼樹，慘澹天將曙。","鸂鶒飞复還，郎隨早帆去。","迴头語同伴，定复負情儂。","去帆不安幅，作抵使西风。","他日相尋索，莫作西州客。","西州人不归，春草年年碧。"]', '诗', 'shi', '', NULL, '西州詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7522233e-072d-4ee6-b735-a3cef602acb2', '燒歌', '燒歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["起來望南山，山火燒山田。","微紅夕如滅，短燄復相連。","差差向巖石，冉冉凌青壁。","低隨迴風盡，遠照簷茅赤。","鄰翁能楚言，倚插欲澘然。","自言楚越俗，燒畬爲早田。","豆苗蟲促促，籬上花當屋。","廢棧豕歸欄，廣場雞啄粟。","新年春雨晴，處處賽神聲。","持錢就人卜，敲瓦隔林鳴。","卜得山上卦，歸來桑棗下。","吹火向白茅，腰鐮映赬蔗。","風驅槲葉煙，槲樹連平山。","迸星拂霞外，飛燼落堦前。","仰面呻復嚏，鴉娘咒豐歲。","誰知蒼翠容，盡作官家稅。"]', '["起来望南山，山火燒山田。","微紅夕如滅，短燄复相連。","差差向巖石，冉冉凌青壁。","低隨迴风尽，远照簷茅赤。","鄰翁能楚言，倚插欲澘然。","自言楚越俗，燒畬爲早田。","豆苗蟲促促，籬上花當屋。","廢棧豕归欄，廣場雞啄粟。","新年春雨晴，处处賽神声。","持錢就人卜，敲瓦隔林鳴。","卜得山上卦，归来桑棗下。","吹火向白茅，腰鐮映赬蔗。","风驱槲葉煙，槲樹連平山。","迸星拂霞外，飞燼落堦前。","仰面呻复嚏，鴉娘咒豐歲。","誰知蒼翠容，尽作官家稅。"]', '诗', 'shi', '', NULL, '燒歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('621a9d7f-47a8-4b77-acb3-c158adb156ea', '長安寺', '长安寺', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["仁祠寫露宮，長安佳氣濃。","煙樹含葱蒨，金剎映䒠茸。","繡戶香焚象，珠網玉盤龍。","寶題斜翡翠，天井倒芙蓉。","幡長迴遠吹，牕虛含曉風。","遊騎迷青鎖，歸鳥思華鐘。","雲栱承跗邐，羽葆背花重。","所嗟蓮社客，輕蕩不相從。"]', '["仁祠寫露宮，长安佳氣濃。","煙樹含葱蒨，金剎映䒠茸。","繡戶香焚象，珠網玉盤龙。","寶題斜翡翠，天井倒芙蓉。","幡长迴远吹，牕虛含晓风。","游騎迷青鎖，归鸟思华鐘。","云栱承跗邐，羽葆背花重。","所嗟蓮社客，轻蕩不相從。"]', '诗', 'shi', '', NULL, '長安寺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c845fa-0fc3-4908-add2-ffaa18f643f3', '和沈參軍招友生觀芙蓉池', '和沈參軍招友生观芙蓉池', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["桂棟坐清曉，瑤琴商鳳絲。","況聞楚澤香，適與秋風期。","遂從櫂萍客，靜嘯煙草湄。","倒影迴澹蕩，愁紅媚漣漪。","湘莖久鮮澀，宿雨增離披。","而我江海意，楚遊動夢思。","北渚水雲葉，南塘煙霧枝。","豈亡臺榭芳，獨與鷗鳥知。","珠墜魚迸淺，影多鳧泛遲。","落英不可攀，返照昏澄陂。"]', '["桂棟坐清晓，瑤琴商鳳絲。","況闻楚澤香，適與秋风期。","遂從櫂萍客，静嘯煙草湄。","倒影迴澹蕩，愁紅媚漣漪。","湘莖久鲜澀，宿雨增離披。","而我江海意，楚游动梦思。","北渚水云葉，南塘煙霧枝。","豈亡台榭芳，独與鷗鸟知。","珠墜鱼迸淺，影多鳧泛遲。","落英不可攀，返照昏澄陂。"]', '诗', 'shi', '', NULL, '和沈參軍招友生觀芙蓉池 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a92e0483-953e-4b6e-b1b2-57c249a8eb4f', '寓懷', '寓懷', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["誠足不顧得，妄矜徒有言。","語斯諒未盡，隱顯何悠然。","洵彼都邑盛，眷惟車馬喧。","自期尊客卿，非意干王孫。","銜知有貞爵，處實非厚顏。","苟無海岱氣，奚取壺漿恩。","唯絲南山楊，適我松菊香。","鵬鵾誠未憶，誰謂凌風翔。"]', '["誠足不顧得，妄矜徒有言。","語斯諒未尽，隐显何悠然。","洵彼都邑盛，眷惟车马喧。","自期尊客卿，非意干王孫。","銜知有貞爵，处實非厚顏。","苟無海岱氣，奚取壺漿恩。","唯絲南山楊，適我松菊香。","鵬鵾誠未憶，誰謂凌风翔。"]', '诗', 'shi', '', NULL, '寓懷 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c174dcf6-c37f-4f50-97f1-d716528c3aa4', '余昔自西濱得蘭數本移藝於庭亦既逾歲而芃然蕃殖自余遊者未始以芳草爲遇矣因悲夫物有厭常而反不若混然者有之焉遂寄情於此', '余昔自西濱得蘭數本移藝於庭亦既逾歲而芃然蕃殖自余游者未始以芳草爲遇矣因悲夫物有厭常而反不若混然者有之焉遂寄情於此', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["寓賞本殊致，意幽非我情。","吾常有流淺，外物無重輕。","各言藝幽深，彼美香素莖。","豈爲賞者設，自保孤根生。","易地無赤株，麗土亦同榮。","賞際林壑近，泛餘煙露清。","余懷既鬱陶，爾類徒縱橫。","妍蚩苟不信，寵辱何爲驚。","貞隱諒無迹，激時猶揀名。","幽叢靄綠畹，豈必懷歸耕。"]', '["寓賞本殊致，意幽非我情。","吾常有流淺，外物無重轻。","各言藝幽深，彼美香素莖。","豈爲賞者設，自保孤根生。","易地無赤株，丽土亦同榮。","賞際林壑近，泛餘煙露清。","余懷既鬱陶，爾類徒縱橫。","妍蚩苟不信，寵辱何爲驚。","貞隐諒無迹，激时猶揀名。","幽叢靄綠畹，豈必懷归耕。"]', '诗', 'shi', '', NULL, '余昔自西濱得蘭數本移藝於庭亦既逾歲而芃然蕃殖自余遊者未始以芳草爲遇矣因悲夫物有厭常而反不若混然者有之焉遂寄情於此 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ceade9d-e0c1-48a0-9d59-79d45e77004e', '秋日', '秋日', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["爽氣變昏旦，神臯徧原隰。","煙華久蕩搖，石澗仍清急。","柳闇山犬吠，蒲荒水禽立。","菊花明欲迷，棗葉光如濕。","天籟思林嶺，車塵倦都邑。","譸張夙所違，悔恡何由入。","芳草秋可藉，幽泉曉堪汲。","牧羊燒外鳴，林果雨中拾。","復此遂閑曠，翛然脫羇縶。","田收鳥雀喧，氣肅龍蛇蟄。","佳節足豐穰，良朋阻遊集。","沈機日寂寥，葆素常呼吸。","投迹倦攸往，放懷志所執。","良時有東菑，吾將事蓑笠。"]', '["爽氣变昏旦，神臯徧原隰。","煙华久蕩搖，石澗仍清急。","柳闇山犬吠，蒲荒水禽立。","菊花明欲迷，棗葉光如濕。","天籟思林嶺，车塵倦都邑。","譸張夙所違，悔恡何由入。","芳草秋可藉，幽泉晓堪汲。","牧羊燒外鳴，林果雨中拾。","复此遂闲曠，翛然脫羇縶。","田收鸟雀喧，氣肅龙蛇蟄。","佳節足豐穰，良朋阻游集。","沈機日寂寥，葆素常呼吸。","投迹倦攸往，放懷志所執。","良时有东菑，吾將事蓑笠。"]', '诗', 'shi', '', NULL, '秋日 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bceea86-b012-4e7e-b5af-159b28704c0d', '七夕', '七夕', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["鳴機札札停金梭，芙蓉澹蕩生池波。","神軒紅粉陳香羅，鳳低蟬薄愁雙蛾。","微光奕奕凌天河，鸞咽鶴唳飄颻歌。","彎橋銷盡愁奈何，天氣駘蕩雲陂陁。","平明花木有秋意，露濕綵盤蛛網多。"]', '["鳴機札札停金梭，芙蓉澹蕩生池波。","神軒紅粉陳香羅，鳳低蟬薄愁雙蛾。","微光奕奕凌天河，鸾咽鹤唳飄颻歌。","彎橋銷尽愁奈何，天氣駘蕩云陂陁。","平明花木有秋意，露濕綵盤蛛網多。"]', '诗', 'shi', '', NULL, '七夕 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28443bec-1873-488a-8352-3db8e3d8eb0f', '酬友人', '酬友人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["辭榮亦素尚，倦遊非夙心。","寧復思金籍，獨此臥煙林。","閑雲無定貌，佳樹有餘陰。","坐久芰荷發，釣闌茭葦深。","遊魚自搖漾，浴鳥故浮沈。","唯君清露夕，一爲灑煩襟。"]', '["辞榮亦素尚，倦游非夙心。","寧复思金籍，独此臥煙林。","闲云無定貌，佳樹有餘陰。","坐久芰荷發，釣闌茭葦深。","游鱼自搖漾，浴鸟故浮沈。","唯君清露夕，一爲灑煩襟。"]', '诗', 'shi', '', NULL, '酬友人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddcca25a-868e-4f11-bb63-24215ac28e19', '觀舞妓', '观舞妓', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["朔音悲嘒管，瑤踏動芳塵。","總袖時增怨，聽破復含嚬。","凝腰倚風軟，花題照錦春。","朱弦固淒緊，瓊樹亦迷人。"]', '["朔音悲嘒管，瑤踏动芳塵。","總袖时增怨，听破复含嚬。","凝腰倚风軟，花題照錦春。","朱弦固淒緊，瓊樹亦迷人。"]', '诗', 'shi', '', NULL, '觀舞妓 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('942a4217-2f9f-4c3e-ac53-cff400acea92', '邊笳曲', '邊笳曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["朔管迎秋動，雕陰雁來早。","上郡隱黃雲，天山吹白草。","嘶馬悲寒磧，朝陽照霜堡。","江南戍客心，門外芙蓉老。"]', '["朔管迎秋动，雕陰雁来早。","上郡隐黄云，天山吹白草。","嘶马悲寒磧，朝陽照霜堡。","江南戍客心，门外芙蓉老。"]', '诗', 'shi', '', NULL, '邊笳曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c35bdac8-4305-4f9f-8d9a-c3b6c7b67f7d', '經西塢偶題', '經西塢偶題', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["搖搖弱柳黃鸝啼，芳草無情人自迷。","日影明滅金色鯉，杏花唼喋青頭雞。","微紅柰蔕惹蜂粉，潔白芹芽穿燕泥。","借問含嚬向何事，昔年曾到武陵溪。"]', '["搖搖弱柳黄鸝啼，芳草無情人自迷。","日影明滅金色鯉，杏花唼喋青头雞。","微紅柰蔕惹蜂粉，潔白芹芽穿燕泥。","借问含嚬向何事，昔年曾到武陵溪。"]', '诗', 'shi', '', NULL, '經西塢偶題 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff47e1b4-5f0b-4907-a612-0898411c4f5d', '金虎臺', '金虎台', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["碧草連金虎，青苔蔽石麟。","皓齒芳塵起，纖腰玉樹春。","倚瑟紅鉛濕，分香翠黛嚬。","誰言奉陵寢，相顧復沾巾。"]', '["碧草連金虎，青苔蔽石麟。","皓齒芳塵起，纖腰玉樹春。","倚瑟紅鉛濕，分香翠黛嚬。","誰言奉陵寢，相顧复沾巾。"]', '诗', 'shi', '', NULL, '金虎臺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da47d59e-d416-4eae-a33f-7ccd0b141582', '俠客行', '俠客行', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["欲出鴻都門，陰雲蔽城闕。","寶劒黯如水，微紅濕餘血。","白馬夜頻驚，三更霸陵雪。"]', '["欲出鴻都门，陰云蔽城闕。","寶劒黯如水，微紅濕餘血。","白马夜頻驚，三更霸陵雪。"]', '诗', 'shi', '', NULL, '俠客行 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e5f3088-bc20-4b17-b0e3-610d455b16a3', '詠曉', '詠晓', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蟲歇紗牕靜，鴉散碧梧寒。","稍驚朝珮動，猶傳清漏殘。","亂珠凝燭淚，微紅上露盤。","褰衣復理鬢，餘潤拂芝蘭。"]', '["蟲歇紗牕静，鴉散碧梧寒。","稍驚朝珮动，猶傳清漏殘。","亂珠凝燭泪，微紅上露盤。","褰衣复理鬢，餘潤拂芝蘭。"]', '诗', 'shi', '', NULL, '詠曉 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88eb3cfc-8c6e-41c2-9276-7b75f38023ce', '芙蓉', '芙蓉', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["刺莖澹蕩碧，花片參差紅。","吳歌秋水冷，湘廟夜雲空。","濃豔香露裏，美人青鏡中。","南樓未歸客，一夕練塘東。"]', '["刺莖澹蕩碧，花片參差紅。","吳歌秋水冷，湘廟夜云空。","濃豔香露裏，美人青镜中。","南楼未归客，一夕練塘东。"]', '诗', 'shi', '', NULL, '芙蓉 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ab610c-0f3a-40b0-8a23-a8c71abfa51a', '勅勒歌塞北', '勅勒歌塞北', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["敕勒金𭘵壁，陰山無歲華。","帳外風飄雪，營前月照沙。","羌兒吹玉管，胡姬踏錦花。","却笑江南客，梅落不歸家。"]', '["敕勒金𭘵壁，陰山無歲华。","帳外风飄雪，營前月照沙。","羌兒吹玉管，胡姬踏錦花。","却笑江南客，梅落不归家。"]', '诗', 'shi', '', NULL, '勅勒歌塞北 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1ff8207-ac62-40fb-a687-aaad98bb5ad9', '邯鄲郭公詞', '邯鄲郭公词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["金笳悲故曲，玉座積深塵。","言是邯鄲伎，不見鄴城人。","青苔竟埋骨，紅粉自傷神。","唯有漳河柳，還向舊營春。"]', '["金笳悲故曲，玉座積深塵。","言是邯鄲伎，不见鄴城人。","青苔竟埋骨，紅粉自傷神。","唯有漳河柳，還向旧營春。"]', '诗', 'shi', '', NULL, '邯鄲郭公詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('692d77fb-1c84-4e00-977d-8b8069cfef5f', '古意', '古意', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["莫莫復莫莫，絲蘿緣澗壑。","散木無斧斤，纖莖得依託。","枝低浴鳥歇，根靜懸泉落。","不慮見春遲，空傷致身錯。"]', '["莫莫复莫莫，絲蘿緣澗壑。","散木無斧斤，纖莖得依託。","枝低浴鸟歇，根静懸泉落。","不慮见春遲，空傷致身錯。"]', '诗', 'shi', '', NULL, '古意 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ddc41e1-0ecf-4e8f-a183-fd98823787d1', '齊宮', '齊宮', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["白馬雜金飾，言從雕輦迴。","粉香隨笑度，鬢態伴愁來。","遠水斜如剪，青莎綠似裁。","所恨章華日，冉冉下層臺。"]', '["白马杂金飾，言從雕輦迴。","粉香隨笑度，鬢態伴愁来。","远水斜如剪，青莎綠似裁。","所恨章华日，冉冉下層台。"]', '诗', 'shi', '', NULL, '齊宮 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7b9fec0-ad1b-4c86-8acf-a177a660ade6', '春日', '春日', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["柳岸杏花稀，梅梁乳燕飛。","美人鸞鏡笑，嘶馬雁門歸。","楚宮雲影薄，臺城心賞違。","從來千里恨，邊色滿戎衣。"]', '["柳岸杏花稀，梅梁乳燕飞。","美人鸾镜笑，嘶马雁门归。","楚宮云影薄，台城心賞違。","從来千里恨，邊色满戎衣。"]', '诗', 'shi', '', NULL, '春日 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ebb92bd-fc53-4266-a78c-22b85681233f', '詠春幡', '詠春幡', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["閑庭見早梅，花影爲誰栽。","碧煙隨刃落，蟬鬢覺春來。","代郡嘶金勒，梵聲悲鏡臺。","玉釵風不定，香步獨徘徊。"]', '["闲庭见早梅，花影爲誰栽。","碧煙隨刃落，蟬鬢覺春来。","代郡嘶金勒，梵声悲镜台。","玉釵风不定，香步独徘徊。"]', '诗', 'shi', '', NULL, '詠春幡 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68abccc3-13d8-4c8e-a56f-560371a7b114', '陳宮詞', '陳宮词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["雞鳴人草草，香輦出宮花。","妓語細腰轉，馬嘶金面斜。","早鶯隨綵仗，驚雉避凝笳。","淅瀝湘風外，紅輪映曙霞。"]', '["雞鳴人草草，香輦出宮花。","妓語細腰轉，马嘶金面斜。","早鶯隨綵仗，驚雉避凝笳。","淅瀝湘风外，紅輪映曙霞。"]', '诗', 'shi', '', NULL, '陳宮詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c43230-0ade-4f34-8dfc-732909a8dfd2', '春日野行', '春日野行', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["騎馬踏煙莎，青春奈怨何。","蝶翎朝粉盡，鴉背夕陽多。","柳豔欺芳帶，山愁縈翠蛾。","別情無處說，方寸是星河。"]', '["騎马踏煙莎，青春奈怨何。","蝶翎朝粉尽，鴉背夕陽多。","柳豔欺芳带，山愁縈翠蛾。","別情無处说，方寸是星河。"]', '诗', 'shi', '', NULL, '春日野行 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d7d979a-a153-432e-898a-f2d472094796', '詠嚬', '詠嚬', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["毛羽歛愁翠，黛嬌攢豔春。","恨容偏落淚，低態定思人。","枕上夢隨月，扇邊歌遶塵。","玉鉤鸞不住，波淺石磷磷。"]', '["毛羽歛愁翠，黛嬌攢豔春。","恨容偏落泪，低態定思人。","枕上梦隨月，扇邊歌遶塵。","玉鉤鸾不住，波淺石磷磷。"]', '诗', 'shi', '', NULL, '詠嚬 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd0bdf0-f7fe-4503-93f6-0b6f9f99c103', '中書令裴公挽歌詞二首 一', '中书令裴公挽歌词二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["王儉風華首，蕭何社稷臣。","丹陽布衣客，蓮渚白頭人。","銘勒燕山暮，碑沈漢水春。","從今虛醉飽，無復汙車茵。"]', '["王儉风华首，蕭何社稷臣。","丹陽布衣客，蓮渚白头人。","銘勒燕山暮，碑沈漢水春。","從今虛醉飽，無复汙车茵。"]', '诗', 'shi', '', NULL, '中書令裴公挽歌詞二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8b1f8cc-24d3-48e4-b37d-a50f2c3faa8a', '中書令裴公挽歌詞二首 二', '中书令裴公挽歌词二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["箭下妖星落，風前殺氣廻。","國香荀令去，樓月庾公來。","玉璽終無慮，金縢意不開。","空嗟薦賢路，芳草滿燕臺。"]', '["箭下妖星落，风前殺氣廻。","国香荀令去，楼月庾公来。","玉璽終無慮，金縢意不开。","空嗟薦賢路，芳草满燕台。"]', '诗', 'shi', '', NULL, '中書令裴公挽歌詞二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71d3784-4553-48dc-a21c-62d29851dd42', '唐莊恪太子挽歌詞二首 一', '唐莊恪太子挽歌词二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["疊鼓辭宮殿，悲笳降杳冥。","影離雲外日，光滅火前星。","鄴客瞻秦苑，商公下漢庭。","依依陵樹色，空繞古原青。"]', '["叠鼓辞宮殿，悲笳降杳冥。","影離云外日，光滅火前星。","鄴客瞻秦苑，商公下漢庭。","依依陵樹色，空繞古原青。"]', '诗', 'shi', '', NULL, '唐莊恪太子挽歌詞二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a94f955-d5ad-4283-bec9-683276498157', '唐莊恪太子挽歌詞二首 二', '唐莊恪太子挽歌词二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["東府虛容衛，西園寄夢思。","鳳懸吹曲夜，雞斷問安時。","塵陌都人恨，霜郊賵馬悲。","唯餘埋璧地，煙草近丹墀。"]', '["东府虛容衛，西园寄梦思。","鳳懸吹曲夜，雞斷问安时。","塵陌都人恨，霜郊賵马悲。","唯餘埋璧地，煙草近丹墀。"]', '诗', 'shi', '', NULL, '唐莊恪太子挽歌詞二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20b551ac-35d4-4185-bfeb-17744c6b6e32', '祕書劉尚書挽歌詞二首 一', '祕书劉尚书挽歌词二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["王筆活鸞鳳，謝詩生芙蓉。","學筵開絳帳，談柄發洪鐘。","粉署見飛鵩，玉山猜臥龍。","遺風麗清韻，蕭散九原松。"]', '["王笔活鸾鳳，謝诗生芙蓉。","学筵开絳帳，談柄發洪鐘。","粉署见飞鵩，玉山猜臥龙。","遺风丽清韻，蕭散九原松。"]', '诗', 'shi', '', NULL, '祕書劉尚書挽歌詞二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35101887-613a-4b4c-bd6f-8a5095e35fac', '祕書劉尚書挽歌詞二首 二', '祕书劉尚书挽歌词二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["麈尾近良玉，鶴裘吹素絲。","壞陵殷浩謫，春墅謝安棊。","京口貴公子，襄陽諸女兒。","折花兼踏月，多唱柳郎詞。"]', '["麈尾近良玉，鹤裘吹素絲。","壞陵殷浩謫，春墅謝安棊。","京口貴公子，襄陽諸女兒。","折花兼踏月，多唱柳郎词。"]', '诗', 'shi', '', NULL, '祕書劉尚書挽歌詞二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d182f8c-6cad-4a43-af62-d5c1e8c8c154', '太子西池二首 一', '太子西池二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["梨花雪壓枝，鶯囀柳如絲。","嬾逐粧成曉，春融夢覺遲。","鬢輕全作影，嚬淺未成眉。","莫信張公子，窗間斷暗期。"]', '["梨花雪壓枝，鶯囀柳如絲。","嬾逐粧成晓，春融梦覺遲。","鬢轻全作影，嚬淺未成眉。","莫信張公子，窗间斷暗期。"]', '诗', 'shi', '', NULL, '太子西池二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edfb62e2-c4ec-4a65-b1af-129f7a69bbfa', '太子西池二首 二', '太子西池二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["花紅蘭紫莖，愁草雨新晴。","柳占三春色，鶯偷百鳥聲。","日長嫌輦重，風暖覺衣輕。","薄暮香塵起，長楊落照明。"]', '["花紅蘭紫莖，愁草雨新晴。","柳占三春色，鶯偷百鸟声。","日长嫌輦重，风暖覺衣轻。","薄暮香塵起，长楊落照明。"]', '诗', 'shi', '', NULL, '太子西池二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41e2e819-270c-4ae0-acab-8ede9188a7d0', '西陵道士茶歌', '西陵道士茶歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["乳竇濺濺通石脉，綠塵愁草春江色。","澗花入井水味香，山月當人松影直。","仙翁白扇霜鳥翎，拂壇夜讀黃庭經。","疎香皓齒有餘味，更覺鶴心通杳冥。"]', '["乳竇濺濺通石脉，綠塵愁草春江色。","澗花入井水味香，山月當人松影直。","仙翁白扇霜鸟翎，拂壇夜读黄庭經。","疎香皓齒有餘味，更覺鹤心通杳冥。"]', '诗', 'shi', '', NULL, '西陵道士茶歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7b40c94-b3a2-4edc-b11c-879fa8fec0d2', '過西堡塞北', '過西堡塞北', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["淺草乾河闊，叢棘廢城高。","白馬犀匕首，黑裘金佩刀。","霜清徹兔目，風急吹鵰毛。","一經何用厄，日暮涕沾袍。"]', '["淺草乾河闊，叢棘廢城高。","白马犀匕首，黑裘金佩刀。","霜清徹兔目，风急吹鵰毛。","一經何用厄，日暮涕沾袍。"]', '诗', 'shi', '', NULL, '過西堡塞北 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57eee7e4-f266-4988-a802-89e8deb2673a', '送李億東歸', '送李億东归', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["黃山遠隔秦樹，紫禁斜通渭城。","別路青青柳弱，前溪漠漠苔生。","和風澹蕩歸客，落月殷勤早鶯。","灞上金樽未飲，讌歌已有餘聲。"]', '["黄山远隔秦樹，紫禁斜通渭城。","別路青青柳弱，前溪漠漠苔生。","和风澹蕩归客，落月殷勤早鶯。","灞上金樽未饮，讌歌已有餘声。"]', '诗', 'shi', '', NULL, '送李億東歸 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53326c00-2c68-4274-84c1-8504e4aac1c6', '開聖寺', '开聖寺', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["路分谿石夾煙叢，十里蕭蕭古樹風。","出寺馬嘶秋色裏，向陵鴉亂夕陽中。","竹間泉落山廚靜，塔下僧歸影殿空。","猶有南朝舊碑在，恥將興廢問休公。"]', '["路分谿石夾煙叢，十里蕭蕭古樹风。","出寺马嘶秋色裏，向陵鴉亂夕陽中。","竹间泉落山廚静，塔下僧归影殿空。","猶有南朝旧碑在，恥將兴廢问休公。"]', '诗', 'shi', '', NULL, '開聖寺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0388b49-fa6b-481e-95b5-4f4e5185d028', '贈蜀府將', '贈蜀府將', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["十年分散劒關秋，萬事皆隨錦水流。","志氣已曾明漢節，功名猶自滯吳鉤。","鵰邊認箭寒雲重，馬上聽笳塞草愁。","今日逢君倍惆悵，灌嬰韓信盡封侯。"]', '["十年分散劒关秋，万事皆隨錦水流。","志氣已曾明漢節，功名猶自滯吳鉤。","鵰邊認箭寒云重，马上听笳塞草愁。","今日逢君倍惆悵，灌嬰韓信尽封侯。"]', '诗', 'shi', '', NULL, '贈蜀府將 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce2b4fd-2bd0-4e47-8742-2177fde229ad', '西江貽釣叟騫生', '西江貽釣叟騫生', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["晴江如鏡月如鉤，泛灩蒼茫送客愁。","夜淚潛生竹枝曲，春潮遙上木蘭舟。","事隨雲去身難到，夢逐煙銷水自流。","昨日歡娛竟何在，一枝梅謝楚江頭。"]', '["晴江如镜月如鉤，泛灩蒼茫送客愁。","夜泪潛生竹枝曲，春潮遙上木蘭舟。","事隨云去身难到，梦逐煙銷水自流。","昨日歡娛竟何在，一枝梅謝楚江头。"]', '诗', 'shi', '', NULL, '西江貽釣叟騫生 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a695e5e1-36eb-4d82-8fb6-0a52682192c4', '寄清源寺僧', '寄清源寺僧', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["石路無塵竹徑開，昔年曾伴戴顒來。","窗間半偈聞鐘後，松下殘棊送客回。","簾向玉峰藏夜雪，砌因藍水長秋苔。","白蓮社裹如相問，爲說遊人是姓雷。"]', '["石路無塵竹徑开，昔年曾伴戴顒来。","窗间半偈闻鐘後，松下殘棊送客回。","簾向玉峰藏夜雪，砌因藍水长秋苔。","白蓮社裹如相问，爲说游人是姓雷。"]', '诗', 'shi', '', NULL, '寄清源寺僧 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a63130-0876-491f-a91c-f7d5cad85e75', '重遊圭峰宗密禪師精廬', '重游圭峰宗密禪師精廬', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["百尺青崖三尺墳，微言已絕杳難聞。","戴顒今日稱居士，支遁他年識領軍。","暫對杉松如結社，偶同麋鹿自成羣。","故山弟子空廻首，葱嶺唯應見宋雲。"]', '["百尺青崖三尺墳，微言已絕杳难闻。","戴顒今日稱居士，支遁他年識領軍。","暫对杉松如結社，偶同麋鹿自成羣。","故山弟子空廻首，葱嶺唯應见宋云。"]', '诗', 'shi', '', NULL, '重遊圭峰宗密禪師精廬 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d343500-66fb-42a2-a32e-97e1e3e9be71', '題李處士幽居', '題李处士幽居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["水玉簪頭白角巾，瑤琴寂歷拂輕塵。","濃陰似帳紅薇晚，細雨如煙碧草春。","隔竹見籠疑有鶴，捲簾看畫靜無人。","南山自是忘年友，谷口徒稱鄭子真。"]', '["水玉簪头白角巾，瑤琴寂歷拂轻塵。","濃陰似帳紅薇晚，細雨如煙碧草春。","隔竹见籠疑有鹤，捲簾看畫静無人。","南山自是忘年友，谷口徒稱鄭子真。"]', '诗', 'shi', '', NULL, '題李處士幽居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac97d42b-8fef-42c9-829f-baafe89b4cdc', '利州南渡', '利州南渡', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["澹然空水對斜暉，曲島蒼茫接翠微。","波上馬嘶看櫂去，柳邊人歇待船歸。","數叢沙草羣鷗散，萬頃江田一鷺飛。","誰解乘舟尋范蠡，五湖煙水獨忘機。"]', '["澹然空水对斜暉，曲島蒼茫接翠微。","波上马嘶看櫂去，柳邊人歇待船归。","數叢沙草羣鷗散，万頃江田一鷺飞。","誰解乘舟尋范蠡，五湖煙水独忘機。"]', '诗', 'shi', '', NULL, '利州南渡 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f13425b8-aac5-4293-bd62-4ff620614a18', '贈李將軍', '贈李將軍', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["誰言荀羨愛功勳，年少登壇衆所聞。","曾以能書稱內史，又因明易號將軍。","金溝故事春長在，玉軸遺文火半焚。","不學龍驤畫山水，醉鄉無跡似閑雲。"]', '["誰言荀羨愛功勳，年少登壇衆所闻。","曾以能书稱內史，又因明易號將軍。","金溝故事春长在，玉軸遺文火半焚。","不学龙驤畫山水，醉乡無跡似闲云。"]', '诗', 'shi', '', NULL, '贈李將軍 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0340ecf4-9a26-451f-a8ac-a3cf62cc9334', '寒食日作', '寒食日作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["紅深綠暗逕相交，抱暖含芳披紫袍。","綵索平時牆婉娩，輕毬落處晚寥梢。","窗中草色妬雞卵，盤上芹泥憎燕巢。","自有玉樓春意在，不能騎馬度煙郊。"]', '["紅深綠暗逕相交，抱暖含芳披紫袍。","綵索平时牆婉娩，轻毬落处晚寥梢。","窗中草色妬雞卵，盤上芹泥憎燕巢。","自有玉楼春意在，不能騎马度煙郊。"]', '诗', 'shi', '', NULL, '寒食日作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aa683db-4203-4bec-b015-a8ec37aba283', '李羽處士寄新醖走筆戲酬', '李羽处士寄新醖走笔戲酬', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["高談有伴還成藪，沈醉無期即是鄉。","已恨流鶯欺謝客，更將浮蟻與劉郎。","簷前柳色分張綠，窗外花枝借助香。","所恨玳筵紅燭夜，草玄寥落近廻塘。"]', '["高談有伴還成藪，沈醉無期即是乡。","已恨流鶯欺謝客，更將浮蟻與劉郎。","簷前柳色分張綠，窗外花枝借助香。","所恨玳筵紅燭夜，草玄寥落近廻塘。"]', '诗', 'shi', '', NULL, '李羽處士寄新醖走筆戲酬 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('470fdb98-6897-4278-b3a7-6ea6016f9627', '郊居秋日有懷一二知己', '郊居秋日有懷一二知己', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["稻田鳧雁滿晴沙，釣渚歸來一逕斜。","門帶果林招邑吏，井分蔬圃屬鄰家。","臯原寂歷垂禾穗，桑竹參差映豆花。","自笑謾懷經濟策，不將心事許煙霞。"]', '["稻田鳧雁满晴沙，釣渚归来一逕斜。","门带果林招邑吏，井分蔬圃屬鄰家。","臯原寂歷垂禾穗，桑竹參差映豆花。","自笑謾懷經濟策，不將心事許煙霞。"]', '诗', 'shi', '', NULL, '郊居秋日有懷一二知己 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6a0618e-0935-48b1-a252-d56fa4cd55de', '題友人池亭', '題友人池亭', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["月榭風亭繞曲池，粉垣廻互瓦參差。","侵簾片白搖翻影，落鏡愁紅寫倒枝。","鸂鶒刷毛花蕩漾，鷺鷥拳足雪離披。","山翁醉後如相憶，羽扇清樽我自知。"]', '["月榭风亭繞曲池，粉垣廻互瓦參差。","侵簾片白搖翻影，落镜愁紅寫倒枝。","鸂鶒刷毛花蕩漾，鷺鷥拳足雪離披。","山翁醉後如相憶，羽扇清樽我自知。"]', '诗', 'shi', '', NULL, '題友人池亭 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2597e95e-2867-4e8c-9cca-51944484b1f3', '南湖', '南湖', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["湖上微風入檻涼，翻翻菱荇滿廻塘。","野船著岸偎春草，水鳥帶波飛夕陽。","蘆葉有聲疑霧雨，浪花無際似瀟湘。","飄然篷艇東歸客，盡日相看憶楚鄉。"]', '["湖上微风入檻涼，翻翻菱荇满廻塘。","野船著岸偎春草，水鸟带波飞夕陽。","蘆葉有声疑霧雨，浪花無際似瀟湘。","飄然篷艇东归客，尽日相看憶楚乡。"]', '诗', 'shi', '', NULL, '南湖 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a916dbf1-65fd-405c-b894-90a546c0ac00', '贈袁司錄', '贈袁司錄', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["一朝辭滿有心期，花發楊園雪壓枝。","劉尹故人諳往事，謝郎諸弟得新知。","金釵醉就胡姬畫，玉管閑留洛客吹。","記得襄陽耆舊語，不堪風景峴山碑。"]', '["一朝辞满有心期，花發楊园雪壓枝。","劉尹故人諳往事，謝郎諸弟得新知。","金釵醉就胡姬畫，玉管闲留洛客吹。","記得襄陽耆旧語，不堪风景峴山碑。"]', '诗', 'shi', '', NULL, '贈袁司錄 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f793728-5900-4155-b48d-4acce7ee6744', '題西明寺僧院', '題西明寺僧院', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["曾識匡山遠法師，低松片石對前墀。","爲尋名畫來過院，因訪閑人得看棊。","新雁參差雲碧處，寒鴉遼亂葉紅時。","自知終有張華識，不向滄洲州理釣絲。"]', '["曾識匡山远法師，低松片石对前墀。","爲尋名畫来過院，因訪闲人得看棊。","新雁參差云碧处，寒鴉遼亂葉紅时。","自知終有張华識，不向滄洲州理釣絲。"]', '诗', 'shi', '', NULL, '題西明寺僧院 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc9b30b9-4137-4872-a3ca-b8af7cfc36bd', '偶題', '偶題', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["微風和暖日鮮明，草色迷人向渭城。","吳客捲簾閑不語，楚娥攀樹獨含情。","紅垂果蔕櫻桃重，黃染花叢蝶粉輕。","自恨青樓無近信，不將心事許卿卿。"]', '["微风和暖日鲜明，草色迷人向渭城。","吳客捲簾闲不語，楚娥攀樹独含情。","紅垂果蔕櫻桃重，黄染花叢蝶粉轻。","自恨青楼無近信，不將心事許卿卿。"]', '诗', 'shi', '', NULL, '偶題 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a7be2d6-34fd-4fd6-8674-c62fe2cd8fec', '寄湘陰閻少府乞釣輪子', '寄湘陰閻少府乞釣輪子', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["釣輪形與月輪同，獨繭和煙影似空。","若向三湘逢雁信，莫辭千里寄漁翁。","篷聲夜滴松江雨，菱葉秋傳鏡水風。","終日垂鉤還有意，尺書多在錦鱗中。"]', '["釣輪形與月輪同，独繭和煙影似空。","若向三湘逢雁信，莫辞千里寄漁翁。","篷声夜滴松江雨，菱葉秋傳镜水风。","終日垂鉤還有意，尺书多在錦鱗中。"]', '诗', 'shi', '', NULL, '寄湘陰閻少府乞釣輪子 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fdda368-6d56-48a7-9f8b-d1a6cb5ba2fb', '哭王元裕', '哭王元裕', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["聞說蕭郎逐逝川，伯牙因此絕清弦。","柳邊猶憶青驄影，墳上俄生碧草煙。","篋裏詩書疑謝後，夢中風貌似潘前。","他時若到相尋處，碧樹紅樓自宛然。"]', '["闻说蕭郎逐逝川，伯牙因此絕清弦。","柳邊猶憶青驄影，墳上俄生碧草煙。","篋裏诗书疑謝後，梦中风貌似潘前。","他时若到相尋处，碧樹紅楼自宛然。"]', '诗', 'shi', '', NULL, '哭王元裕 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96f7caf5-2ea5-4f65-9f75-107f207dfac7', '法雲寺雙檜', '法云寺雙檜', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["晉朝名輩此離羣，想對濃陰去住分。","題處尚尋王內史，畫時應是顧將軍。","長廊夜靜聲疑雨，古殿秋深影勝雲。","一下南臺到人世，曉泉清籟更難聞。"]', '["晉朝名輩此離羣，想对濃陰去住分。","題处尚尋王內史，畫时應是顧將軍。","长廊夜静声疑雨，古殿秋深影勝云。","一下南台到人世，晓泉清籟更难闻。"]', '诗', 'shi', '', NULL, '法雲寺雙檜 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25f7203e-270e-4a9c-9118-39c18b3bc7b9', '送陳嘏之侯官兼簡李常侍', '送陳嘏之侯官兼簡李常侍', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["縱得步兵無綠蟻，不緣句漏有丹砂。","殷勤爲報同袍友，我亦無心似海槎。","春服照塵連草色，夜船聞雨滴蘆花。","梅仙自是青雲客，莫羨相如却到家。"]', '["縱得步兵無綠蟻，不緣句漏有丹砂。","殷勤爲報同袍友，我亦無心似海槎。","春服照塵連草色，夜船闻雨滴蘆花。","梅仙自是青云客，莫羨相如却到家。"]', '诗', 'shi', '', NULL, '送陳嘏之侯官兼簡李常侍 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('debd689a-f10e-4069-afe8-91855547c735', '春日野行', '春日野行', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["雨漲西塘金堤斜，碧草芊芊晴吐芽。","野岸明媚山芍藥，水田呌噪官蝦蟇。","鏡中有浪動菱蔓，陌上無風飄柳花。","何事輕橈句溪客，綠萍方好不歸家。"]', '["雨漲西塘金堤斜，碧草芊芊晴吐芽。","野岸明媚山芍藥，水田呌噪官蝦蟇。","镜中有浪动菱蔓，陌上無风飄柳花。","何事轻橈句溪客，綠萍方好不归家。"]', '诗', 'shi', '', NULL, '春日野行 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a02279d-5b32-474c-a76d-32e242e8651f', '溪上行', '溪上行', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["綠塘漾漾煙濛濛，張翰此來情不窮。","雪羽䙰褷立倒影，金鱗撥剌跳晴空。","風翻荷葉一向白，雨濕蓼花千穗紅。","心羨夕陽波上客，片時歸夢釣船中。"]', '["綠塘漾漾煙濛濛，張翰此来情不窮。","雪羽䙰褷立倒影，金鱗撥剌跳晴空。","风翻荷葉一向白，雨濕蓼花千穗紅。","心羨夕陽波上客，片时归梦釣船中。"]', '诗', 'shi', '', NULL, '溪上行 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5654e427-74f4-42cf-b2fa-aa374e5b8ca0', '投翰林蕭舍人', '投翰林蕭舍人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["人間鵷鷺杳難從，獨恨金扉直九重。","萬象晚歸仁壽鏡，百花春隔景陽鐘。","紫微芒動詞初出，紅燭香殘誥未封。","每過朱門愛庭樹，一枝何日許相容。"]', '["人间鵷鷺杳难從，独恨金扉直九重。","万象晚归仁壽镜，百花春隔景陽鐘。","紫微芒动词初出，紅燭香殘誥未封。","每過朱门愛庭樹，一枝何日許相容。"]', '诗', 'shi', '', NULL, '投翰林蕭舍人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a37dd2b9-5b29-4c37-9e0d-d5696ea354bd', '春日偶作', '春日偶作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["西園一曲豔陽歌，擾擾車塵負薜蘿。","自欲放懷猶未得，不知經世竟如何。","夜聞猛雨判花盡，寒戀重衾覺夢多。","釣渚別來應更好，春風還爲起微波。"]', '["西园一曲豔陽歌，擾擾车塵負薜蘿。","自欲放懷猶未得，不知經世竟如何。","夜闻猛雨判花尽，寒戀重衾覺梦多。","釣渚別来應更好，春风還爲起微波。"]', '诗', 'shi', '', NULL, '春日偶作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a426ca-921b-49c3-bcb8-e22bb614a144', '春暮宴罷寄宋壽先輩', '春暮宴罷寄宋壽先輩', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["斜掩朱門花外鐘，曉鶯時節好相逢。","窗間桃蘂宿粧在，雨後牡丹春睡濃。","蘇小風姿迷下蔡，馬卿才調似臨邛。","誰憐芳草生三徑，參佐橋西陸士龍。"]', '["斜掩朱门花外鐘，晓鶯时節好相逢。","窗间桃蘂宿粧在，雨後牡丹春睡濃。","蘇小风姿迷下蔡，马卿才調似臨邛。","誰怜芳草生三徑，參佐橋西陸士龙。"]', '诗', 'shi', '', NULL, '春暮宴罷寄宋壽先輩 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('002b2c32-f2c5-4088-bce6-7b41e90fc18a', '馬嵬驛', '马嵬驛', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["穆滿曾爲物外遊，六龍經此暫淹留。","返魂無驗青煙滅，埋血空生碧草愁。","香輦却歸長樂殿，曉鐘還下景陽樓。","甘泉不復重相見，誰道文成是故侯。"]', '["穆满曾爲物外游，六龙經此暫淹留。","返魂無驗青煙滅，埋血空生碧草愁。","香輦却归长乐殿，晓鐘還下景陽楼。","甘泉不复重相见，誰道文成是故侯。"]', '诗', 'shi', '', NULL, '馬嵬驛 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5347f8af-04ed-450b-90e1-39b677ae59f6', '和道溪君別業', '和道溪君別業', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["積潤初銷碧草新，鳳陽晴日帶雕輪。","風飄弱柳平橋晚，雪點寒梅小苑春。","屏上樓臺陳後主，鏡中金翠李夫人。","花房透露紅珠落，蛺蝶雙飛護粉塵。"]', '["積潤初銷碧草新，鳳陽晴日带雕輪。","风飄弱柳平橋晚，雪点寒梅小苑春。","屏上楼台陳後主，镜中金翠李夫人。","花房透露紅珠落，蛺蝶雙飞護粉塵。"]', '诗', 'shi', '', NULL, '和道溪君別業 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01ac69a9-82d3-41ec-a20d-b81f338ae4b8', '奉天西佛寺', '奉天西佛寺', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["憶昔狂童犯順年，玉虬閑暇出甘泉。","宗臣欲舞千鈞劒，追騎猶觀七寶鞭。","星背紫垣終埽地，日歸黃道却當天。","至今南頓諸耆舊，猶指榛蕪作弄田。"]', '["憶昔狂童犯順年，玉虬闲暇出甘泉。","宗臣欲舞千鈞劒，追騎猶观七寶鞭。","星背紫垣終埽地，日归黄道却當天。","至今南頓諸耆旧，猶指榛蕪作弄田。"]', '诗', 'shi', '', NULL, '奉天西佛寺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73e98562-ad4b-4d7c-b6a3-aa9ba7899d20', '題望苑驛', '題望苑驛', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["弱柳千條杏一枝，半含春雨半垂絲。","景陽寒井人難到，長樂晨鐘鳥自知。","花影至今通博望，樹名從此號相思。","分明十二樓前月，不向西陵照盛姬。"]', '["弱柳千條杏一枝，半含春雨半垂絲。","景陽寒井人难到，长乐晨鐘鸟自知。","花影至今通博望，樹名從此號相思。","分明十二楼前月，不向西陵照盛姬。"]', '诗', 'shi', '', NULL, '題望苑驛 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('365ccc87-dc31-430c-9ea6-b99e955bef96', '寄分司元庶子兼呈元處士', '寄分司元庶子兼呈元处士', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["閉門高臥莫長嗟，水木凝暉屬謝家。","緱嶺參差殘曉雪，洛波清淺露晴沙。","劉公春盡蕪菁色，華[廙]愁深苜蓿花。","月榭知君還悵望，碧霄煙闊雁行斜。"]', '["閉门高臥莫长嗟，水木凝暉屬謝家。","緱嶺參差殘晓雪，洛波清淺露晴沙。","劉公春尽蕪菁色，华[廙]愁深苜蓿花。","月榭知君還悵望，碧霄煙闊雁行斜。"]', '诗', 'shi', '', NULL, '寄分司元庶子兼呈元處士 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89eb81af-1a1f-4d3e-bd71-527ec7df6a3d', '題柳', '題柳', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["楊柳千條拂面絲，綠煙金穗不勝吹。","香隨靜婉歌塵起，影伴嬌嬈舞袖垂。","羌管一聲何處曲，流鶯百囀最高枝。","千門九陌花如雪，飛過宮牆兩自知。"]', '["楊柳千條拂面絲，綠煙金穗不勝吹。","香隨静婉歌塵起，影伴嬌嬈舞袖垂。","羌管一声何处曲，流鶯百囀最高枝。","千门九陌花如雪，飞過宮牆兩自知。"]', '诗', 'shi', '', NULL, '題柳 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6216babf-bc9e-4940-a94c-228ef1146788', '和友人悼亡', '和友人悼亡', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["玉貌潘郎淚滿衣，畫羅輕鬢[雨]霏微。","紅蘭委露愁難盡，白馬朝天望不歸。","寶鏡塵昏鸞影在，鈿箏弦斷雁行稀。","春來多少傷心事，碧草侵堦粉蝶飛。"]', '["玉貌潘郎泪满衣，畫羅轻鬢[雨]霏微。","紅蘭委露愁难尽，白马朝天望不归。","寶镜塵昏鸾影在，鈿箏弦斷雁行稀。","春来多少傷心事，碧草侵堦粉蝶飞。"]', '诗', 'shi', '', NULL, '和友人悼亡 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99d510b8-68e2-409d-a0a1-3a261a88777a', '李羽處士故里', '李羽处士故里', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["柳不成絲草帶煙，海槎東去鶴歸天。","愁腸斷處春何限，病眼開時月正圓。","花若有情還悵望，水應無事莫潺湲。","終知此恨銷難盡，辜負南華第一篇。"]', '["柳不成絲草带煙，海槎东去鹤归天。","愁腸斷处春何限，病眼开时月正圓。","花若有情還悵望，水應無事莫潺湲。","終知此恨銷难尽，辜負南华第一篇。"]', '诗', 'shi', '', NULL, '李羽處士故里 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9247b61-367d-49e4-8872-f9c1165f080a', '却經商山寄昔同行人', '却經商山寄昔同行人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["曾道逍遙第一篇，爾來無處不恬然。","便同南郭能忘象，兼笑東林學坐禪。","人事轉新花爛熳，客程依舊水潺湲。","若敎猶作當時意，應有垂絲在鬢邊。"]', '["曾道逍遙第一篇，爾来無处不恬然。","便同南郭能忘象，兼笑东林学坐禪。","人事轉新花爛熳，客程依旧水潺湲。","若敎猶作當时意，應有垂絲在鬢邊。"]', '诗', 'shi', '', NULL, '却經商山寄昔同行人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbafea96-0799-4aa4-8e79-ccab790e974d', '池塘七夕', '池塘七夕', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["月出西南露氣秋，綺羅河漢在斜溝。","楊家繡作鴛鴦幔，張氏金爲翡翠鉤。","香燭有花妨宿燕，畫屏無睡待牽牛。","萬家砧杵三篙水，一夕橫塘似舊遊。"]', '["月出西南露氣秋，綺羅河漢在斜溝。","楊家繡作鴛鴦幔，張氏金爲翡翠鉤。","香燭有花妨宿燕，畫屏無睡待牽牛。","万家砧杵三篙水，一夕橫塘似旧游。"]', '诗', 'shi', '', NULL, '池塘七夕 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89826a88-d58a-442a-8e0c-225cdea57e54', '偶遊', '偶游', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["曲巷斜臨一水間，小門終日不開關。","紅珠斗帳櫻桃熟，金尾屏風孔雀閑。","雲髻幾迷芳草蝶，額黃無限夕陽山。","與君便是鴛鴦侶，休向人間覓往還。"]', '["曲巷斜臨一水间，小门終日不开关。","紅珠斗帳櫻桃熟，金尾屏风孔雀闲。","云髻幾迷芳草蝶，額黄無限夕陽山。","與君便是鴛鴦侶，休向人间覓往還。"]', '诗', 'shi', '', NULL, '偶遊 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc1bd77b-fcbe-4a18-9a10-c81abe36712f', '寄河南杜少尹', '寄河南杜少尹', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["十載歸來鬢未凋，玳簪珠履見常僚。","豈關名利分榮路，自有才華作慶霄。","鳥影參差經上苑，騎聲斷續過中橋。","夕陽亭畔山如畫，應念田歌正寂寥。"]', '["十載归来鬢未凋，玳簪珠履见常僚。","豈关名利分榮路，自有才华作慶霄。","鸟影參差經上苑，騎声斷續過中橋。","夕陽亭畔山如畫，應念田歌正寂寥。"]', '诗', 'shi', '', NULL, '寄河南杜少尹 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a89caac5-432b-4272-8c29-d058b56131da', '贈知音', '贈知音', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["翠羽花冠碧樹雞，未明先向短牆啼。","窗間謝女青蛾歛，門外蕭郎白馬嘶。","星漢漸移庭竹影，露珠猶綴野花迷。","景陽宮裏鐘初動，不語垂鞭上柳堤。"]', '["翠羽花冠碧樹雞，未明先向短牆啼。","窗间謝女青蛾歛，门外蕭郎白马嘶。","星漢漸移庭竹影，露珠猶綴野花迷。","景陽宮裏鐘初动，不語垂鞭上柳堤。"]', '诗', 'shi', '', NULL, '贈知音 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6879701e-c949-4b63-9431-d43baa941e69', '過陳琳墓', '過陳琳墓', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["曾於青史見遺文，今日飄蓬過古墳。","詞客有靈應識我，霸才無主始憐君。","石麟埋沒藏春草，銅雀荒涼對暮雲。","莫怪臨風倍惆悵，欲將書劒學從軍。"]', '["曾於青史见遺文，今日飄蓬過古墳。","词客有靈應識我，霸才無主始怜君。","石麟埋沒藏春草，銅雀荒涼对暮云。","莫怪臨风倍惆悵，欲將书劒学從軍。"]', '诗', 'shi', '', NULL, '過陳琳墓 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0903b2a-03fb-401a-bdee-2ccea5073e32', '題崔公池舊遊', '題崔公池旧游', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["皎鏡方塘菡萏秋，此來重見採蓮舟。","誰能不逐當年樂，還恐添成異日愁。","紅豔影多風嫋嫋，碧空雲斷水悠悠。","簷前依舊青山色，盡日無人獨上樓。"]', '["皎镜方塘菡萏秋，此来重见採蓮舟。","誰能不逐當年乐，還恐添成異日愁。","紅豔影多风嫋嫋，碧空云斷水悠悠。","簷前依旧青山色，尽日無人独上楼。"]', '诗', 'shi', '', NULL, '題崔公池舊遊 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0401d1b-d034-4553-b059-fa4c052a32d6', '回中作', '回中作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蒼莽寒空遠色愁，嗚嗚戍角上高樓。","吳姬怨思吹雙管，燕客悲歌別五侯。","千里關山邊草暮，一星烽火朔雲秋。","夜來霜重西風起，隴水無聲凍不流。"]', '["蒼莽寒空远色愁，嗚嗚戍角上高楼。","吳姬怨思吹雙管，燕客悲歌別五侯。","千里关山邊草暮，一星烽火朔云秋。","夜来霜重西风起，隴水無声凍不流。"]', '诗', 'shi', '', NULL, '回中作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a456cc8d-2cd1-41c9-9cc8-52163216510d', '西江上送漁父', '西江上送漁父', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["却逐嚴光向若耶，釣輪菱櫂寄年華。","三秋梅雨愁楓葉，一夜篷舟宿葦花。","不見水雲應有夢，偶隨鷗鷺便成家。","白蘋風起樓船暮，江燕雙雙五兩斜。"]', '["却逐嚴光向若耶，釣輪菱櫂寄年华。","三秋梅雨愁楓葉，一夜篷舟宿葦花。","不见水云應有梦，偶隨鷗鷺便成家。","白蘋风起楼船暮，江燕雙雙五兩斜。"]', '诗', 'shi', '', NULL, '西江上送漁父 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7807234-8674-468f-a2d9-87f574aaf5c0', '經故秘書崔監揚州南塘舊居', '經故秘书崔監揚州南塘旧居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["昔年曾識范安成，松竹風姿鶴性情。","西掖曙河橫漏響，北山秋月照江聲。","乘舟覓吏經輿縣，爲酒求官得步兵。","千頃水流通故墅，至今留得謝公名。"]', '["昔年曾識范安成，松竹风姿鹤性情。","西掖曙河橫漏响，北山秋月照江声。","乘舟覓吏經輿縣，爲酒求官得步兵。","千頃水流通故墅，至今留得謝公名。"]', '诗', 'shi', '', NULL, '經故秘書崔監揚州南塘舊居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99e03e7b-8b9c-4080-8575-9b6bbd399c34', '經故秘書崔監揚州南塘舊居', '經故秘书崔監揚州南塘旧居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["昔年曽識謝宣城，松竹風姿鶴性情。","唯向舊山留月色，偶逢秋澗似琴聲。","乗舟覔吏經輿縣，爲酒求官得步兵。","玉柄寂寥譚客散，却尋池閣淚縱横。"]', '["昔年曽識謝宣城，松竹风姿鹤性情。","唯向旧山留月色，偶逢秋澗似琴声。","乗舟覔吏經輿縣，爲酒求官得步兵。","玉柄寂寥譚客散，却尋池閣泪縱横。"]', '诗', 'shi', '', NULL, '經故秘書崔監揚州南塘舊居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdfe4ef8-154d-4eb9-98a8-785a11628662', '七夕', '七夕', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["鵲歸燕去兩悠悠，青瑣西南月似鉤。","天上歲時星右轉，世間離別水東流。","金風入樹千門夜，銀漢橫空萬象秋。","蘇小橫塘通桂檝，未應清淺隔牽牛。"]', '["鵲归燕去兩悠悠，青瑣西南月似鉤。","天上歲时星右轉，世间離別水东流。","金风入樹千门夜，銀漢橫空万象秋。","蘇小橫塘通桂檝，未應清淺隔牽牛。"]', '诗', 'shi', '', NULL, '七夕 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2bc2287-eefa-487a-8469-b8697b95cf46', '題韋籌博士草堂', '題韋籌博士草堂', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["玄晏先生已白頭，不隨鵷鷺狎羣鷗。","元卿謝免開三徑，平仲朝歸臥一裘。","醉後獨知殷甲子，病來猶作晉春秋。","滄浪未濯塵纓在，野水無情處處流。"]', '["玄晏先生已白头，不隨鵷鷺狎羣鷗。","元卿謝免开三徑，平仲朝归臥一裘。","醉後独知殷甲子，病来猶作晉春秋。","滄浪未濯塵纓在，野水無情处处流。"]', '诗', 'shi', '', NULL, '題韋籌博士草堂 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb60707b-7659-4c24-ad73-d0fe1d88eb62', '和友人題壁', '和友人題壁', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["沖尚猶來出範圍，肯將經世作風徽。","三台位缺嚴陵臥，百戰功高范蠡歸。","自欲一鳴驚鶴寢，不應孤憤學牛衣。","西州未有看棋暇，澗戶何由得掩扉。"]', '["沖尚猶来出範圍，肯將經世作风徽。","三台位缺嚴陵臥，百戰功高范蠡归。","自欲一鳴驚鹤寢，不應孤憤学牛衣。","西州未有看棋暇，澗戶何由得掩扉。"]', '诗', 'shi', '', NULL, '和友人題壁 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db92fa1d-ae7d-44ea-9939-a6180917ac91', '春日將欲東歸寄新及第苗紳先輩', '春日將欲东归寄新及第苗紳先輩', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["幾年辛苦與君同，得喪悲歡盡是空。","猶喜故人先折桂，自憐羈客尚飄蓬。","三春月照千山道，十日花開一夜風。","知有杏園無路入，馬前惆悵滿枝紅。"]', '["幾年辛苦與君同，得喪悲歡尽是空。","猶喜故人先折桂，自怜羈客尚飄蓬。","三春月照千山道，十日花开一夜风。","知有杏园無路入，马前惆悵满枝紅。"]', '诗', 'shi', '', NULL, '春日將欲東歸寄新及第苗紳先輩 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('020fd638-66f0-452d-893d-61875b0b0a54', '經李徵君故居', '經李徵君故居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["露濃煙重草萋萋，樹映闌干柳拂堤。","一院落花無客醉，五更殘月有鶯啼。","芳筵想像情難盡，故榭荒涼路已迷。","惆悵羸驂往來慣，每經門巷亦長嘶。"]', '["露濃煙重草萋萋，樹映闌干柳拂堤。","一院落花無客醉，五更殘月有鶯啼。","芳筵想像情难尽，故榭荒涼路已迷。","惆悵羸驂往来慣，每經门巷亦长嘶。"]', '诗', 'shi', '', NULL, '經李徵君故居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c79fd881-06c9-4678-a589-c55609a97720', '送崔郎中赴幕', '送崔郎中赴幕', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["一別黔巫似斷弦，故交東去更淒然。","心遊目送三千里，雨散雲飛二十年。","發跡豈勞天上桂，屬詞還得幕中蓮。","相思休話長安遠，江月隨人處處圓。"]', '["一別黔巫似斷弦，故交东去更淒然。","心游目送三千里，雨散云飞二十年。","發跡豈勞天上桂，屬词還得幕中蓮。","相思休話长安远，江月隨人处处圓。"]', '诗', 'shi', '', NULL, '送崔郎中赴幕 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d192b2b3-174b-4270-834f-c8d1421fdc7c', '經舊遊', '經旧游', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["珠箔金鉤對彩橋，昔年於此見嬌嬈。","香燈悵望飛瓊鬢，涼月慇勤碧玉簫。","屏倚故窗山六扇，柳垂寒砌露千條。","壞牆經雨蒼苔遍，拾得當時舊翠翹。"]', '["珠箔金鉤对彩橋，昔年於此见嬌嬈。","香灯悵望飞瓊鬢，涼月慇勤碧玉簫。","屏倚故窗山六扇，柳垂寒砌露千條。","壞牆經雨蒼苔遍，拾得當时旧翠翹。"]', '诗', 'shi', '', NULL, '經舊遊 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35265b90-cd0b-4ddb-9c8a-014eecb21b6f', '老君廟', '老君廟', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["紫氣氤氳捧半巖，蓮峰仙掌共巉巉。","廟前晚色連寒水，天外斜陽帶遠帆。","百二關山扶玉座，五千文字閟瑤緘。","自憐金骨無人識，知有飛龜在石函。"]', '["紫氣氤氳捧半巖，蓮峰仙掌共巉巉。","廟前晚色連寒水，天外斜陽带远帆。","百二关山扶玉座，五千文字閟瑤緘。","自怜金骨無人識，知有飞龟在石函。"]', '诗', 'shi', '', NULL, '老君廟 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b215d262-2d70-43d9-bd9e-b43c0eb26c0e', '過五丈原', '過五丈原', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["鐵馬雲雕久絕塵，柳陰高壓漢營春。","天晴殺氣屯關右，夜半妖星照渭濱。","下國臥龍空誤主，中原逐鹿不因人。","象牀錦帳無言語，從此譙周是老臣。"]', '["鐵马云雕久絕塵，柳陰高壓漢營春。","天晴殺氣屯关右，夜半妖星照渭濱。","下国臥龙空誤主，中原逐鹿不因人。","象牀錦帳無言語，從此譙周是老臣。"]', '诗', 'shi', '', NULL, '過五丈原 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ea550b-5635-4a41-ad28-e44718b6c24f', '和友人傷歌姬', '和友人傷歌姬', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["月缺花殘莫愴然，花須終發月終圓。","更能何事銷芳念，亦有濃華委逝川。","一曲豔歌留婉轉，九原春草妬嬋娟。","王孫莫學多情客，自古多情損少年。"]', '["月缺花殘莫愴然，花須終發月終圓。","更能何事銷芳念，亦有濃华委逝川。","一曲豔歌留婉轉，九原春草妬嬋娟。","王孫莫学多情客，自古多情損少年。"]', '诗', 'shi', '', NULL, '和友人傷歌姬 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46fe9d66-3468-4e36-a6bd-987fcc04943d', '山中與諸道友夜坐聞邊防不寧因示同志', '山中與諸道友夜坐闻邊防不寧因示同志', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["龍砂鐵馬犯煙塵，跡近羣鷗意倍親。","風卷蓬根屯戊己，月移松影守庚申。","韜鈐豈足爲經濟，巖壑何嘗是隱淪。","心許故人知此意，古來知者竟誰人。"]', '["龙砂鐵马犯煙塵，跡近羣鷗意倍親。","风卷蓬根屯戊己，月移松影守庚申。","韜鈐豈足爲經濟，巖壑何嘗是隐淪。","心許故人知此意，古来知者竟誰人。"]', '诗', 'shi', '', NULL, '山中與諸道友夜坐聞邊防不寧因示同志 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11745c54-4dcd-4092-af49-02cfb69925d6', '秘書省有賀監知章草題詩筆力遒健風尚高遠拂塵尋玩因有此作', '秘书省有賀監知章草題诗笔力遒健风尚高远拂塵尋玩因有此作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["越溪漁客賀知章，任達憐才愛酒狂。","鸂鶒葦花隨釣艇，蛤蜊菰菜夢橫塘。","幾年涼月拘華省，一宿秋風憶故鄉。","榮路脫身終自得，福庭迴首莫相忘。","出籠鸞鶴歸遼海，落筆龍蛇滿壞牆。","李白死來無醉客，可憐神彩弔殘陽。"]', '["越溪漁客賀知章，任達怜才愛酒狂。","鸂鶒葦花隨釣艇，蛤蜊菰菜梦橫塘。","幾年涼月拘华省，一宿秋风憶故乡。","榮路脫身終自得，福庭迴首莫相忘。","出籠鸾鹤归遼海，落笔龙蛇满壞牆。","李白死来無醉客，可怜神彩弔殘陽。"]', '诗', 'shi', '', NULL, '秘書省有賀監知章草題詩筆力遒健風尚高遠拂塵尋玩因有此作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a64ba7b6-c02b-4962-90db-6b2277d438f8', '題裴晉公林亭', '題裴晉公林亭', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["謝傅林亭暑氣微，山丘零落閟音徽。","東山終爲蒼生起，南浦虛言白首歸。","池鳳已傳春水浴，渚禽猶帶夕陽飛。","悠然到此忘情處，一日何妨有萬幾。"]', '["謝傅林亭暑氣微，山丘零落閟音徽。","东山終爲蒼生起，南浦虛言白首归。","池鳳已傳春水浴，渚禽猶带夕陽飞。","悠然到此忘情处，一日何妨有万幾。"]', '诗', 'shi', '', NULL, '題裴晉公林亭 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfa680d3-fd3c-43d1-8299-149ab2d121c5', '車駕西遊因而有作', '车駕西游因而有作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["宣曲長楊瑞氣凝，上林狐兔待秋鷹。","誰將詞賦陪雕輦，寂寞相如臥茂林。"]', '["宣曲长楊瑞氣凝，上林狐兔待秋鷹。","誰將词賦陪雕輦，寂寞相如臥茂林。"]', '诗', 'shi', '', NULL, '車駕西遊因而有作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac20b52-5102-4a6f-b5a3-1673ef7c8711', '傷溫德彝', '傷溫德彝', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["昔年戎虜犯榆關，一敗龍城匹馬還。","侯印不聞封李廣，他人丘壟似天山。"]', '["昔年戎虜犯榆关，一敗龙城匹马還。","侯印不闻封李廣，他人丘壟似天山。"]', '诗', 'shi', '', NULL, '傷溫德彝 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50f5662f-f3a3-4e72-8a0b-dda78fc55330', '贈少年', '贈少年', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["江海相逢客恨多，秋風葉下洞庭波。","酒酣夜別淮陰市，月照高樓一曲歌。"]', '["江海相逢客恨多，秋风葉下洞庭波。","酒酣夜別淮陰市，月照高楼一曲歌。"]', '诗', 'shi', '', NULL, '贈少年 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce7a789e-e4f6-4b0c-8be7-b08ccc404595', '贈鄭徵君家匡山首春與丞相贊皇公遊止', '贈鄭徵君家匡山首春與丞相贊皇公游止', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["一拋蘭櫂逐燕鴻，曾向江湖識謝公。","每到朱門還悵望，故山多在畫屏中。"]', '["一拋蘭櫂逐燕鴻，曾向江湖識謝公。","每到朱门還悵望，故山多在畫屏中。"]', '诗', 'shi', '', NULL, '贈鄭徵君家匡山首春與丞相贊皇公遊止 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35426ef-7a2f-430d-b6a5-c7b419cb28a3', '夏中病痁作', '夏中病痁作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["山鬼揚威正氣愁，便辭珍簟襲狐裘。","西窗一夕悲人事，團扇無情不待秋。"]', '["山鬼揚威正氣愁，便辞珍簟襲狐裘。","西窗一夕悲人事，團扇無情不待秋。"]', '诗', 'shi', '', NULL, '夏中病痁作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d741600-24bd-422e-aa9c-003d158a7898', '題友人居', '題友人居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["盡日松堂看畫圖，綺疏岑寂似清都。","若敎煙水無鷗鳥，張翰何由到五湖。"]', '["尽日松堂看畫圖，綺疏岑寂似清都。","若敎煙水無鷗鸟，張翰何由到五湖。"]', '诗', 'shi', '', NULL, '題友人居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee8d09e5-41e5-4e09-856c-c90bd119d2d8', '題李相公勅賜錦屏風', '題李相公勅賜錦屏风', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["豐沛曾爲社稷臣，賜書名畫墨猶新。","幾人同保山河誓，猶自栖栖九陌塵。"]', '["豐沛曾爲社稷臣，賜书名畫墨猶新。","幾人同保山河誓，猶自栖栖九陌塵。"]', '诗', 'shi', '', NULL, '題李相公勅賜錦屏風 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d70f376f-02f0-4742-819a-09ea1f121910', '蔡中郎墳', '蔡中郎墳', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["古墳零落野花春，聞說中郎有後身。","今日愛才非昔日，莫拋心力作詞人。"]', '["古墳零落野花春，闻说中郎有後身。","今日愛才非昔日，莫拋心力作词人。"]', '诗', 'shi', '', NULL, '蔡中郎墳 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9afee2bc-4123-4e11-aace-ced5551c732d', '元處士池上', '元处士池上', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蓼穗菱叢思蟪蛄，水螢江鳥滿煙蒲。","愁紅一片風前落，池上秋波似五湖。"]', '["蓼穗菱叢思蟪蛄，水螢江鸟满煙蒲。","愁紅一片风前落，池上秋波似五湖。"]', '诗', 'shi', '', NULL, '元處士池上 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dabc2faf-6bbe-4c03-9815-37986e7205df', '華陰韋氏林亭', '华陰韋氏林亭', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["自有林亭不得閑，陌塵宮樹是非間。","終南長在茅簷外，別向人間看華山。"]', '["自有林亭不得闲，陌塵宮樹是非间。","終南长在茅簷外，別向人间看华山。"]', '诗', 'shi', '', NULL, '華陰韋氏林亭 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0adcf238-f09f-4cd1-9422-07935f0c4979', '寄裴生乞釣鉤', '寄裴生乞釣鉤', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["一隨菱櫂謁王侯，深媿移文負釣舟。","今日太湖風色好，却將詩句乞魚鉤。"]', '["一隨菱櫂謁王侯，深媿移文負釣舟。","今日太湖风色好，却將诗句乞鱼鉤。"]', '诗', 'shi', '', NULL, '寄裴生乞釣鉤 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af13fb2-8c2d-46ab-ba36-b8e34ae88d12', '長安春晚二首 一', '长安春晚二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["曲江春半日遲遲，正是王孫悵望時。","杏花落盡不歸去，江上東風吹柳絲。"]', '["曲江春半日遲遲，正是王孫悵望时。","杏花落尽不归去，江上东风吹柳絲。"]', '诗', 'shi', '', NULL, '長安春晚二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1d2ae4a-a30e-40d8-a4d2-6c5df69714b3', '長安春晚二首 二', '长安春晚二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["四方無事太平年，萬象鮮明禁火前。","九重細雨惹春色，輕染龍池楊柳煙。"]', '["四方無事太平年，万象鲜明禁火前。","九重細雨惹春色，轻染龙池楊柳煙。"]', '诗', 'shi', '', NULL, '長安春晚二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb7776cf-d5f0-4a07-83dc-a87a8c807dd4', '三月十八日雪中作', '三月十八日雪中作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["芍藥薔薇語早梅，不知誰是豔陽才。","今朝領得春風意，不復饒君雪裏開。"]', '["芍藥薔薇語早梅，不知誰是豔陽才。","今朝領得春风意，不复饒君雪裏开。"]', '诗', 'shi', '', NULL, '三月十八日雪中作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e6ddbb-746f-43ec-a57b-61741d3579c0', '咸陽值雨', '咸陽值雨', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["咸陽橋上雨如懸，萬點空濛隔釣船。","還似洞庭春水色，晚雲將入岳陽天。"]', '["咸陽橋上雨如懸，万点空濛隔釣船。","還似洞庭春水色，晚云將入岳陽天。"]', '诗', 'shi', '', NULL, '咸陽值雨 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a539e5e-4148-4ae8-b2eb-81b42b25173a', '彈箏人', '彈箏人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["天寶年中事玉皇，曾將新曲敎寧王。","鈿蟬金雁今零落，一曲伊州淚萬行。"]', '["天寶年中事玉皇，曾將新曲敎寧王。","鈿蟬金雁今零落，一曲伊州泪万行。"]', '诗', 'shi', '', NULL, '彈箏人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7d50789-e0d5-4291-8014-eddf65a124df', '瑤瑟怨', '瑤瑟怨', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["冰簟銀牀夢不成，碧天如水夜雲輕。","雁聲遠過瀟湘去，十二樓中月自明。"]', '["冰簟銀牀梦不成，碧天如水夜云轻。","雁声远過瀟湘去，十二楼中月自明。"]', '诗', 'shi', '', NULL, '瑤瑟怨 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5127877-3f72-413e-84e2-16f6314c7d70', '題端正樹', '題端正樹', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["路傍佳樹碧雲愁，曾侍金輿幸驛樓。","草木榮枯似人事，綠陰寂寞漢陵秋。"]', '["路傍佳樹碧云愁，曾侍金輿幸驛楼。","草木榮枯似人事，綠陰寂寞漢陵秋。"]', '诗', 'shi', '', NULL, '題端正樹 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('052ad12c-02a6-4aab-9c12-7288c042f99d', '渭上題三首 一', '渭上題三首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["呂公榮達子陵歸，萬古煙波遶釣磯。","橋上一通名利迹，至今江鳥背人飛。"]', '["呂公榮達子陵归，万古煙波遶釣磯。","橋上一通名利迹，至今江鸟背人飞。"]', '诗', 'shi', '', NULL, '渭上題三首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5379f566-4b31-4745-b607-4a0c9db2ccb6', '渭上題三首 二', '渭上題三首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["目極雲霄思浩然，風帆一片水連天。","輕橈便是東歸路，不肯忘機作釣船。"]', '["目極云霄思浩然，风帆一片水連天。","轻橈便是东归路，不肯忘機作釣船。"]', '诗', 'shi', '', NULL, '渭上題三首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a201ba89-e924-4180-bb6a-c7234c6e5325', '渭上題三首 三', '渭上題三首 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["煙水何曾息世機，暫時相向亦依依。","所嗟白首磻谿叟，一下漁舟更不歸。"]', '["煙水何曾息世機，暫时相向亦依依。","所嗟白首磻谿叟，一下漁舟更不归。"]', '诗', 'shi', '', NULL, '渭上題三首 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62e8c1ab-86e8-4b82-9afa-22491fd8b845', '經故翰林袁學士居', '經故翰林袁学士居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["劒逐驚波玉委塵，謝安門下更何人。","西州城外花千樹，盡是羊曇醉後春。"]', '["劒逐驚波玉委塵，謝安门下更何人。","西州城外花千樹，尽是羊曇醉後春。"]', '诗', 'shi', '', NULL, '經故翰林袁學士居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('882c4ec8-8fd9-44cb-a7f5-da4d500f5643', '題城南杜邠公林亭', '題城南杜邠公林亭', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["卓氏壚前金線柳，隋家堤畔錦帆風。","貪爲兩地分霖雨，不見池蓮照水紅。"]', '["卓氏壚前金線柳，隋家堤畔錦帆风。","貪爲兩地分霖雨，不见池蓮照水紅。"]', '诗', 'shi', '', NULL, '題城南杜邠公林亭 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c16f2a83-a9c0-437e-b3ad-2789717505a0', '夜看牡丹', '夜看牡丹', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["高低深淺一闌紅，把火殷勤遶露叢。","希逸近來成嬾病，不能容易向春風。"]', '["高低深淺一闌紅，把火殷勤遶露叢。","希逸近来成嬾病，不能容易向春风。"]', '诗', 'shi', '', NULL, '夜看牡丹 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb7518c4-1baf-41ca-a286-4f15f1b77cb5', '宿城南亡友別墅', '宿城南亡友別墅', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["水流花落歎浮生，又伴遊人宿杜城。","還似昔年殘夢裏，透簾斜月獨聞鶯。"]', '["水流花落歎浮生，又伴游人宿杜城。","還似昔年殘梦裏，透簾斜月独闻鶯。"]', '诗', 'shi', '', NULL, '宿城南亡友別墅 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a67da702-57ba-4f4b-9f7e-dfa60e3eeb25', '過分水嶺', '過分水嶺', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["溪水無情似有情，入山三日得同行。","嶺頭更是分頭處，惜別潺湲一夜聲。"]', '["溪水無情似有情，入山三日得同行。","嶺头更是分头处，惜別潺湲一夜声。"]', '诗', 'shi', '', NULL, '過分水嶺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('772ce407-979a-463b-9194-8f9c67f0d4c2', '鄠杜郊居', '鄠杜郊居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["槿籬芳援近樵家，壠麥青青一逕斜。","寂寞遊人寒食後，夜來風雨送梨花。"]', '["槿籬芳援近樵家，壠麦青青一逕斜。","寂寞游人寒食後，夜来风雨送梨花。"]', '诗', 'shi', '', NULL, '鄠杜郊居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f061ff5-50d9-40d3-95c4-c5a2bd50b4f6', '題河中紫極宮', '題河中紫極宮', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["昔年曾伴玉真遊，每到仙宮即是秋。","曼倩不歸花落盡，滿叢煙露月當樓。"]', '["昔年曾伴玉真游，每到仙宮即是秋。","曼倩不归花落尽，满叢煙露月當楼。"]', '诗', 'shi', '', NULL, '題河中紫極宮 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fe8dd20-37a1-464b-99a5-bcbd7673103b', '四皓', '四皓', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["商於甪里便成功，一寸沈機萬古同。","但得戚姬甘定分，不應真有紫芝翁。"]', '["商於甪里便成功，一寸沈機万古同。","但得戚姬甘定分，不應真有紫芝翁。"]', '诗', 'shi', '', NULL, '四皓 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d065d8b2-3fd1-4a75-861b-84d334ebcf9b', '贈張鍊師', '贈張鍊師', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["丹溪藥盡變金骨，清洛月寒吹玉笙。","他日隱居無訪處，碧桃花發水縱橫。"]', '["丹溪藥尽变金骨，清洛月寒吹玉笙。","他日隐居無訪处，碧桃花發水縱橫。"]', '诗', 'shi', '', NULL, '贈張鍊師 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85eda7b9-c445-4432-a693-309b4a502e5a', '病中書懷呈友人', '病中书懷呈友人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["逸足皆先路，窮郊獨向隅。","頑童逃廣柳，羸馬臥平蕪。","黃卷嗟誰問，朱弦偶自娛。","鹿鳴皆綴士，雌伏竟非夫。","采地荒遺野，爰田失故都。","亡羊猶博簺，牧馬倦呼盧。","奕世參周祿，承家學魯儒。","功庸留劒舃，銘戒在盤盂。","經濟懷良畫，行藏識遠圖。","未能鳴楚玉，空欲握隋珠。","定爲魚緣木，曾因兔守株。","五車堆縹帙，三逕闔繩樞。","適與羣英集，將期善價沽。","葉龍圖夭矯，燕鼠笑胡盧。","賦分知前定，寒心畏厚誣。","躡塵追慶忌，操劒學班輸。","文囿陪多士，神州試大巫。","對雖希鼓瑟，名亦濫吹竽。","正使猜奔競，何嘗計有無。","鎦惔虛訪覓，王霸竟揶揄。","市義虛焚券，關譏謾棄繻。","至言今信矣，微尚亦悲夫。","白雪調歌響，清風樂舞雩。","脅肩難黽勉，搔首易嗟吁。","角勝非能者，推賢見射乎。","兕觥增恐竦，杯水失錙銖。","粉垛收丹采，金髇隱僕姑。","垂櫜羞盡爵，揚觶辱彎弧。","虎拙休言畫，龍希莫學屠。","轉蓬隨欵段，耘草闢墁壚。","受業鄉名鄭，藏機谷號愚。","質文精等貫，琴筑韻相須。","築室連中野，誅茅接上腴。","葦花綸虎落，松癭鬬欒櫨。","靜語鶯相對，閑眠鶴浪俱。","蘂多勞蝶翅，香酷墜蜂鬚。","芳草迷三島，澄波似五湖。","躍魚翻藻荇，愁鷺睡葭蘆。","暝洘藏鸂鶒，幽屏臥鷓鴣。","苦辛隨蓻殖，甘旨仰樵蘇。","笑語空懷橘，窮愁亦據梧。","尚能甘半菽，非敢薄生芻。","釣石封蒼蘚，芳蹊豔絳跗。","樹蘭畦繚繞，穿竹路縈紆。","機杼非桑女，林園異木奴。","橫竿窺赤鯉，持翳望青鸕。","泮水思芹味，琅琊得稻租。","杖輕藜擁腫，衣破芰披敷。","芳意憂鶗鴂，愁聲覺蟪蛄。","短簷喧語燕，高木墮飢鼯。","事迫離幽墅，貧牽犯畏途。","愛憎防杜摯，悲歎似楊朱。","旅食常過衛，羇遊欲渡瀘。","塞歌傷督護，邊角思單于。","堡戍標槍槊，關河鏁舳艫。","威容尊大樹，邢法避秋荼。","遠目窮千里，歸心寄九衢。","寢甘誠繫滯，漿饋貴睢盱。","懷刺名先遠，干時道自孤。","齒牙頻激發，簦笈尚崎嶇。","蓮府侯門貴，霜臺帝命俞。","驥蹄初躡景，鵬翅欲摶扶。","寓直廻驄馬，分曹對暝烏。","百神歆彷彿，孤竹韻含胡。","鳳闕分班立，鵷行竦劒趨。","觸邪承密勿，持法奉訏謨。","鳴玉鏘登降，衡牙嚮曳婁。","祀親和氏璧，香近博山鑪。","瑞景森瓊樹，輕冰瑩玉壺。","豸冠簪鐵柱，螭首對金鋪。","內史書千卷，將軍畫一廚。","眼明驚氣象，心死伏規模。","豈意觀文物，何勞琢碔砆。","草肥牧騕褭，苔澀淬昆吾。","鄉思巢枝鳥，年華過隙駒。","銜恩空抱影，酬德未捐軀。","時輩推良友，家聲繼令圖。","致身傷短翮，驤首顧疲駑。","班馬方齊騖，陳雷亦並驅。","昔皆言爾志，今亦畏吾徒。","有氣干牛斗，無人辯轆轤。","客來斟綠蟻，妻試踏青蚨。","積毀方銷骨，微瑕懼掩瑜。","蛇矛猶轉戰，魚服自囚拘。","欲就欺人事，何能逭鬼誅。","是非迷覺夢，行役議秦吳。","凜冽風埃慘，蕭條草木枯。","低徊傷志氣，蒙犯變肌膚。","旅雁唯聞呌，飢鷹不待呼。","夢梭拋促織，心繭學蜘蛛。","寧復機難料，庸非信未孚。","激揚銜箭虎，疑懼聽冰狐。","處己將營窟，論心若合符。","浪言輝棣萼，何所託葭莩。","喬木能求友，危巢莫嚇雛。","風華飄領袖，詩禮拜衾繻。","欹枕情何苦，同舟道豈殊。","放懷親蕙芷，收迹異桑榆。","贈遠聊攀柳，栽書欲截蒲。","瞻風無限淚，廻首更踟躕。"]', '["逸足皆先路，窮郊独向隅。","頑童逃廣柳，羸马臥平蕪。","黄卷嗟誰问，朱弦偶自娛。","鹿鳴皆綴士，雌伏竟非夫。","采地荒遺野，爰田失故都。","亡羊猶博簺，牧马倦呼盧。","奕世參周祿，承家学魯儒。","功庸留劒舃，銘戒在盤盂。","經濟懷良畫，行藏識远圖。","未能鳴楚玉，空欲握隋珠。","定爲鱼緣木，曾因兔守株。","五车堆縹帙，三逕闔繩樞。","適與羣英集，將期善價沽。","葉龙圖夭矯，燕鼠笑胡盧。","賦分知前定，寒心畏厚誣。","躡塵追慶忌，操劒学班輸。","文囿陪多士，神州試大巫。","对雖希鼓瑟，名亦濫吹竽。","正使猜奔競，何嘗計有無。","鎦惔虛訪覓，王霸竟揶揄。","市義虛焚券，关譏謾棄繻。","至言今信矣，微尚亦悲夫。","白雪調歌响，清风乐舞雩。","脅肩难黽勉，搔首易嗟吁。","角勝非能者，推賢见射乎。","兕觥增恐竦，杯水失錙銖。","粉垛收丹采，金髇隐僕姑。","垂櫜羞尽爵，揚觶辱彎弧。","虎拙休言畫，龙希莫学屠。","轉蓬隨欵段，耘草闢墁壚。","受業乡名鄭，藏機谷號愚。","質文精等貫，琴筑韻相須。","築室連中野，誅茅接上腴。","葦花綸虎落，松癭鬬欒櫨。","静語鶯相对，闲眠鹤浪俱。","蘂多勞蝶翅，香酷墜蜂鬚。","芳草迷三島，澄波似五湖。","躍鱼翻藻荇，愁鷺睡葭蘆。","暝洘藏鸂鶒，幽屏臥鷓鴣。","苦辛隨蓻殖，甘旨仰樵蘇。","笑語空懷橘，窮愁亦據梧。","尚能甘半菽，非敢薄生芻。","釣石封蒼蘚，芳蹊豔絳跗。","樹蘭畦繚繞，穿竹路縈紆。","機杼非桑女，林园異木奴。","橫竿窺赤鯉，持翳望青鸕。","泮水思芹味，琅琊得稻租。","杖轻藜擁腫，衣破芰披敷。","芳意憂鶗鴂，愁声覺蟪蛄。","短簷喧語燕，高木墮飢鼯。","事迫離幽墅，貧牽犯畏途。","愛憎防杜摯，悲歎似楊朱。","旅食常過衛，羇游欲渡瀘。","塞歌傷督護，邊角思單于。","堡戍標槍槊，关河鏁舳艫。","威容尊大樹，邢法避秋荼。","远目窮千里，归心寄九衢。","寢甘誠繫滯，漿饋貴睢盱。","懷刺名先远，干时道自孤。","齒牙頻激發，簦笈尚崎嶇。","蓮府侯门貴，霜台帝命俞。","驥蹄初躡景，鵬翅欲摶扶。","寓直廻驄马，分曹对暝烏。","百神歆彷彿，孤竹韻含胡。","鳳闕分班立，鵷行竦劒趨。","觸邪承密勿，持法奉訏謨。","鳴玉鏘登降，衡牙嚮曳婁。","祀親和氏璧，香近博山鑪。","瑞景森瓊樹，轻冰瑩玉壺。","豸冠簪鐵柱，螭首对金鋪。","內史书千卷，將軍畫一廚。","眼明驚氣象，心死伏規模。","豈意观文物，何勞琢碔砆。","草肥牧騕褭，苔澀淬昆吾。","乡思巢枝鸟，年华過隙駒。","銜恩空抱影，酬德未捐軀。","时輩推良友，家声繼令圖。","致身傷短翮，驤首顧疲駑。","班马方齊騖，陳雷亦並驱。","昔皆言爾志，今亦畏吾徒。","有氣干牛斗，無人辯轆轤。","客来斟綠蟻，妻試踏青蚨。","積毀方銷骨，微瑕懼掩瑜。","蛇矛猶轉戰，鱼服自囚拘。","欲就欺人事，何能逭鬼誅。","是非迷覺梦，行役議秦吳。","凜冽风埃慘，蕭條草木枯。","低徊傷志氣，蒙犯变肌膚。","旅雁唯闻呌，飢鷹不待呼。","梦梭拋促织，心繭学蜘蛛。","寧复機难料，庸非信未孚。","激揚銜箭虎，疑懼听冰狐。","处己將營窟，論心若合符。","浪言輝棣萼，何所託葭莩。","喬木能求友，危巢莫嚇雛。","风华飄領袖，诗禮拜衾繻。","欹枕情何苦，同舟道豈殊。","放懷親蕙芷，收迹異桑榆。","贈远聊攀柳，栽书欲截蒲。","瞻风無限泪，廻首更踟躕。"]', '诗', 'shi', '', NULL, '病中書懷呈友人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4591b990-c99c-4b8d-8ef3-97076a4dda8c', '感舊陳情五十韻獻淮南李僕射', '感旧陳情五十韻獻淮南李僕射', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["嵇紹垂髫日，山濤筮仕年。","琴樽陳席上，紈綺拜牀前。","鄰里纔三徙，雲霄已九遷。","感深情戃怳，言發淚潺湲。","憶昔龍圖盛，方今鶴羽全。","桂枝香可襲，楊葉舊頻穿。","玉籍標人瑞，金丹化地仙。","賦成攢筆寫，歌出滿城傳。","既矯排虛翅，將持造物權。","萬靈思鼓鑄，羣品待陶甄。","視草絲綸出，持綱雨露懸。","法行黃道內，居近翠華邊。","書迹臨湯鼎，吟聲接舜絃。","白麻紅燭夜，清漏紫微天。","雷電隨神筆，魚龍落彩牋。","閑宵陪雍畤，清暑在甘泉。","耿介非持祿，優游是養賢。","冰清臨百粵，風靡化三川。","委寄崇推轂，威儀壓控弦。","梁園提彀騎，淮水換戎旃。","照日青油濕，迎風錦帳鮮。","黛蛾陳二八，珠履列三千。","舞轉廻紅袖，歌愁歛翠鈿。","滿堂開照曜，分座儼嬋娟。","油額芙蓉帳，香塵玳瑁筵。","繡旗隨影合，金陣似波旋。","緹幕深廻互，朱門暗接連。","彩虬蟠畫戟，花馬立金鞭。","有客將誰託，無媒竊自憐。","抑揚中散曲，漂泊孝廉船。","未展干時策，徒拋負郭田。","轉蓬猶邈爾，懷橘更澘然。","投足乖蹊逕，冥心向簡編。","未知魚躍地，空媿鹿鳴篇。","稷下期方至，漳濱病未痊。","定非籠外鳥，真是殼中蟬。","蕙逕鄰幽澹，荆扉興靜便。","草堂苔點點，蔬囿水濺濺。","釣罷溪雲重，樵歸澗月圓。","嬾多成宿疢，愁甚似春眠。","木直終難怨，膏明只自煎。","鄭鄉空健羨，陳榻未招延。","旅食逢春盡，羈遊爲事牽。","宦無毛義檄，婚乏阮脩錢。","冉弱營中柳，披敷幕下蓮。","儻能容委質，非敢望差肩。","澀劒猶堪淬，餘朱或可研。","從師當鼓篋，窮理久忘筌。","折簡能榮瘁，遺簪莫棄捐。","韶光如見借，寒谷變風煙。"]', '["嵇紹垂髫日，山濤筮仕年。","琴樽陳席上，紈綺拜牀前。","鄰里纔三徙，云霄已九遷。","感深情戃怳，言發泪潺湲。","憶昔龙圖盛，方今鹤羽全。","桂枝香可襲，楊葉旧頻穿。","玉籍標人瑞，金丹化地仙。","賦成攢笔寫，歌出满城傳。","既矯排虛翅，將持造物權。","万靈思鼓鑄，羣品待陶甄。","視草絲綸出，持綱雨露懸。","法行黄道內，居近翠华邊。","书迹臨湯鼎，吟声接舜絃。","白麻紅燭夜，清漏紫微天。","雷電隨神笔，鱼龙落彩牋。","闲宵陪雍畤，清暑在甘泉。","耿介非持祿，優游是養賢。","冰清臨百粵，风靡化三川。","委寄崇推轂，威儀壓控弦。","梁园提彀騎，淮水換戎旃。","照日青油濕，迎风錦帳鲜。","黛蛾陳二八，珠履列三千。","舞轉廻紅袖，歌愁歛翠鈿。","满堂开照曜，分座儼嬋娟。","油額芙蓉帳，香塵玳瑁筵。","繡旗隨影合，金陣似波旋。","緹幕深廻互，朱门暗接連。","彩虬蟠畫戟，花马立金鞭。","有客將誰託，無媒竊自怜。","抑揚中散曲，漂泊孝廉船。","未展干时策，徒拋負郭田。","轉蓬猶邈爾，懷橘更澘然。","投足乖蹊逕，冥心向簡編。","未知鱼躍地，空媿鹿鳴篇。","稷下期方至，漳濱病未痊。","定非籠外鸟，真是殼中蟬。","蕙逕鄰幽澹，荆扉兴静便。","草堂苔点点，蔬囿水濺濺。","釣罷溪云重，樵归澗月圓。","嬾多成宿疢，愁甚似春眠。","木直終难怨，膏明只自煎。","鄭乡空健羨，陳榻未招延。","旅食逢春尽，羈游爲事牽。","宦無毛義檄，婚乏阮脩錢。","冉弱營中柳，披敷幕下蓮。","儻能容委質，非敢望差肩。","澀劒猶堪淬，餘朱或可研。","從師當鼓篋，窮理久忘筌。","折簡能榮瘁，遺簪莫棄捐。","韶光如见借，寒谷变风煙。"]', '诗', 'shi', '', NULL, '感舊陳情五十韻獻淮南李僕射 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05555152-7c48-44c6-ba85-def3e3d1244c', '題翠微寺二十二韻', '題翠微寺二十二韻', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["邠土初成邑，虞賓竟讓王。","乾符初得位，天弩夜收鋩。","偃息齊三代，優游念四方。","萬靈扶正寢，千嶂抱重岡。","幽石歸階陛，喬柯入棟梁。","火雲如沃雪，湯殿似含霜。","澗籟添仙曲，巖花借御香。","野麋陪獸舞，林鳥逐鵷行。","鏡寫三秦色，窗搖八水光。","問雲徵楚女，疑粉試何郎。","蘭芷承雕輦，杉蘿入畫堂。","受朝松露曉，頒朔桂煙涼。","嵐濕金鋪外，溪鳴錦幄傍。","倚絲憂漢祖，持璧告秦皇。","短景催風馭，長星屬羽觴。","儲君猶問豎，元老已登牀。","鶴蓋趨平樂，雞人下建章。","龍髯悲滿眼，螭首淚沾裳。","疊鼓嚴靈杖，吹笙送夕陽。","斷泉辭劒佩，昏日伴旂常。","遺廟青蓮在，頹垣碧草芳。","無因奏韶濩，流涕對幽篁。"]', '["邠土初成邑，虞賓竟讓王。","乾符初得位，天弩夜收鋩。","偃息齊三代，優游念四方。","万靈扶正寢，千嶂抱重岡。","幽石归階陛，喬柯入棟梁。","火云如沃雪，湯殿似含霜。","澗籟添仙曲，巖花借御香。","野麋陪獸舞，林鸟逐鵷行。","镜寫三秦色，窗搖八水光。","问云徵楚女，疑粉試何郎。","蘭芷承雕輦，杉蘿入畫堂。","受朝松露晓，頒朔桂煙涼。","嵐濕金鋪外，溪鳴錦幄傍。","倚絲憂漢祖，持璧告秦皇。","短景催风馭，长星屬羽觴。","儲君猶问豎，元老已登牀。","鹤蓋趨平乐，雞人下建章。","龙髯悲满眼，螭首泪沾裳。","叠鼓嚴靈杖，吹笙送夕陽。","斷泉辞劒佩，昏日伴旂常。","遺廟青蓮在，頹垣碧草芳。","無因奏韶濩，流涕对幽篁。"]', '诗', 'shi', '', NULL, '題翠微寺二十二韻 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('824423a3-e7e6-41f5-bf24-d0d755bd5ed7', '過孔北海墓二十韻', '過孔北海墓二十韻', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["撫事如神遇，臨風獨涕零。","墓平春草綠，碑折古苔青。","珪玉埋英氣，山河孕炳靈。","發言驚辨囿，撝翰動文星。","蘊策期干世，持權欲反經。","激揚思壯志，流落歎頹齡。","惡木人皆息，貪泉我獨醒。","輪轅無匠石，刀几有庖丁。","碌碌迷藏器，規規守挈瓶。","憤容凌鼎鑊，公議動朝廷。","故國將辭寵，危邦竟緩刑。","鈍工磨白璧，凡石礪青萍。","揭日昭東夏，摶風滯北溟。","後塵遵軌轍，前席詠儀型。","木秀當憂悴，弦傷不底寧。","矜誇遭斥鷃，光彩困飛螢。","白羽留談柄，清風襲德馨。","鸞凰嬰雪刃，狼虎犯雲屏。","蘭蕙荒遺址，榛蕪蔽舊坰。","轘轅近沂水，何事戀明庭。"]', '["撫事如神遇，臨风独涕零。","墓平春草綠，碑折古苔青。","珪玉埋英氣，山河孕炳靈。","發言驚辨囿，撝翰动文星。","蘊策期干世，持權欲反經。","激揚思壯志，流落歎頹齡。","惡木人皆息，貪泉我独醒。","輪轅無匠石，刀几有庖丁。","碌碌迷藏器，規規守挈瓶。","憤容凌鼎鑊，公議动朝廷。","故国將辞寵，危邦竟緩刑。","鈍工磨白璧，凡石礪青萍。","揭日昭东夏，摶风滯北溟。","後塵遵軌轍，前席詠儀型。","木秀當憂悴，弦傷不底寧。","矜誇遭斥鷃，光彩困飞螢。","白羽留談柄，清风襲德馨。","鸾凰嬰雪刃，狼虎犯云屏。","蘭蕙荒遺址，榛蕪蔽旧坰。","轘轅近沂水，何事戀明庭。"]', '诗', 'shi', '', NULL, '過孔北海墓二十韻 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8573544b-7016-432e-9e2e-6c8f7f153de3', '過華清宮二十二韻', '過华清宮二十二韻', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["憶昔開元日，承平事勝遊。","貴妃專寵幸，天子富春秋。","月白霓裳殿，風乾羯鼓樓。","鬬雞花蔽膝，騎馬玉搔頭。","繡轂千門妓，金鞍萬戶侯。","薄雲欹雀扇，輕雪犯貂裘。","過客聞韶濩，居人識冕旒。","氣和春不覺，煙暖霽難收。","澀浪和瓊甃，晴陽上彩斿。","卷衣輕鬢嬾，窺鏡澹蛾羞。","屏掩芙蓉帳，簾褰玳瑁鉤。","重瞳分渭曲，纖手指神州。","御案迷萱草，天袍妬石榴。","深巖藏浴鳳，鮮隰媚潛虬。","不料邯鄲蝨，俄成即墨牛。","劒鋒揮太皞，旗焰拂蚩尤。","內嬖陪行在，孤臣預坐籌。","瑤簪遺翡翠，霜仗駐驊騮。","豔笑雙飛斷，[香]魂一哭休。","早梅悲蜀道，高樹隔昭丘。","朱閣重霄近，蒼崖萬古愁。","至今湯殿水，嗚咽縣前流。"]', '["憶昔开元日，承平事勝游。","貴妃專寵幸，天子富春秋。","月白霓裳殿，风乾羯鼓楼。","鬬雞花蔽膝，騎马玉搔头。","繡轂千门妓，金鞍万戶侯。","薄云欹雀扇，轻雪犯貂裘。","過客闻韶濩，居人識冕旒。","氣和春不覺，煙暖霽难收。","澀浪和瓊甃，晴陽上彩斿。","卷衣轻鬢嬾，窺镜澹蛾羞。","屏掩芙蓉帳，簾褰玳瑁鉤。","重瞳分渭曲，纖手指神州。","御案迷萱草，天袍妬石榴。","深巖藏浴鳳，鲜隰媚潛虬。","不料邯鄲蝨，俄成即墨牛。","劒鋒揮太皞，旗焰拂蚩尤。","內嬖陪行在，孤臣預坐籌。","瑤簪遺翡翠，霜仗駐驊騮。","豔笑雙飞斷，[香]魂一哭休。","早梅悲蜀道，高樹隔昭丘。","朱閣重霄近，蒼崖万古愁。","至今湯殿水，嗚咽縣前流。"]', '诗', 'shi', '', NULL, '過華清宮二十二韻 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656586f8-3110-47aa-b23b-4f97283dbc2f', '洞戶二十二韻', '洞戶二十二韻', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["洞戶連珠網，方疏隱碧潯。","燭盤煙墜燼，簾壓月通陰。","粉白仙郎署，霜清玉女砧。","醉鄉高窈窈，棊陣靜愔愔。","素手琉璃扇，玄髫玳瑁簪。","昔邪看寄迹，梔子詠同心。","樹列千秋勝，樓懸七夕鍼。","舊詞翻白紵，新賦換黃金。","唳鶴調蠻鼓，驚蟬應寶琴。","舞疑繁易度，歌轉斷難尋。","露委花相妬，風欹柳不禁。","橋彎雙表逈，池漲一篙深。","清蹕傳恢囿，黃旗幸上林。","神鷹參翰苑，天馬破蹄涔。","武庫方題品，文園有好音。","朱莖殊菌蠢，丹桂欲蕭森。","黼帳廻瑤席，華燈對錦衾。","畫圖驚走獸，書帖得來禽。","河曙秦樓映，山晴魏闕臨。","綠囊逢趙后，青鎖見王沈。","任達嫌孤憤，疎慵倦九箴。","若爲南遁客，猶作臥龍吟。"]', '["洞戶連珠網，方疏隐碧潯。","燭盤煙墜燼，簾壓月通陰。","粉白仙郎署，霜清玉女砧。","醉乡高窈窈，棊陣静愔愔。","素手琉璃扇，玄髫玳瑁簪。","昔邪看寄迹，梔子詠同心。","樹列千秋勝，楼懸七夕鍼。","旧词翻白紵，新賦換黄金。","唳鹤調蠻鼓，驚蟬應寶琴。","舞疑繁易度，歌轉斷难尋。","露委花相妬，风欹柳不禁。","橋彎雙表逈，池漲一篙深。","清蹕傳恢囿，黄旗幸上林。","神鷹參翰苑，天马破蹄涔。","武庫方題品，文园有好音。","朱莖殊菌蠢，丹桂欲蕭森。","黼帳廻瑤席，华灯对錦衾。","畫圖驚走獸，书帖得来禽。","河曙秦楼映，山晴魏闕臨。","綠囊逢趙后，青鎖见王沈。","任達嫌孤憤，疎慵倦九箴。","若爲南遁客，猶作臥龙吟。"]', '诗', 'shi', '', NULL, '洞戶二十二韻 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4398517-f5ee-4157-b972-5e4d307fff37', '送洛南李主簿', '送洛南李主簿', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["想君秦塞外，因見楚山青。","槲葉曉迷路，枳花春滿庭。","祿優仍侍膳，官散得專經。","子敬懷愚谷，歸心在翠屏。"]', '["想君秦塞外，因见楚山青。","槲葉晓迷路，枳花春满庭。","祿優仍侍膳，官散得專經。","子敬懷愚谷，归心在翠屏。"]', '诗', 'shi', '', NULL, '送洛南李主簿 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262a4225-0f04-4d59-9fa0-ec11b999250e', '巫山神女廟', '巫山神女廟', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["黯黯閉宮殿，霏霏蔭薜蘿。","曉峰眉上色，春水臉前波。","古樹芳菲盡，扁舟離恨多。","一叢斑竹夜，環佩響如何。"]', '["黯黯閉宮殿，霏霏蔭薜蘿。","晓峰眉上色，春水臉前波。","古樹芳菲尽，扁舟離恨多。","一叢斑竹夜，环佩响如何。"]', '诗', 'shi', '', NULL, '巫山神女廟 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea05a06f-93f2-4847-b699-025630d0ddb8', '地肺山春日', '地肺山春日', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["冉冉花明岸，涓涓水繞山。","幾時拋俗事，來共白雲閑。"]', '["冉冉花明岸，涓涓水繞山。","幾时拋俗事，来共白云闲。"]', '诗', 'shi', '', NULL, '地肺山春日 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d09fabb-6e88-44a6-b795-0e02632c08d8', '題陳處士幽居', '題陳处士幽居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["松軒塵外客，高枕自蕭疎。","雨後苔侵井，霜來葉滿渠。","閑看鏡湖畫，秋得越僧書。","若待前溪月，誰人伴釣魚。"]', '["松軒塵外客，高枕自蕭疎。","雨後苔侵井，霜来葉满渠。","闲看镜湖畫，秋得越僧书。","若待前溪月，誰人伴釣鱼。"]', '诗', 'shi', '', NULL, '題陳處士幽居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fe7f03d-21ec-4cfe-a408-774b57b26856', '握柘詞', '握柘词', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["楊柳縈橋綠，玫瑰拂地紅。","繡衫金騕褭，花髻玉瓏璁。","宿雨香潛潤，春流水暗通。","畫樓初夢斷，曉日照湘風。"]', '["楊柳縈橋綠，玫瑰拂地紅。","繡衫金騕褭，花髻玉瓏璁。","宿雨香潛潤，春流水暗通。","畫楼初梦斷，晓日照湘风。"]', '诗', 'shi', '', NULL, '握柘詞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('081c823e-2f7f-4693-93cd-8ed7011bdf75', '題盧處士山居', '題盧处士山居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["西溪問樵客，遙識楚人家。","古樹老連石，急泉清露沙。","千峰隨雨暗，一逕入雲斜。","日暮飛鴉集，滿山蕎麥花。"]', '["西溪问樵客，遙識楚人家。","古樹老連石，急泉清露沙。","千峰隨雨暗，一逕入云斜。","日暮飞鴉集，满山蕎麦花。"]', '诗', 'shi', '', NULL, '題盧處士山居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('021826a4-0bde-4271-9846-d3fc0016fc32', '初秋寄友人', '初秋寄友人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["閑夢正悠悠，涼風生竹樓。","夜琴知欲雨，曉簟覺新秋。","獨鳥楚山遠，一蟬關樹愁。","憑將離別恨，江外問同遊。"]', '["闲梦正悠悠，涼风生竹楼。","夜琴知欲雨，晓簟覺新秋。","独鸟楚山远，一蟬关樹愁。","憑將離別恨，江外问同游。"]', '诗', 'shi', '', NULL, '初秋寄友人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51ed193a-266f-4e32-96aa-bf2c5603f610', '題豐安里王相林亭二首 一', '題豐安里王相林亭二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["花竹有薄埃，嘉遊集上才。","白蘋安石渚，紅葉子雲臺。","朱戶雀羅設，黃門馭騎來。","不知淮水濁，丹藕爲誰開。"]', '["花竹有薄埃，嘉游集上才。","白蘋安石渚，紅葉子云台。","朱戶雀羅設，黄门馭騎来。","不知淮水濁，丹藕爲誰开。"]', '诗', 'shi', '', NULL, '題豐安里王相林亭二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d43e80-e7fe-464b-a409-9bb62c9ecbe7', '題豐安里王相林亭二首 二', '題豐安里王相林亭二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["偶到烏衣巷，含情更惘然。","西州曲堤柳，東府舊池蓮。","星坼悲元老，雲歸送墨仙。","誰知濟川檝，今作野人船。"]', '["偶到烏衣巷，含情更惘然。","西州曲堤柳，东府旧池蓮。","星坼悲元老，云归送墨仙。","誰知濟川檝，今作野人船。"]', '诗', 'shi', '', NULL, '題豐安里王相林亭二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('625e5d3b-c785-4637-8707-7c0834a288eb', '早秋山居', '早秋山居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["山近覺寒早，草堂霜氣晴。","樹凋窗有日，池滿水無聲。","果落見猿過，葉乾聞鹿行。","素琴機慮靜，空伴夜泉清。"]', '["山近覺寒早，草堂霜氣晴。","樹凋窗有日，池满水無声。","果落见猿過，葉乾闻鹿行。","素琴機慮静，空伴夜泉清。"]', '诗', 'shi', '', NULL, '早秋山居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cdf0ffd-f93e-494b-999b-24d56a68a7d4', '和友人盤石寺逢舊友', '和友人盤石寺逢旧友', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["楚寺上方宿，滿堂皆舊遊。","月溪逢遠客，煙浪有歸舟。","江館白蘋夜，水關紅葉秋。","西風吹暮雨，汀草更堪愁。"]', '["楚寺上方宿，满堂皆旧游。","月溪逢远客，煙浪有归舟。","江館白蘋夜，水关紅葉秋。","西风吹暮雨，汀草更堪愁。"]', '诗', 'shi', '', NULL, '和友人盤石寺逢舊友 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43b388ea-85c6-45ec-95e7-ed29abf9200f', '送人南遊', '送人南游', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["送君遊楚國，江浦樹蒼然。","沙淨有波迹，岸平多草煙。","角悲臨海郡，月到渡淮船。","唯以一桮酒，相思高楚天。"]', '["送君游楚国，江浦樹蒼然。","沙淨有波迹，岸平多草煙。","角悲臨海郡，月到渡淮船。","唯以一桮酒，相思高楚天。"]', '诗', 'shi', '', NULL, '送人南遊 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d3ce376-9b2c-4c0e-ba5a-6ef10d170e09', '贈鄭處士', '贈鄭处士', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["飄然隨釣艇，雲水是天涯。","紅葉下荒井，碧梧侵古槎。","醉收陶令菊，貧賣邵平瓜。","更有相期處，南籬一樹花。"]', '["飄然隨釣艇，云水是天涯。","紅葉下荒井，碧梧侵古槎。","醉收陶令菊，貧賣邵平瓜。","更有相期处，南籬一樹花。"]', '诗', 'shi', '', NULL, '贈鄭處士 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ecbcbc5-181e-4972-92ab-399fa3c662f3', '江岸即事', '江岸即事', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["水容侵古岸，峰影度青蘋。","廟竹唯聞鳥，江帆不見人。","雀聲花外暝，客思柳邊春。","別恨轉難盡，行行汀草新。"]', '["水容侵古岸，峰影度青蘋。","廟竹唯闻鸟，江帆不见人。","雀声花外暝，客思柳邊春。","別恨轉难尽，行行汀草新。"]', '诗', 'shi', '', NULL, '江岸即事 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('190b3c15-f403-45f7-8e96-2423f0ffc989', '贈隱者', '贈隐者', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["茅堂對薇蕨，爐曖一裘輕。","醉後楚山夢，覺來春鳥聲。","採茶溪樹綠，煮藥石泉清。","不問人間事，忘機過此生。"]', '["茅堂对薇蕨，爐曖一裘轻。","醉後楚山梦，覺来春鸟声。","採茶溪樹綠，煮藥石泉清。","不问人间事，忘機過此生。"]', '诗', 'shi', '', NULL, '贈隱者 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85faedaf-3758-4c8a-8eb0-276c984c1c5f', '渚宮晚春寄秦地友人', '渚宮晚春寄秦地友人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["風華已眇然，獨立思江天。","鳧鴈野塘水，牛羊春草煙。","秦原曉重疊，灞浪夜潺湲。","今日思歸客，愁容在鏡懸。"]', '["风华已眇然，独立思江天。","鳧鴈野塘水，牛羊春草煙。","秦原晓重叠，灞浪夜潺湲。","今日思归客，愁容在镜懸。"]', '诗', 'shi', '', NULL, '渚宮晚春寄秦地友人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e269048-5ec9-4dc4-b49c-f71559570c7b', '碧澗驛曉思', '碧澗驛晓思', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["香燈伴殘夢，楚國在天涯。","月落子規歇，滿庭山杏花。"]', '["香灯伴殘梦，楚国在天涯。","月落子規歇，满庭山杏花。"]', '诗', 'shi', '', NULL, '碧澗驛曉思 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bacfc609-2d58-4beb-a773-2bd9c5ea4248', '送幷州郭書記', '送幷州郭书記', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["賓筵得佳客，侯印有光輝。","候騎不傳箭，迴文空上機。","塞城收馬去，烽火射鵰歸。","惟有嚴家瀨，回環逕草微。"]', '["賓筵得佳客，侯印有光輝。","候騎不傳箭，迴文空上機。","塞城收马去，烽火射鵰归。","惟有嚴家瀨，回环逕草微。"]', '诗', 'shi', '', NULL, '送幷州郭書記 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8a0199c-bb4a-4bfb-af37-961551c9c87e', '贈越僧岳雲二首 一', '贈越僧岳云二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["世機消已盡，巾屨亦飄然。","一室故山月，滿瓶秋澗泉。","禪庵過微雪，鄉寺隔寒煙。","應共白蓮客，相期松桂前。"]', '["世機消已尽，巾屨亦飄然。","一室故山月，满瓶秋澗泉。","禪庵過微雪，乡寺隔寒煙。","應共白蓮客，相期松桂前。"]', '诗', 'shi', '', NULL, '贈越僧岳雲二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4eb4f18-2098-4ab8-b5ed-0db472754d60', '贈越僧岳雲二首 二', '贈越僧岳云二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蘭亭舊都講，今日意如何。","有樹關深院，無塵到淺莎。","僧居隨處好，人事出門多。","不及新春雁，年年鏡水波。"]', '["蘭亭旧都講，今日意如何。","有樹关深院，無塵到淺莎。","僧居隨处好，人事出门多。","不及新春雁，年年镜水波。"]', '诗', 'shi', '', NULL, '贈越僧岳雲二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('905ad3a1-c6ad-493f-90ba-80b38fd60e57', '詠山雞', '詠山雞', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["萬壑動晴景，山禽凌翠微。","繡翎翻草去，紅觜啄花歸。","巢暖碧雲色，影孤清鏡輝。"]', '["万壑动晴景，山禽凌翠微。","繡翎翻草去，紅觜啄花归。","巢暖碧云色，影孤清镜輝。"]', '诗', 'shi', '', NULL, '詠山雞 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19bc5010-51a7-44da-b090-a8bcaabd0aff', '清旦題採藥翁草堂', '清旦題採藥翁草堂', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["幽人尋藥逕，來自曉雲邊。","衣濕朮花雨，語成松嶺煙。","解藤開澗戶，踏石過溪泉。","林外晨光動，山昏鳥滿天。"]', '["幽人尋藥逕，来自晓云邊。","衣濕朮花雨，語成松嶺煙。","解藤开澗戶，踏石過溪泉。","林外晨光动，山昏鸟满天。"]', '诗', 'shi', '', NULL, '清旦題採藥翁草堂 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('768ab03f-279d-43c3-932e-131a347eb031', '商山早行', '商山早行', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["晨起動征鐸，客行悲故鄉。","雞聲茅店月，人迹板橋霜。","槲葉落山路，枳花明驛牆。","因思杜陵夢，鳧雁滿迴塘。"]', '["晨起动征鐸，客行悲故乡。","雞声茅店月，人迹板橋霜。","槲葉落山路，枳花明驛牆。","因思杜陵梦，鳧雁满迴塘。"]', '诗', 'shi', '', NULL, '商山早行 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c97ea54e-f300-4992-93f2-cddbc4bb35d9', '題竹谷神祠', '題竹谷神祠', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蒼蒼松竹晚，一逕入荒祠。","古樹風吹馬，虛廊日照旗。","煙煤朝奠處，風雨夜歸時。","寂寞東湖客，空看蔣帝碑。"]', '["蒼蒼松竹晚，一逕入荒祠。","古樹风吹马，虛廊日照旗。","煙煤朝奠处，风雨夜归时。","寂寞东湖客，空看蔣帝碑。"]', '诗', 'shi', '', NULL, '題竹谷神祠 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e011f26-2bac-4dfb-86b4-b3f03f851a48', '途中有懷', '途中有懷', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["驅車何日閑，擾擾路岐間。","歲暮自多感，客程殊未還。","亭臯汝陽道，風雪穆陵關。","臘後寒梅發，誰人在故山。"]', '["驱车何日闲，擾擾路岐间。","歲暮自多感，客程殊未還。","亭臯汝陽道，风雪穆陵关。","臘後寒梅發，誰人在故山。"]', '诗', 'shi', '', NULL, '途中有懷 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e5f908-806a-4bd9-9c0c-37c1aa54c794', '經李處士杜城別業', '經李处士杜城別業', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["憶昔幾遊集，今來倍歎傷。","百花情易老，一笑事難忘。","白社已蕭索，青樓空豔陽。","不閑雲雨夢，猶欲過高唐。"]', '["憶昔幾游集，今来倍歎傷。","百花情易老，一笑事难忘。","白社已蕭索，青楼空豔陽。","不闲云雨梦，猶欲過高唐。"]', '诗', 'shi', '', NULL, '經李處士杜城別業 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59c9d0f6-8d4b-44f5-8754-65973afee477', '登李羽士東樓', '登李羽士东楼', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["經客有餘音，他年終故林。","高樓本危睇，涼月更傷心。","此意竟難折，伊人成古今。","流塵其可欲，非復嬾鳴琴。"]', '["經客有餘音，他年終故林。","高楼本危睇，涼月更傷心。","此意竟难折，伊人成古今。","流塵其可欲，非复嬾鳴琴。"]', '诗', 'shi', '', NULL, '登李羽士東樓 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f839af23-10a5-447c-bf07-6641576d58b6', '題僧泰恭院二首 一', '題僧泰恭院二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["昔歲東林下，深公識姓名。","爾來辭半偈，空復歎勞生。","憂患慕禪味，寂寥遺世情。","所歸心自得，何事倦塵纓。"]', '["昔歲东林下，深公識姓名。","爾来辞半偈，空复歎勞生。","憂患慕禪味，寂寥遺世情。","所归心自得，何事倦塵纓。"]', '诗', 'shi', '', NULL, '題僧泰恭院二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75adbd27-4cda-49e3-8c53-9db3c171b1fc', '題僧泰恭院二首 二', '題僧泰恭院二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["微生竟勞止，晤言猶是非。","出門還有淚，看竹暫忘機。","爽氣三秋近，浮生一笑稀。","故山松菊在，終欲掩荆扉。"]', '["微生竟勞止，晤言猶是非。","出门還有泪，看竹暫忘機。","爽氣三秋近，浮生一笑稀。","故山松菊在，終欲掩荆扉。"]', '诗', 'shi', '', NULL, '題僧泰恭院二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('664db117-12b7-4bd1-af88-4a8e5fef272a', '西遊書懷', '西游书懷', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["渭川通野戍，有路上桑乾。","獨鳥青天暮，驚麏赤燒殘。","高秋辭故國，昨日夢長安。","客意自如此，非關行路難。"]', '["渭川通野戍，有路上桑乾。","独鸟青天暮，驚麏赤燒殘。","高秋辞故国，昨日梦长安。","客意自如此，非关行路难。"]', '诗', 'shi', '', NULL, '西遊書懷 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('315bc0e1-f76c-49d5-9940-b212e5f9c2ae', '送人東遊', '送人东游', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["荒戍落黃葉，浩然離故關。","高風漢陽渡，初日郢門山。","江上幾人在，天涯孤櫂還。","何當重相見，尊酒慰離顏。"]', '["荒戍落黄葉，浩然離故关。","高风漢陽渡，初日郢门山。","江上幾人在，天涯孤櫂還。","何當重相见，尊酒慰離顏。"]', '诗', 'shi', '', NULL, '送人東遊 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35092cbf-ff9a-4065-ae7c-bcc5945fb978', '寄山中友人', '寄山中友人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["惟昔有歸趣，今茲固願言。","嘯歌成往事，風雨坐涼軒。","時物信佳節，歲華非故園。","固知春草色，何意爲王孫。"]', '["惟昔有归趣，今茲固願言。","嘯歌成往事，风雨坐涼軒。","时物信佳節，歲华非故园。","固知春草色，何意爲王孫。"]', '诗', 'shi', '', NULL, '寄山中友人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('808bff5f-d76e-4621-ad83-1e5ad76038a9', '偶題', '偶題', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["孔雀眠高閣，櫻桃拂短簷。","畫明金冉冉，箏語玉纖纖。","細雨無妨燭，輕寒不隔簾。","欲將紅錦段，因夢寄江淹。"]', '["孔雀眠高閣，櫻桃拂短簷。","畫明金冉冉，箏語玉纖纖。","細雨無妨燭，轻寒不隔簾。","欲將紅錦段，因梦寄江淹。"]', '诗', 'shi', '', NULL, '偶題 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('221e44cd-103f-4531-86a3-911bd57d7f86', '贈考功盧郎中', '贈考功盧郎中', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["白首方辭滿，荆扉對渚田。","雪中無陋巷，醉後似當年。","一笈負山藥，兩瓶攜澗泉。"]', '["白首方辞满，荆扉对渚田。","雪中無陋巷，醉後似當年。","一笈負山藥，兩瓶携澗泉。"]', '诗', 'shi', '', NULL, '贈考功盧郎中 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9efab7e0-e323-4420-b552-20ebc129be2d', '題蕭山廟', '題蕭山廟', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["故道木陰濃，荒祠山影東。","杉松一庭雨，幡蓋滿堂風。","客奠曉莎濕，馬嘶秋廟空。","夜深池上歇，龍入古潭中。"]', '["故道木陰濃，荒祠山影东。","杉松一庭雨，幡蓋满堂风。","客奠晓莎濕，马嘶秋廟空。","夜深池上歇，龙入古潭中。"]', '诗', 'shi', '', NULL, '題蕭山廟 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8248ebc9-adf3-46cb-9fcd-d38340d1d9d6', '春日寄岳州從事李員外二首 一', '春日寄岳州從事李員外二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["苒弱樓前柳，輕空花外窗。","蝶高飛有伴，鶯早語無雙。","剪勝裁春字，開屏見曉江。","從來共情戰，今日欲歸降。"]', '["苒弱楼前柳，轻空花外窗。","蝶高飞有伴，鶯早語無雙。","剪勝裁春字，开屏见晓江。","從来共情戰，今日欲归降。"]', '诗', 'shi', '', NULL, '春日寄岳州從事李員外二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308a66a9-8104-45b9-ae17-e1ce8e425fb7', '春日寄岳州從事李員外二首 二', '春日寄岳州從事李員外二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["從小識賓卿，恩深若弟兄。","相逢在何日，此別不勝情。","紅粉座中客，綵斿江上城。","尚平婚嫁累，無路逐雙旌。"]', '["從小識賓卿，恩深若弟兄。","相逢在何日，此別不勝情。","紅粉座中客，綵斿江上城。","尚平婚嫁累，無路逐雙旌。"]', '诗', 'shi', '', NULL, '春日寄岳州從事李員外二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd6fb867-ac97-4113-b61a-5c97f22cc0e7', '和段少常柯古', '和段少常柯古', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["稱觴慙座客，懷刺即門人。","素向寧知貴，清淡不厭貧。","野梅江上晚，堤柳雨中春。","未報淮南詔，何勞問白蘋。"]', '["稱觴慙座客，懷刺即门人。","素向寧知貴，清淡不厭貧。","野梅江上晚，堤柳雨中春。","未報淮南詔，何勞问白蘋。"]', '诗', 'shi', '', NULL, '和段少常柯古 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8278d0c0-0e30-4f1c-bc4e-614e18727ce4', '海榴', '海榴', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["海榴開似火，先解報春風。","葉亂裁牋綠，花宜插鬢紅。","蠟珠攢作蔕，緗綵剪成叢。","鄭驛多歸思，相期一笑同。"]', '["海榴开似火，先解報春风。","葉亂裁牋綠，花宜插鬢紅。","蠟珠攢作蔕，緗綵剪成叢。","鄭驛多归思，相期一笑同。"]', '诗', 'shi', '', NULL, '海榴 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5f2f5d6-beac-4610-aa30-53eed85ab155', '李先生別墅望僧舍寶剎因作雙韻聲', '李先生別墅望僧舍寶剎因作雙韻声', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["棲息消心象，簷楹溢豔陽。","簾櫳蘭露落，鄰里柳林涼。","高閣過空谷，孤竿隔古岡。","潭廬同淡蕩，髣髴復芬芳。"]', '["棲息消心象，簷楹溢豔陽。","簾櫳蘭露落，鄰里柳林涼。","高閣過空谷，孤竿隔古岡。","潭廬同淡蕩，髣髴复芬芳。"]', '诗', 'shi', '', NULL, '李先生別墅望僧舍寶剎因作雙韻聲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74fad94e-1b54-4559-abb1-e26eb0b20bbb', '敷水小桃盛開因作', '敷水小桃盛开因作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["敷水小橋東，娟娟照露叢。","所嗟非勝地，堪恨是春風。","二月豔陽節，一枝惆悵紅。","定知留不住，吹落路塵中。"]', '["敷水小橋东，娟娟照露叢。","所嗟非勝地，堪恨是春风。","二月豔陽節，一枝惆悵紅。","定知留不住，吹落路塵中。"]', '诗', 'shi', '', NULL, '敷水小桃盛開因作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4e8909-ce94-4b1b-8a9b-d27389580458', '寄山中人', '寄山中人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["月中一雙鶴，石上千尺松。","素琴入爽籟，山酒和春容。","幽瀑有時斷，片雲無所從。","何事蘇門生，攜手東南峰。"]', '["月中一雙鹤，石上千尺松。","素琴入爽籟，山酒和春容。","幽瀑有时斷，片云無所從。","何事蘇门生，携手东南峰。"]', '诗', 'shi', '', NULL, '寄山中人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca789aac-36a3-487c-a9e6-3b39bbb84168', '送淮陰孫令之官', '送淮陰孫令之官', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["隋堤楊柳煙，孤櫂正悠然。","蕭寺通淮戍，蕪城枕楚壖。","魚鹽橋上市，燈火雨中船。","故老青葭岸，先知虙子賢。"]', '["隋堤楊柳煙，孤櫂正悠然。","蕭寺通淮戍，蕪城枕楚壖。","鱼鹽橋上市，灯火雨中船。","故老青葭岸，先知虙子賢。"]', '诗', 'shi', '', NULL, '送淮陰孫令之官 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5606b6e0-c119-4e33-8c19-df38d69cd995', '宿輝公精舍', '宿輝公精舍', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["禪房無外物，清話此宵同。","林彩水煙裏，澗聲[山]月中。","橡霜諸壑霽，杉火一爐空。","擁褐寒更徹，心知覺路通。"]', '["禪房無外物，清話此宵同。","林彩水煙裏，澗声[山]月中。","橡霜諸壑霽，杉火一爐空。","擁褐寒更徹，心知覺路通。"]', '诗', 'shi', '', NULL, '宿輝公精舍 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57042eb4-218a-40f8-acd6-0e037080af00', '旅泊新津却寄一二知己', '旅泊新津却寄一二知己', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["維舟息行役，霽景近江村。","併起別離恨，似聞歌吹喧。","高林月初上，遠水霧猶昏。","王粲平生感，登臨幾斷魂。"]', '["維舟息行役，霽景近江村。","併起別離恨，似闻歌吹喧。","高林月初上，远水霧猶昏。","王粲平生感，登臨幾斷魂。"]', '诗', 'shi', '', NULL, '旅泊新津却寄一二知己 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee7cab5-a2e1-48d9-9c60-742c8b14baab', '贈僧雲栖', '贈僧云栖', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["麈尾與筇杖，幾年離石壇。","梵餘林雪厚，棊罷岳鐘殘。","開卷喜先悟，漱缾知早寒。","衡陽寺前雁，今日到長安。"]', '["麈尾與筇杖，幾年離石壇。","梵餘林雪厚，棊罷岳鐘殘。","开卷喜先悟，漱缾知早寒。","衡陽寺前雁，今日到长安。"]', '诗', 'shi', '', NULL, '贈僧雲栖 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d571587c-8ec8-4404-b621-6546fe69d982', '雪夜與友生同宿曉寄近鄰', '雪夜與友生同宿晓寄近鄰', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["閉門羣動息，積雪透疎林。","有客寒方覺，無聲曉已深。","正繁聞近雁，併落起栖禽。","寂寞寒塘路，憐君獨阻尋。"]', '["閉门羣动息，積雪透疎林。","有客寒方覺，無声晓已深。","正繁闻近雁，併落起栖禽。","寂寞寒塘路，怜君独阻尋。"]', '诗', 'shi', '', NULL, '雪夜與友生同宿曉寄近鄰 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec99b96-e980-4ad6-8932-b05ac8e3159c', '題造微禪師院', '題造微禪師院', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["夜香聞偈後，岑寂掩雙扉。","照竹燈和雪，看松月到衣。","草堂疎磬斷，江寺故人稀。","唯憶湘南雨，春風獨鳥歸。"]', '["夜香闻偈後，岑寂掩雙扉。","照竹灯和雪，看松月到衣。","草堂疎磬斷，江寺故人稀。","唯憶湘南雨，春风独鸟归。"]', '诗', 'shi', '', NULL, '題造微禪師院 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e768c583-263d-4ef2-a289-6eb589747c1a', '正見寺曉別生公', '正见寺晓別生公', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["清曉盥秋水，高窗留夕陰。","初陽到古寺，宿鳥起寒林。","香火有良願，宦名非素心。","靈山緣未絕，他日重來尋。"]', '["清晓盥秋水，高窗留夕陰。","初陽到古寺，宿鸟起寒林。","香火有良願，宦名非素心。","靈山緣未絕，他日重来尋。"]', '诗', 'shi', '', NULL, '正見寺曉別生公 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90e8b67-7c47-4cf0-a59e-2f94f9e4d3c8', '旅次盱眙縣', '旅次盱眙縣', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["離離麥擢芒，楚客意偏傷。","波上旅愁起，天邊歸路長。","孤橈投楚驛，殘月在淮檣。","外杜三千里，誰人數雁行。"]', '["離離麦擢芒，楚客意偏傷。","波上旅愁起，天邊归路长。","孤橈投楚驛，殘月在淮檣。","外杜三千里，誰人數雁行。"]', '诗', 'shi', '', NULL, '旅次盱眙縣 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ba2892-b146-41d6-a5ff-bac17b1a0538', '鄠郊別墅寄所知', '鄠郊別墅寄所知', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["持頤望平綠，萬景集所思。","南塘遇新雨，百草生容姿。","幽鳥不相識，美人如何期。","徒然委搖蕩，惆悵春風時。"]', '["持頤望平綠，万景集所思。","南塘遇新雨，百草生容姿。","幽鸟不相識，美人如何期。","徒然委搖蕩，惆悵春风时。"]', '诗', 'shi', '', NULL, '鄠郊別墅寄所知 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a51fef9d-0ec6-4498-841d-f21d23a2ff96', '京兆公池上作', '京兆公池上作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["稻香山色疊，平野接荒陂。","蓮折舟行遠，萍多釣下遲。","壞堤泉落處，涼簟雨來時。","京口兵堪用，何因入夢思。"]', '["稻香山色叠，平野接荒陂。","蓮折舟行远，萍多釣下遲。","壞堤泉落处，涼簟雨来时。","京口兵堪用，何因入梦思。"]', '诗', 'shi', '', NULL, '京兆公池上作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90a2223-1336-497d-8bd8-c1339983d7d8', '盧氏池上遇雨贈同遊者', '盧氏池上遇雨贈同游者', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["簟翻涼氣集，溪上潤殘棊。","萍皺風來後，荷喧雨到時。","寂寥閑望久，飄灑獨歸遲。","無限松江恨，煩君解釣絲。"]', '["簟翻涼氣集，溪上潤殘棊。","萍皺风来後，荷喧雨到时。","寂寥闲望久，飄灑独归遲。","無限松江恨，煩君解釣絲。"]', '诗', 'shi', '', NULL, '盧氏池上遇雨贈同遊者 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('192c9299-8208-4bdb-ba69-2dfbe5d0b8cb', '題薛昌之所居', '題薛昌之所居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["所得乃清曠，寂寥常掩關。","獨來春尚在，相得暮方還。","花白風露晚，柳青街陌閑。","翠微應有雪，窗外見南山。"]', '["所得乃清曠，寂寥常掩关。","独来春尚在，相得暮方還。","花白风露晚，柳青街陌闲。","翠微應有雪，窗外见南山。"]', '诗', 'shi', '', NULL, '題薛昌之所居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03fadb0f-d34a-4944-a2a7-c28530749011', '東歸有懷', '东归有懷', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["晴川通野陂，此地昔傷離。","一去迹常在，獨來心自知。","鷺眠茭葉折，魚靜蓼花垂。","無限高秋淚，扁舟極路岐。"]', '["晴川通野陂，此地昔傷離。","一去迹常在，独来心自知。","鷺眠茭葉折，鱼静蓼花垂。","無限高秋泪，扁舟極路岐。"]', '诗', 'shi', '', NULL, '東歸有懷 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f92767ce-8b70-4cf9-8f34-2cec0813c0a4', '休澣日西掖謁所知', '休澣日西掖謁所知', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["赤墀高閣自從容，玉女窗扉報曙鐘。","日麗九門青鎖闥，雨晴雙闕翠微峰。","毫端蕙露滋仙草，琴上薰風入禁松。","荀令鳳池春婉娩，好將餘潤變魚龍。"]', '["赤墀高閣自從容，玉女窗扉報曙鐘。","日丽九门青鎖闥，雨晴雙闕翠微峰。","毫端蕙露滋仙草，琴上薰风入禁松。","荀令鳳池春婉娩，好將餘潤变鱼龙。"]', '诗', 'shi', '', NULL, '休澣日西掖謁所知 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f8c0e6-e243-4712-8141-857631a8265c', '博山', '博山', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["博山香重欲成雲，錦段機絲妬鄂君。","粉蝶團飛花轉影，彩鴛雙泳水生紋。","青樓二月春將半，碧瓦千家日未曛。","見說楊朱無限淚，豈能空爲路岐分。"]', '["博山香重欲成云，錦段機絲妬鄂君。","粉蝶團飞花轉影，彩鴛雙泳水生紋。","青楼二月春將半，碧瓦千家日未曛。","见说楊朱無限泪，豈能空爲路岐分。"]', '诗', 'shi', '', NULL, '博山 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ca57e47-ba4d-4302-8b70-0fcbec5b2b58', '送盧處士遊吳越', '送盧处士游吳越', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["羨君東去見殘梅，唯有王孫獨未廻。","吳苑夕陽明古堞，越宮春草上高臺。","波生野水雁初下，風滿驛樓潮欲來。","試逐漁舟看雪浪，幾多江燕荇花開。"]', '["羨君东去见殘梅，唯有王孫独未廻。","吳苑夕陽明古堞，越宮春草上高台。","波生野水雁初下，风满驛楼潮欲来。","試逐漁舟看雪浪，幾多江燕荇花开。"]', '诗', 'shi', '', NULL, '送盧處士遊吳越 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f55bdd0-5ecb-461e-ae85-cd10ae7b8c66', '過新豐', '過新豐', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["一劒乘時帝業成，沛中鄉里到咸京。","寰區已作皇居貴，風月猶含白社情。","泗水舊亭春草徧，千門遺瓦古苔生。","至今留得離家恨，雞犬相聞落照明。"]', '["一劒乘时帝業成，沛中乡里到咸京。","寰區已作皇居貴，风月猶含白社情。","泗水旧亭春草徧，千门遺瓦古苔生。","至今留得離家恨，雞犬相闻落照明。"]', '诗', 'shi', '', NULL, '過新豐 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e92c3b9-3fd6-44c7-815d-58f8b4210817', '過潼關', '過潼关', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["地形盤屈帶河流，景氣澄明是勝遊。","十里曉雞關樹暗，一行寒雁隴雲愁。","片時無事溪泉好，盡日凝眸岳色秋。","麈尾角巾應曠望，更嗟芳靄隔秦樓。"]', '["地形盤屈带河流，景氣澄明是勝游。","十里晓雞关樹暗，一行寒雁隴云愁。","片时無事溪泉好，尽日凝眸岳色秋。","麈尾角巾應曠望，更嗟芳靄隔秦楼。"]', '诗', 'shi', '', NULL, '過潼關 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9595514e-8ad5-470e-8c3c-a56bd6232e40', '題西平王舊賜屏風', '題西平王旧賜屏风', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["曾向金扉玉砌來，百花鮮濕隔塵埃。","披香殿下櫻桃熟，結綺樓前芍藥開。","朱鷺已隨新鹵簿，黃鸝猶濕舊池臺。","世間剛有東流水，一送恩波更不廻。"]', '["曾向金扉玉砌来，百花鲜濕隔塵埃。","披香殿下櫻桃熟，結綺楼前芍藥开。","朱鷺已隨新鹵簿，黄鸝猶濕旧池台。","世间剛有东流水，一送恩波更不廻。"]', '诗', 'shi', '', NULL, '題西平王舊賜屏風 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc22cdfd-916c-43ff-855e-21e682e07073', '河中陪帥遊亭', '河中陪帥游亭', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["倚闌愁立獨徘徊，欲賦慙非宋玉才。","滿座山光搖劒戟，繞城波色動樓臺。","鳥飛天外斜陽盡，人過橋心倒影來。","添得五湖多少恨，柳花飄蕩似寒梅。"]', '["倚闌愁立独徘徊，欲賦慙非宋玉才。","满座山光搖劒戟，繞城波色动楼台。","鸟飞天外斜陽尽，人過橋心倒影来。","添得五湖多少恨，柳花飄蕩似寒梅。"]', '诗', 'shi', '', NULL, '河中陪帥遊亭 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f43085b1-0c91-4976-a191-aa8bacf50eea', '和趙嘏題岳寺', '和趙嘏題岳寺', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["疎鐘細響亂鳴泉，客省高臨似水天。","嵐翠暗來空覺潤，澗茶餘爽不成眠。","越僧寒立孤燈外，岳月秋當萬木前。","張邴宦情何太薄，遠公窗外有池蓮。"]', '["疎鐘細响亂鳴泉，客省高臨似水天。","嵐翠暗来空覺潤，澗茶餘爽不成眠。","越僧寒立孤灯外，岳月秋當万木前。","張邴宦情何太薄，远公窗外有池蓮。"]', '诗', 'shi', '', NULL, '和趙嘏題岳寺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae8a893-7ae6-4824-b4c5-eada730b075f', '蘇武廟', '蘇武廟', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蘇武魂銷漢使前，古祠高樹兩茫然。","雲邊雁斷胡天月，隴上羊歸塞草煙。","廻日樓臺非甲帳，去時冠劒是丁年。","茂陵不見封侯印，空向秋波哭逝川。"]', '["蘇武魂銷漢使前，古祠高樹兩茫然。","云邊雁斷胡天月，隴上羊归塞草煙。","廻日楼台非甲帳，去时冠劒是丁年。","茂陵不见封侯印，空向秋波哭逝川。"]', '诗', 'shi', '', NULL, '蘇武廟 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf12ced-258a-4890-99d4-544ec28385d4', '送客偶作', '送客偶作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["石路荒涼接野蒿，西風吹馬利如刀。","小橋連驛楊柳晚，廢寺入門禾黍高。","雞犬夕陽喧縣市，鳧鷖秋水曝城壕。","故山有夢不歸去，官樹陌塵何太勞。"]', '["石路荒涼接野蒿，西风吹马利如刀。","小橋連驛楊柳晚，廢寺入门禾黍高。","雞犬夕陽喧縣市，鳧鷖秋水曝城壕。","故山有梦不归去，官樹陌塵何太勞。"]', '诗', 'shi', '', NULL, '送客偶作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dccf5d6-dd4c-40ac-aefe-c9b3594cfc53', '寒食前有懷', '寒食前有懷', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["萬物鮮華雨乍晴，春寒寂歷近清明。","殘芳荏苒雙飛蝶，曉睡朦朧百囀鶯。","舊侶不歸成獨酌，故園雖在有誰耕。","悠然更起嚴灘恨，一宿東風蕙草生。"]', '["万物鲜华雨乍晴，春寒寂歷近清明。","殘芳荏苒雙飞蝶，晓睡朦朧百囀鶯。","旧侶不归成独酌，故园雖在有誰耕。","悠然更起嚴灘恨，一宿东风蕙草生。"]', '诗', 'shi', '', NULL, '寒食前有懷 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b780c16d-05aa-40ed-95c0-e1ecaa6e433f', '宿雲際寺', '宿云際寺', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["白蓋微雲一逕深，東峰弟子遠相尋。","蒼苔路熟僧歸寺，紅葉聲乾鹿在林。","高閣清香生靜境，夜堂疎磬發禪心。","自從紫桂巖前別，不見南能直至今。"]', '["白蓋微云一逕深，东峰弟子远相尋。","蒼苔路熟僧归寺，紅葉声乾鹿在林。","高閣清香生静境，夜堂疎磬發禪心。","自從紫桂巖前別，不见南能直至今。"]', '诗', 'shi', '', NULL, '宿雲際寺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fce7dac-6d91-43bd-b574-299740303228', '寄岳州李外郎遠', '寄岳州李外郎远', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["含嚬不語坐持頤，天遠樓高宋玉悲。","湖上殘棊人散後，岳陽微雨鳥來遲。","早梅猶得廻歌扇，春水還應理釣絲。","獨有袁宏正憔悴，一罇惆悵落花時。"]', '["含嚬不語坐持頤，天远楼高宋玉悲。","湖上殘棊人散後，岳陽微雨鸟来遲。","早梅猶得廻歌扇，春水還應理釣絲。","独有袁宏正憔悴，一罇惆悵落花时。"]', '诗', 'shi', '', NULL, '寄岳州李外郎遠 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2eb119c-087b-4d77-b26b-fd044cec1c62', '遊南塘寄知者', '游南塘寄知者', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["白鳥梳翎立岸莎，藻花菱刺泛微波。","煙光似帶侵垂柳，露點如珠落卷荷。","楚水曉涼催客早，杜陵秋思傍蟬多。","鎦公不信歸心切，聽取江樓一曲歌。"]', '["白鸟梳翎立岸莎，藻花菱刺泛微波。","煙光似带侵垂柳，露点如珠落卷荷。","楚水晓涼催客早，杜陵秋思傍蟬多。","鎦公不信归心切，听取江楼一曲歌。"]', '诗', 'shi', '', NULL, '遊南塘寄知者 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1c66a8b-b78c-4945-a3a4-7e6bd4fe643d', '寄盧生', '寄盧生', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["遺業荒涼近故都，門前堤路枕平湖。","綠楊陰裏千家月，紅藕香中萬點珠。","此地別來雙鬢改，幾時歸去片帆孤。","他年猶擬金貂換，寄語黃公舊酒壚。"]', '["遺業荒涼近故都，门前堤路枕平湖。","綠楊陰裏千家月，紅藕香中万点珠。","此地別来雙鬢改，幾时归去片帆孤。","他年猶擬金貂換，寄語黄公旧酒壚。"]', '诗', 'shi', '', NULL, '寄盧生 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('891a34dc-3531-4352-b786-035b2a839eaf', '春日訪李十四處士', '春日訪李十四处士', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["花深橋轉水潺潺，甪里先生自閉關。","看竹已知行處好，望雲空得暫時閑。","誰言有策堪經世，自是無錢可買山。","一局殘棊千點雨，綠萍池上暮方還。"]', '["花深橋轉水潺潺，甪里先生自閉关。","看竹已知行处好，望云空得暫时闲。","誰言有策堪經世，自是無錢可買山。","一局殘棊千点雨，綠萍池上暮方還。"]', '诗', 'shi', '', NULL, '春日訪李十四處士 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('296bfdb7-8069-461a-9a56-8c57c891686e', '宿松門寺', '宿松门寺', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["白石青崖世界分，卷簾孤坐對氛氳。","林間禪室春深雪，潭上龍堂夜半雲。","落月蒼涼登閣在，曉鐘搖蕩隔江聞。","西山舊是經行地，願漱寒缾逐領軍。"]', '["白石青崖世界分，卷簾孤坐对氛氳。","林间禪室春深雪，潭上龙堂夜半云。","落月蒼涼登閣在，晓鐘搖蕩隔江闻。","西山旧是經行地，願漱寒缾逐領軍。"]', '诗', 'shi', '', NULL, '宿松門寺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74c30b20-ec45-4e00-8914-f6aa1e5c9b03', '詠寒宵', '詠寒宵', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["寒宵何耿耿，良讌有餘姿。","寶靺徘徊處，熏鑪悵望時。","曲瓊垂翡翠，斜月到罘罳。","委墜金釭燼，闌珊玉局棊。","話窮猶注睇，歌罷尚持頤。","晻暖遙相屬，氛氳積所思。","秦蛾卷衣晚，胡雁度雲遲。","上郡歸來夢，那知錦字詩。"]', '["寒宵何耿耿，良讌有餘姿。","寶靺徘徊处，熏鑪悵望时。","曲瓊垂翡翠，斜月到罘罳。","委墜金釭燼，闌珊玉局棊。","話窮猶注睇，歌罷尚持頤。","晻暖遙相屬，氛氳積所思。","秦蛾卷衣晚，胡雁度云遲。","上郡归来梦，那知錦字诗。"]', '诗', 'shi', '', NULL, '詠寒宵 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e030dd-e356-4aa7-95dd-cf812cf4794e', '寄渚宮遺民弘里生', '寄渚宮遺民弘里生', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["柳弱湖堤曲，籬疎水巷深。","酒闌初促席，歌罷欲分襟。","波月欺華燭，汀雲潤故琴。","鏡清花並蔕，牀冷簟連心。","荷疊平橋暗，萍稀敗舫沈。","城頭五通鼓，窗外萬家砧。","異縣魚投浪，當年鳥共林。","八行香未滅，千里夢難尋。","未肯暌良願，空期嗣好音。","他時因詠作，猶得比南金。"]', '["柳弱湖堤曲，籬疎水巷深。","酒闌初促席，歌罷欲分襟。","波月欺华燭，汀云潤故琴。","镜清花並蔕，牀冷簟連心。","荷叠平橋暗，萍稀敗舫沈。","城头五通鼓，窗外万家砧。","異縣鱼投浪，當年鸟共林。","八行香未滅，千里梦难尋。","未肯暌良願，空期嗣好音。","他时因詠作，猶得比南金。"]', '诗', 'shi', '', NULL, '寄渚宮遺民弘里生 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994c9cd5-93f6-447b-8d3e-9f513862f853', '春盡與友人入裴氏林探漁竿', '春尽與友人入裴氏林探漁竿', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["一逕互紆直，茅棘亦已繁。","晴陽入荒竹，曖曖如春園。","倚杖息慚倦，徘徊戀微暄。","歷尋嬋娟節，翦破蒼筤根。","地閉修莖孤，林振餘籜翻。","適心在所好，非必尋湘沅。"]', '["一逕互紆直，茅棘亦已繁。","晴陽入荒竹，曖曖如春园。","倚杖息慚倦，徘徊戀微暄。","歷尋嬋娟節，翦破蒼筤根。","地閉修莖孤，林振餘籜翻。","適心在所好，非必尋湘沅。"]', '诗', 'shi', '', NULL, '春盡與友人入裴氏林探漁竿 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9562c01f-bf63-45ce-bdac-d15827cb13a0', '春日', '春日', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["問君何所思，迢遞豔陽時。","門靜人歸晚，牆高蝶過遲。","一雙青瑣燕，千萬綠楊絲。","屏上吳山遠，樓中朔管悲。","寶書無寄處，香轂有來期。","草色將林彩，相添入黛眉。"]', '["问君何所思，迢遞豔陽时。","门静人归晚，牆高蝶過遲。","一雙青瑣燕，千万綠楊絲。","屏上吳山远，楼中朔管悲。","寶书無寄处，香轂有来期。","草色將林彩，相添入黛眉。"]', '诗', 'shi', '', NULL, '春日 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f16efb1-9f3b-450c-b88f-a95d65d7ddfc', '洛陽', '洛陽', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["鞏樹先春雪滿枝，上陽宮柳囀黃鸝。","桓譚未便忘西笑，豈爲長安有鳳池。"]', '["鞏樹先春雪满枝，上陽宮柳囀黄鸝。","桓譚未便忘西笑，豈爲长安有鳳池。"]', '诗', 'shi', '', NULL, '洛陽 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f876230-ed38-4a37-bf92-95df6764ab5b', '題賀知章故居疊韻作', '題賀知章故居叠韻作', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["廢砌翳薜荔，枯湖無菰蒲。","老媼飽藁草，愚儒輸逋租。"]', '["廢砌翳薜荔，枯湖無菰蒲。","老媼飽藁草，愚儒輸逋租。"]', '诗', 'shi', '', NULL, '題賀知章故居疊韻作 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d2442b-288b-4ae8-9ad7-bb0019891906', '雨中與李先生期垂釣先後相失因作疊韻', '雨中與李先生期垂釣先後相失因作叠韻', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["隔石覓屐跡，西溪迷雞啼。","小鳥擾曉沼，犂泥齊低畦。"]', '["隔石覓屐跡，西溪迷雞啼。","小鸟擾晓沼，犂泥齊低畦。"]', '诗', 'shi', '', NULL, '雨中與李先生期垂釣先後相失因作疊韻 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b2d85ae-188b-4fe3-8d4e-aa16281d8936', '春日雨', '春日雨', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["細雨濛濛入絳紗，湖亭寒食孟珠家。","南朝漫自稱流品，宮體何曾爲杏花。"]', '["細雨濛濛入絳紗，湖亭寒食孟珠家。","南朝漫自稱流品，宮體何曾爲杏花。"]', '诗', 'shi', '', NULL, '春日雨 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b37093-bc68-47ad-a4b4-1f26f296edab', '細雨', '細雨', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["憑軒望秋雨，涼入暑衣清。","極目鳥頻沒，片時雲復輕。","沼萍開更歛，山葉動還鳴。","楚客秋江上，蕭蕭故國情。"]', '["憑軒望秋雨，涼入暑衣清。","極目鸟頻沒，片时云复轻。","沼萍开更歛，山葉动還鳴。","楚客秋江上，蕭蕭故国情。"]', '诗', 'shi', '', NULL, '細雨 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c96ad97-81fd-4371-8ce7-4ad5c11bc6a7', '秋雨', '秋雨', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["雲滿鳥行滅，池涼龍氣腥。","斜飄看棊簟，疎灑望山亭。","細響鳴林葉，圓文破沼萍。","秋陰杳無際，平野但冥冥。"]', '["云满鸟行滅，池涼龙氣腥。","斜飄看棊簟，疎灑望山亭。","細响鳴林葉，圓文破沼萍。","秋陰杳無際，平野但冥冥。"]', '诗', 'shi', '', NULL, '秋雨 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04fa06aa-5863-441c-8573-56f2c62d25b0', '春初對暮雨', '春初对暮雨', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["淅瀝生叢篠，空濛泫網軒。","暝姿看遠樹，春意入塵根。","點細飄風急，聲輕入夜繁。","雀喧爭槿樹，人靜出蔬園。","瓦濕光先起，房深影易昏。","不應江上草，相與滯王孫。"]', '["淅瀝生叢篠，空濛泫網軒。","暝姿看远樹，春意入塵根。","点細飄风急，声轻入夜繁。","雀喧爭槿樹，人静出蔬园。","瓦濕光先起，房深影易昏。","不應江上草，相與滯王孫。"]', '诗', 'shi', '', NULL, '春初對暮雨 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f7b3abf-38d3-483f-9088-503f71200880', '雪二首 一', '雪二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["硯水池先凍，窗風酒易消。","鴉聲出山郭，人跡過村橋。","稍急方縈轉，才深未寂寥。","細光穿暗隟，輕白駐寒條。","草靜封還折，松攲墮復搖。","謝莊今病眼，無意坐通宵。"]', '["硯水池先凍，窗风酒易消。","鴉声出山郭，人跡過村橋。","稍急方縈轉，才深未寂寥。","細光穿暗隟，轻白駐寒條。","草静封還折，松攲墮复搖。","謝莊今病眼，無意坐通宵。"]', '诗', 'shi', '', NULL, '雪二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('784bd231-aa8b-457b-9bdf-b75a2a079e7f', '雪二首 二', '雪二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["羸驂出更慵，林寺已疎鐘。","踏緊寒聲澀，飛交細點重。","圃斜人過跡，皆靜鳥行蹤。","寂寞梁鴻病，誰人代夜舂。"]', '["羸驂出更慵，林寺已疎鐘。","踏緊寒声澀，飞交細点重。","圃斜人過跡，皆静鸟行蹤。","寂寞梁鴻病，誰人代夜舂。"]', '诗', 'shi', '', NULL, '雪二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48cfd687-4d05-4e5c-b05f-d2851bb73b58', '送人遊淮海', '送人游淮海', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["背檣燈色暗，宿客夢初成。","半夜竹窗雨，滿池荷葉聲。","簟涼秋閤思，木落故山情。","明發又愁起，桂花溪水清。"]', '["背檣灯色暗，宿客梦初成。","半夜竹窗雨，满池荷葉声。","簟涼秋閤思，木落故山情。","明發又愁起，桂花溪水清。"]', '诗', 'shi', '', NULL, '送人遊淮海 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c741f233-7243-479b-bdd6-8847445c31d7', '原隰荑綠柳', '原隰荑綠柳', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["逈野韶光早，晴川柳滿堤。","拂塵生嫩綠，披雪見柔荑。","碧玉牙猶短，黃金縷未齊。","腰肢弄寒吹，眉意入春閨。","預恐狂夫折，迎牽逸客迷。","新鶯將出谷，應借一枝棲。"]', '["逈野韶光早，晴川柳满堤。","拂塵生嫩綠，披雪见柔荑。","碧玉牙猶短，黄金縷未齊。","腰肢弄寒吹，眉意入春閨。","預恐狂夫折，迎牽逸客迷。","新鶯將出谷，應借一枝棲。"]', '诗', 'shi', '', NULL, '原隰荑綠柳 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17b94f10-22c9-4a1b-b823-9e6fc9d3c3cc', '宿秦生山齋', '宿秦生山斋', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["衡巫路不同，結室在東峰。","歲晚得支遁，夜寒逢戴顒。","龕燈落葉寺，山雪隔林鐘。","行解無由發，曹溪欲施舂。"]', '["衡巫路不同，結室在东峰。","歲晚得支遁，夜寒逢戴顒。","龕灯落葉寺，山雪隔林鐘。","行解無由發，曹溪欲施舂。"]', '诗', 'shi', '', NULL, '宿秦生山齋 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb28f914-c334-4c34-ba08-3ff34bfb64b8', '贈楚雲上人', '贈楚云上人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["松根滿苔石，盡日閉禪關。","有伴年年月，無家處處山。","煙波五湖遠，瓶屨一身閑。","岳寺蕙蘭晚，幾時幽鳥還。"]', '["松根满苔石，尽日閉禪关。","有伴年年月，無家处处山。","煙波五湖远，瓶屨一身闲。","岳寺蕙蘭晚，幾时幽鸟還。"]', '诗', 'shi', '', NULL, '贈楚雲上人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f991f56e-7cd8-47bb-bbd8-142f5bd28626', '宿白蓋峰寺寄僧', '宿白蓋峰寺寄僧', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["山房霜氣晴，一宿遂平生。","閤上見林影，月中聞澗聲。","佛燈銷永夜，僧磬徹寒更。","不學何居士，焚香爲宦情。"]', '["山房霜氣晴，一宿遂平生。","閤上见林影，月中闻澗声。","佛灯銷永夜，僧磬徹寒更。","不学何居士，焚香爲宦情。"]', '诗', 'shi', '', NULL, '宿白蓋峰寺寄僧 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40556d3f-d004-4b00-a4b1-3005145ca360', '送僧東遊', '送僧东游', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["師歸舊山去，此別已悽然。","燈影秋江寺，篷聲夜雨船。","鷗飛吳市外，麟臥晉陵前。","若到東林社，誰人更問禪。"]', '["師归旧山去，此別已悽然。","灯影秋江寺，篷声夜雨船。","鷗飞吳市外，麟臥晉陵前。","若到东林社，誰人更问禪。"]', '诗', 'shi', '', NULL, '送僧東遊 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83d558bf-f1e8-4d53-9582-b66e1399fdfc', '盤石寺留別成公', '盤石寺留別成公', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["槲葉蕭蕭帶葦風，寺前歸客別支公。","三秋岸雪花初白，一夜林霜葉盡紅。","山疊楚天雲壓塞，浪遙吳苑水連空。","悠然旅榜頻迴首，無復松窗半偈同。"]', '["槲葉蕭蕭带葦风，寺前归客別支公。","三秋岸雪花初白，一夜林霜葉尽紅。","山叠楚天云壓塞，浪遙吳苑水連空。","悠然旅榜頻迴首，無复松窗半偈同。"]', '诗', 'shi', '', NULL, '盤石寺留別成公 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdc41346-8038-4112-8295-c2f483cf847d', '題中南佛塔寺', '題中南佛塔寺', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["鳴泉隔翠微，千里到柴扉。","地勝人無慾，林昏虎有威。","澗苔侵客屨，山雪入禪衣。","桂樹芳陰在，還期歲晏歸。"]', '["鳴泉隔翠微，千里到柴扉。","地勝人無慾，林昏虎有威。","澗苔侵客屨，山雪入禪衣。","桂樹芳陰在，還期歲晏归。"]', '诗', 'shi', '', NULL, '題中南佛塔寺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe7616f-ae91-496e-81a0-eb93bfc63854', '馬嵬佛寺', '马嵬佛寺', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["荒雞夜唱戰塵深，五鼓雕輿過上林。","才信傾城是真語，直敎塗地始甘心。","兩重秦苑成千里，一炷胡香抵萬金。","曼倩死來無絕藝，後人誰肯惜青禽。"]', '["荒雞夜唱戰塵深，五鼓雕輿過上林。","才信傾城是真語，直敎塗地始甘心。","兩重秦苑成千里，一炷胡香抵万金。","曼倩死来無絕藝，後人誰肯惜青禽。"]', '诗', 'shi', '', NULL, '馬嵬佛寺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed5f8328-25cf-4bfd-8dd8-307705d7e29a', '清涼寺', '清涼寺', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["黃花紅樹謝芳蹊，宮殿參差黛巘西。","詩閤曉窗藏雪嶺，畫堂秋水接藍溪。","松飄晚吹摐金鐸，竹蔭寒苔上石梯。","妙跡奇名竟何在，下方煙暝草萋萋。"]', '["黄花紅樹謝芳蹊，宮殿參差黛巘西。","诗閤晓窗藏雪嶺，畫堂秋水接藍溪。","松飄晚吹摐金鐸，竹蔭寒苔上石梯。","妙跡奇名竟何在，下方煙暝草萋萋。"]', '诗', 'shi', '', NULL, '清涼寺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb8064a9-c9ba-42ba-963c-1f7f747c9ba3', '贈盧長史', '贈盧长史', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["移病欲成隱，扁舟歸舊居。","地深新事少，官散故交疎。","道直更無侶，家貧唯有書。","東門煙水夢，非獨爲鱸魚。"]', '["移病欲成隐，扁舟归旧居。","地深新事少，官散故交疎。","道直更無侶，家貧唯有书。","东门煙水梦，非独爲鱸鱼。"]', '诗', 'shi', '', NULL, '贈盧長史 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e08bdbb8-e54a-4bd5-9531-d2b58222c1ff', '秋日旅舍寄義山李侍御', '秋日旅舍寄義山李侍御', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["一水悠悠隔渭城，渭城風物近柴荆。","寒蛩乍響催機杼，旅雁初來憶弟兄。","自爲林泉牽曉夢，不關砧杵報秋聲。","子虛何處堪消渴，試向文園問長卿。"]', '["一水悠悠隔渭城，渭城风物近柴荆。","寒蛩乍响催機杼，旅雁初来憶弟兄。","自爲林泉牽晓梦，不关砧杵報秋声。","子虛何处堪消渴，試向文园问长卿。"]', '诗', 'shi', '', NULL, '秋日旅舍寄義山李侍御 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f21525-51ba-4647-bbd5-02dc3d13a209', '晚坐寄友人', '晚坐寄友人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["九枝燈在瑣窗空，希逸無聊恨不同。","曉夢未離金夾膝，早寒先到石屏風。","遺簪可惜三秋白，蠟燭猶殘一寸紅。","應卷鰕簾看皓齒，鏡中惆悵見梧桐。"]', '["九枝灯在瑣窗空，希逸無聊恨不同。","晓梦未離金夾膝，早寒先到石屏风。","遺簪可惜三秋白，蠟燭猶殘一寸紅。","應卷鰕簾看皓齒，镜中惆悵见梧桐。"]', '诗', 'shi', '', NULL, '晚坐寄友人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f69a26f-024c-4e4f-b56e-dee8856e849c', '送渤海王子歸本國', '送渤海王子归本国', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["疆理雖重海，車書本一家。","盛勳歸舊國，佳句在中華。","定界分秋漲，開帆到曙霞。","九門風月好，回首是天涯。"]', '["疆理雖重海，车书本一家。","盛勳归旧国，佳句在中华。","定界分秋漲，开帆到曙霞。","九门风月好，回首是天涯。"]', '诗', 'shi', '', NULL, '送渤海王子歸本國 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4baa8c3-0669-46e9-859d-2633611a64f5', '送北陽袁明府', '送北陽袁明府', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["楚鄉千里路，君去及良晨。","葦浦迎船火，茶山候吏塵。","桑濃蠶臥晚，麥秀雉聲春。","莫作東籬興，青雲有故人。"]', '["楚乡千里路，君去及良晨。","葦浦迎船火，茶山候吏塵。","桑濃蠶臥晚，麦秀雉声春。","莫作东籬兴，青云有故人。"]', '诗', 'shi', '', NULL, '送北陽袁明府 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d64a360-20a5-46c6-a12d-c82b501ef489', '送李生歸舊居', '送李生归旧居', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["一從征戰後，故社幾人歸。","薄宦離山久，高談與世稀。","夕陽當板檻，春日入柴扉。","莫却嚴灘意，西溪有釣磯。"]', '["一從征戰後，故社幾人归。","薄宦離山久，高談與世稀。","夕陽當板檻，春日入柴扉。","莫却嚴灘意，西溪有釣磯。"]', '诗', 'shi', '', NULL, '送李生歸舊居 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f2691fb-476e-4196-9386-4d5a96b0fd77', '早春滻水送友人', '早春滻水送友人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["青門煙野外，渡滻送行人。","鴨臥溪沙暖，鳩鳴社樹春。","殘波青有石，幽草綠無塵。","楊柳東風裏，相看淚滿巾。"]', '["青门煙野外，渡滻送行人。","鴨臥溪沙暖，鳩鳴社樹春。","殘波青有石，幽草綠無塵。","楊柳东风裏，相看泪满巾。"]', '诗', 'shi', '', NULL, '早春滻水送友人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03917a86-15d2-4079-97f3-64c7a551309c', '送襄州李中丞赴從事', '送襄州李中丞赴從事', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["漢庭文采有相如，天子通宵愛子虛。","把釣看棊高興盡，焚香起草宦情疎。","楚山重疊當歸路，溪月分明到直廬。","江雨瀟瀟帆一片，此行誰道爲鱸魚。"]', '["漢庭文采有相如，天子通宵愛子虛。","把釣看棊高兴尽，焚香起草宦情疎。","楚山重叠當归路，溪月分明到直廬。","江雨瀟瀟帆一片，此行誰道爲鱸鱼。"]', '诗', 'shi', '', NULL, '送襄州李中丞赴從事 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b873a38-bd0c-4ef0-bc59-22e6e48ca9fb', '江上別友人', '江上別友人', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["秋色滿葭菼，離人西復東。","幾年方暫見，一笑又難同。","地勢蕭陵歇，江聲禹廟空。","如何暮灘上，千里逐征鴻。"]', '["秋色满葭菼，離人西复东。","幾年方暫见，一笑又难同。","地勢蕭陵歇，江声禹廟空。","如何暮灘上，千里逐征鴻。"]', '诗', 'shi', '', NULL, '江上別友人 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f236e58-0f26-4c27-ad5f-112c7368d6e1', '與友人別', '與友人別', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["半醉別都門，含悽上古原。","晚風楊葉社，寒食杏花村。","薄暮牽離緒，傷春憶晤言。","年芳本無限，何況有蘭孫。"]', '["半醉別都门，含悽上古原。","晚风楊葉社，寒食杏花村。","薄暮牽離緒，傷春憶晤言。","年芳本無限，何況有蘭孫。"]', '诗', 'shi', '', NULL, '與友人別 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ab3386-92d1-4156-be01-3c69ed11cec1', '鴻臚寺有開元中錫宴堂樓臺池沼雅爲勝絕荒涼遺址僅有存者偶成四十韻', '鴻臚寺有开元中錫宴堂楼台池沼雅爲勝絕荒涼遺址僅有存者偶成四十韻', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["明皇昔御極，神聖垂耿光。","沈機發雷電，逸躅陵堯湯。","西覃積石山，北至窮髮鄉。","四凶有獬豸，一臂無螳螂。","嬋娟得神豔，郁烈聞國香。","紫縧鳴羯鼓，玉管吹霓裳。","祿山未封侯，林甫才爲郎。","昭融廓日月，妥帖安紀綱。","羣生到壽域，百辟趨明堂。","四海正夷宴，一塵不飛揚。","天子自猶豫，侍臣宜樂康。","軋然閶闔開，赤日生扶桑。","玉砌露盤紆，金壺漏丁當。","劒佩相擊觸，左右隨趨蹌。","玄珠十二旒，紅粉三千行。","顧盻生羽翼，叱嗟廻雪霜。","神霞凌雲閣，春水驪山陽。","盤鬬九子糭，甌擎五雲漿。","雙瓊京兆博，七鼓邯鄲娼。","毰毸碧雞鬬，蘢葱翠雉場。","杖官繡蔽膝，寶馬金鏤錫。","椒塗隔鸚鵡，柘彈驚鴛鴦。","猗歟華國臣，鬢髪俱蒼蒼。","錫宴得幽致，車從真煒煌。","畫鷁照魚鼈，鳴騶亂鶖鶬。","颭灩蕩碧波，炫煌迷橫塘。","縈盈舞廻雪，宛轉歌遶梁。","豔帶畫銀絡，寶梳金鈿筐。","沈冥類漢相，醉倒疑楚狂。","一旦紫微東，胡星森耀芒。","憑陵逐鯨鯢，唐突驅犬羊。","縱火三月赤，戰塵千里黃。","殽函與府寺，從此俱荒涼。","茲地乃蔓草，故基摧壞牆。","枯池接斷岸，唧唧啼寒螿。","敗荷塌作泥，死竹森如槍。","遊人問老吏，相對聊感傷。","豈必見麋鹿，然後堪迴腸。","幸今遇太平，令節稱羽觴。","誰知曲江曲，歲歲棲鸞凰。"]', '["明皇昔御極，神聖垂耿光。","沈機發雷電，逸躅陵堯湯。","西覃積石山，北至窮髮乡。","四凶有獬豸，一臂無螳螂。","嬋娟得神豔，郁烈闻国香。","紫縧鳴羯鼓，玉管吹霓裳。","祿山未封侯，林甫才爲郎。","昭融廓日月，妥帖安紀綱。","羣生到壽域，百辟趨明堂。","四海正夷宴，一塵不飞揚。","天子自猶豫，侍臣宜乐康。","軋然閶闔开，赤日生扶桑。","玉砌露盤紆，金壺漏丁當。","劒佩相擊觸，左右隨趨蹌。","玄珠十二旒，紅粉三千行。","顧盻生羽翼，叱嗟廻雪霜。","神霞凌云閣，春水驪山陽。","盤鬬九子糭，甌擎五云漿。","雙瓊京兆博，七鼓邯鄲娼。","毰毸碧雞鬬，蘢葱翠雉場。","杖官繡蔽膝，寶马金鏤錫。","椒塗隔鸚鵡，柘彈驚鴛鴦。","猗歟华国臣，鬢髪俱蒼蒼。","錫宴得幽致，车從真煒煌。","畫鷁照鱼鼈，鳴騶亂鶖鶬。","颭灩蕩碧波，炫煌迷橫塘。","縈盈舞廻雪，宛轉歌遶梁。","豔带畫銀絡，寶梳金鈿筐。","沈冥類漢相，醉倒疑楚狂。","一旦紫微东，胡星森耀芒。","憑陵逐鯨鯢，唐突驱犬羊。","縱火三月赤，戰塵千里黄。","殽函與府寺，從此俱荒涼。","茲地乃蔓草，故基摧壞牆。","枯池接斷岸，唧唧啼寒螿。","敗荷塌作泥，死竹森如槍。","游人问老吏，相对聊感傷。","豈必见麋鹿，然後堪迴腸。","幸今遇太平，令節稱羽觴。","誰知曲江曲，歲歲棲鸾凰。"]', '诗', 'shi', '', NULL, '鴻臚寺有開元中錫宴堂樓臺池沼雅爲勝絕荒涼遺址僅有存者偶成四十韻 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c89cff-2211-4098-a95a-ab1393babc17', '訪知玄上人遇暴經因有贈', '訪知玄上人遇暴經因有贈', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["縹帙無塵滿畫廊，鍾山弟子靜焚香。","惠能未肯傳心法，張湛徒勞與眼方。","風颺檀煙銷篆印，日移松影過禪牀。","客兒自有翻經處，江上秋來蕙草荒。"]', '["縹帙無塵满畫廊，鍾山弟子静焚香。","惠能未肯傳心法，張湛徒勞與眼方。","风颺檀煙銷篆印，日移松影過禪牀。","客兒自有翻經处，江上秋来蕙草荒。"]', '诗', 'shi', '', NULL, '訪知玄上人遇暴經因有贈 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c980c4e-a8b9-4db8-9c46-8b05b644636d', '寄崔先生', '寄崔先生', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["往年江海別元卿，家近山陽古郡城。","蓮浦香中離席散，柳堤風裏釣船橫。","星霜荏苒無音信，煙水微茫變姓名。","菰黍正肥魚正美，五侯門下負平生。"]', '["往年江海別元卿，家近山陽古郡城。","蓮浦香中離席散，柳堤风裏釣船橫。","星霜荏苒無音信，煙水微茫变姓名。","菰黍正肥鱼正美，五侯门下負平生。"]', '诗', 'shi', '', NULL, '寄崔先生 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d68ac4e-db5a-4d16-8b80-5b5f035559b2', '敬荅李先生', '敬荅李先生', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["七里灘聲舜廟前，杏花初盛草芊芊。","綠昏晴氣春風岸，紅漾輕綸野水天。","不爲傷離成極望，更因行樂惜流年。","一瓢無事麛裘暖，手弄溪波坐釣船。"]', '["七里灘声舜廟前，杏花初盛草芊芊。","綠昏晴氣春风岸，紅漾轻綸野水天。","不爲傷離成極望，更因行乐惜流年。","一瓢無事麛裘暖，手弄溪波坐釣船。"]', '诗', 'shi', '', NULL, '敬荅李先生 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eca4a53-2996-4fa4-8666-c94201243541', '宿灃曲僧舍', '宿灃曲僧舍', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["東郊和氣新，芳靄遠如塵。","客舍停疲馬，僧牆畫故人。","沃田桑景晚，平野菜花春。","更想嚴家瀨，微風蕩白蘋。"]', '["东郊和氣新，芳靄远如塵。","客舍停疲马，僧牆畫故人。","沃田桑景晚，平野菜花春。","更想嚴家瀨，微风蕩白蘋。"]', '诗', 'shi', '', NULL, '宿灃曲僧舍 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b78e2c8-f630-4cce-b91a-08bff2b84616', '宿一公精舍', '宿一公精舍', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["夜闌黃葉寺，瓶錫兩俱能。","松下石橋路，雨中山殿燈。","茶爐天姥客，棊席剡溪僧。","還笑長門賦，高秋臥茂陵。"]', '["夜闌黄葉寺，瓶錫兩俱能。","松下石橋路，雨中山殿灯。","茶爐天姥客，棊席剡溪僧。","還笑长门賦，高秋臥茂陵。"]', '诗', 'shi', '', NULL, '宿一公精舍 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b68fa0cc-21c8-4c35-a0f9-2268070d3559', '月中宿雲居寺上方', '月中宿云居寺上方', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["虛閤披衣坐，寒堦踏葉行。","衆星中夜少，圓月上方明。","靄盡無林色，喧餘有澗聲。","祗應愁恨事，還逐曉光生。"]', '["虛閤披衣坐，寒堦踏葉行。","衆星中夜少，圓月上方明。","靄尽無林色，喧餘有澗声。","祗應愁恨事，還逐晓光生。"]', '诗', 'shi', '', NULL, '月中宿雲居寺上方 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00386e6d-492f-4531-a527-69b20c28d345', '登盧氏臺', '登盧氏台', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["勝地當通邑，前山有故居。","臺高秋盡出，林斷野無餘。","白露鳴蛩急，晴天度雁疎。","由來放懷地，非獨在吾廬。"]', '["勝地當通邑，前山有故居。","台高秋尽出，林斷野無餘。","白露鳴蛩急，晴天度雁疎。","由来放懷地，非独在吾廬。"]', '诗', 'shi', '', NULL, '登盧氏臺 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08beb140-b310-459c-bde8-fee049e1d102', '牡丹二首 一', '牡丹二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["輕陰隔翠幃，宿雨泣晴暉。","醉後佳期在，歌餘舊意非。","蝶繁經粉住，蜂重抱香歸。","莫惜薰爐夜，因風到舞衣。"]', '["轻陰隔翠幃，宿雨泣晴暉。","醉後佳期在，歌餘旧意非。","蝶繁經粉住，蜂重抱香归。","莫惜薰爐夜，因风到舞衣。"]', '诗', 'shi', '', NULL, '牡丹二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa9e8394-46b3-41a0-b483-4342a5d54058', '牡丹二首 二', '牡丹二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["水漾晴紅壓疊波，曉來金粉覆庭莎。","裁成豔思偏應巧，分得春光最數多。","欲綻似含雙靨笑，正繁疑有一聲歌。","華堂客散簾垂地，想凭闌干歛翠蛾。"]', '["水漾晴紅壓叠波，晓来金粉覆庭莎。","裁成豔思偏應巧，分得春光最數多。","欲綻似含雙靨笑，正繁疑有一声歌。","华堂客散簾垂地，想凭闌干歛翠蛾。"]', '诗', 'shi', '', NULL, '牡丹二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea9e459-2092-4f7d-a28b-1e7b3d0af58c', '反生桃花發因題', '反生桃花發因題', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["疾眼逢春四壁空，夜來山雪破東風。","未知王母千年熟，且共劉郎一笑同。","已落又開橫晚翠，似無如有帶朝紅。","僧虔蠟炬高三尺，莫惜連宵照露叢。"]', '["疾眼逢春四壁空，夜来山雪破东风。","未知王母千年熟，且共劉郎一笑同。","已落又开橫晚翠，似無如有带朝紅。","僧虔蠟炬高三尺，莫惜連宵照露叢。"]', '诗', 'shi', '', NULL, '反生桃花發因題 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('915f4d25-28e2-4a3c-82de-6af7e241e0dc', '杏花', '杏花', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["紅花初綻雪花繁，重疊高低滿小園。","正見盛時猶悵望，豈堪開處已繽翻。","情爲世累詩千首，醉是吾鄉酒一樽。","杳杳豔歌春日午，出牆何處隔朱門。"]', '["紅花初綻雪花繁，重叠高低满小园。","正见盛时猶悵望，豈堪开处已繽翻。","情爲世累诗千首，醉是吾乡酒一樽。","杳杳豔歌春日午，出牆何处隔朱门。"]', '诗', 'shi', '', NULL, '杏花 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf84891-b511-41a5-99ed-5bb23f9b8ca3', '和太常杜少卿東都脩[行]里有嘉蓮', '和太常杜少卿东都脩[行]里有嘉蓮', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["春秋罷注直銅龍，舊宅嘉蓮照水紅。","兩處龜巢清露裏，一時魚躍翠莖東。","同心表瑞荀池上，半面分妝樂鏡中。","應爲臨川多麗句，故持重豔向西風。"]', '["春秋罷注直銅龙，旧宅嘉蓮照水紅。","兩处龟巢清露裏，一时鱼躍翠莖东。","同心表瑞荀池上，半面分妝乐镜中。","應爲臨川多丽句，故持重豔向西风。"]', '诗', 'shi', '', NULL, '和太常杜少卿東都脩[行]里有嘉蓮 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9283238-3bd2-4a4d-890b-e31483c7906b', '題磁嶺海棠花', '題磁嶺海棠花', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["幽態竟誰賞，歲華空與期。","島迴香盡處，泉照豔濃時。","蜀彩淡搖曳，吳妝低怨思。","王孫又誰恨，惆悵下山遲。"]', '["幽態竟誰賞，歲华空與期。","島迴香尽处，泉照豔濃时。","蜀彩淡搖曳，吳妝低怨思。","王孫又誰恨，惆悵下山遲。"]', '诗', 'shi', '', NULL, '題磁嶺海棠花 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66aafecf-6095-4a95-917c-e509fd56cb86', '苦楝花', '苦楝花', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["院裏鶯歌歇，牆頭蝶舞孤。","天香薰羽葆，宮紫暈流蘇。","晻曖迷青瑣，氤氳向畫圖。","只應春惜別，留與博山爐。"]', '["院裏鶯歌歇，牆头蝶舞孤。","天香薰羽葆，宮紫暈流蘇。","晻曖迷青瑣，氤氳向畫圖。","只應春惜別，留與博山爐。"]', '诗', 'shi', '', NULL, '苦楝花 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('385c76fb-c45b-49e3-9958-91fb3b08b927', '自有扈至京師已後朱櫻之期', '自有扈至京師已後朱櫻之期', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["露圓霞赤數千枝，銀籠誰家寄所思。","秦苑飛禽諳熟早，杜陵遊客恨來遲。","空看翠幄成陰日，不見紅珠滿樹時。","盡日徘徊濃影下，祗應重作釣魚期。"]', '["露圓霞赤數千枝，銀籠誰家寄所思。","秦苑飞禽諳熟早，杜陵游客恨来遲。","空看翠幄成陰日，不见紅珠满樹时。","尽日徘徊濃影下，祗應重作釣鱼期。"]', '诗', 'shi', '', NULL, '自有扈至京師已後朱櫻之期 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde19b81-d062-4bca-915d-352157c3a198', '答段柯古見嘲', '答段柯古见嘲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["彩翰殊翁金繚繞，一千二百逃飛鳥。","尾薪橋下未爲癡，暮雨朝雲世間少。"]', '["彩翰殊翁金繚繞，一千二百逃飞鸟。","尾薪橋下未爲癡，暮雨朝云世间少。"]', '诗', 'shi', '', NULL, '答段柯古見嘲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb424b41-4b6e-4c5b-979b-b109cae6db68', '蓮花', '蓮花', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["綠塘搖灩接星津，軋軋蘭橈入白蘋。","應爲洛神波上韈，至今蓮蘂有香塵。"]', '["綠塘搖灩接星津，軋軋蘭橈入白蘋。","應爲洛神波上韈，至今蓮蘂有香塵。"]', '诗', 'shi', '', NULL, '蓮花 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce747c86-a756-4fdb-83f8-a0216dcbf3ab', '過吳景帝陵', '過吳景帝陵', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["王氣銷來水淼茫，豈能才與命相妨。","虛開直瀆三千里，青蓋何曾到洛陽。"]', '["王氣銷来水淼茫，豈能才與命相妨。","虛开直瀆三千里，青蓋何曾到洛陽。"]', '诗', 'shi', '', NULL, '過吳景帝陵 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03ad4be6-155c-4ce6-a085-4d06ccf0a140', '龍尾驛婦人圖', '龙尾驛婦人圖', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["慢笑開元有倖臣，直敎天子到蒙塵。","今來看畫猶如此，何況親逢絕世人。"]', '["慢笑开元有倖臣，直敎天子到蒙塵。","今来看畫猶如此，何況親逢絕世人。"]', '诗', 'shi', '', NULL, '龍尾驛婦人圖 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb4e0a9a-e59b-4650-9e2b-335ef5f83f4f', '薛氏池垂釣', '薛氏池垂釣', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["池塘經雨更蒼蒼，萬點荷珠曉氣涼。","朱瑀空偷御溝水，錦鱗紅尾屬嚴光。"]', '["池塘經雨更蒼蒼，万点荷珠晓氣涼。","朱瑀空偷御溝水，錦鱗紅尾屬嚴光。"]', '诗', 'shi', '', NULL, '薛氏池垂釣 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d56fe90a-6357-40d4-9ae3-3ec98f03a01e', '簡同志', '簡同志', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["開濟由來變盛衰，五車纔得號鎡基。","留侯功業何容易，一卷兵書作帝師。"]', '["开濟由来变盛衰，五车纔得號鎡基。","留侯功業何容易，一卷兵书作帝師。"]', '诗', 'shi', '', NULL, '簡同志 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d1895aa-a267-42d3-8acf-be58cfee7df0', '瑟瑟釵', '瑟瑟釵', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["翠染冰輕透露光，墮雲孫壽有餘香。","只因七夕回天浪，添作湘妃淚兩行。"]', '["翠染冰轻透露光，墮云孫壽有餘香。","只因七夕回天浪，添作湘妃泪兩行。"]', '诗', 'shi', '', NULL, '瑟瑟釵 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e4058d3-9158-434a-ad2c-d46ed5cc73e2', '元日', '元日', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["神耀破氛昏，新陽入晏溫。","緒風調玉吹，端日應銅渾。","威鳳蹌瑤簴，升龍護璧門。","雨暘春令煦，裘冕晬容尊。"]', '["神耀破氛昏，新陽入晏溫。","緒风調玉吹，端日應銅渾。","威鳳蹌瑤簴，升龙護璧门。","雨暘春令煦，裘冕晬容尊。"]', '诗', 'shi', '', NULL, '元日 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('575c2162-ca4d-48be-82c8-f6afda95ae39', '二月十五日櫻桃盛開自所居躡履吟翫競名王澤章洋才', '二月十五日櫻桃盛开自所居躡履吟翫競名王澤章洋才', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["曉覺籠煙重，春深染雪輕。","靜應留得蝶，繁欲不勝鶯。","影亂晨飆急，香多夜雨晴。","似將千萬恨，西北爲卿卿。"]', '["晓覺籠煙重，春深染雪轻。","静應留得蝶，繁欲不勝鶯。","影亂晨飆急，香多夜雨晴。","似將千万恨，西北爲卿卿。"]', '诗', 'shi', '', NULL, '二月十五日櫻桃盛開自所居躡履吟翫競名王澤章洋才 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('323a84b9-bb22-4e62-b77a-3f051f2ab401', '寒食節日寄楚望二首 一', '寒食節日寄楚望二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["芳蘭無意綠，弱柳何窮縷。","心斷入淮山，夢長穿楚雨。","繁花如二八，好月當三五。","愁碧竟平臯，韶紅換幽圃。","流鶯隱員樹，乳燕喧餘哺。","曠望戀曾臺，離憂集環堵。","當年不自遣，晚得終何補。","鄭谷有樵蘇，歸來要腰斧。"]', '["芳蘭無意綠，弱柳何窮縷。","心斷入淮山，梦长穿楚雨。","繁花如二八，好月當三五。","愁碧竟平臯，韶紅換幽圃。","流鶯隐員樹，乳燕喧餘哺。","曠望戀曾台，離憂集环堵。","當年不自遣，晚得終何補。","鄭谷有樵蘇，归来要腰斧。"]', '诗', 'shi', '', NULL, '寒食節日寄楚望二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('057cfa1b-fb2e-4c46-8c82-e5de0e499b20', '寒食節日寄楚望二首 二', '寒食節日寄楚望二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["家乏兩千萬，時當一百五。","颸颸楊柳風，穰穰櫻桃雨。","年芳苦沈潦，心事如摧櫓。","金犢近蘭汀，銅龍接花塢。","青蔥建楊宅，隱轔端門鼓。","綵素拂庭柯，輕毬落鄰圃。","三春謝游衍，一笑牽規矩。","獨有恩澤侯，歸來看楚舞。"]', '["家乏兩千万，时當一百五。","颸颸楊柳风，穰穰櫻桃雨。","年芳苦沈潦，心事如摧櫓。","金犢近蘭汀，銅龙接花塢。","青蔥建楊宅，隐轔端门鼓。","綵素拂庭柯，轻毬落鄰圃。","三春謝游衍，一笑牽規矩。","独有恩澤侯，归来看楚舞。"]', '诗', 'shi', '', NULL, '寒食節日寄楚望二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65c96a3e-fba7-4cf8-af72-5f1f57762462', '清明日', '清明日', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["清娥畫扇中，春樹鬱金紅。","出犯繁花露，歸穿弱柳風。","馬驕偏避幰，雞駭乍開籠。","柘彈何人發，黃鸝隔故宮。"]', '["清娥畫扇中，春樹鬱金紅。","出犯繁花露，归穿弱柳风。","马驕偏避幰，雞駭乍开籠。","柘彈何人發，黄鸝隔故宮。"]', '诗', 'shi', '', NULL, '清明日 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dfa0f12-2290-4904-a663-bcb7480d077e', '禁火日', '禁火日', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["駘蕩清明日，儲胥小苑東。","舞衫萱草綠，春鬢杏花紅。","馬轡輕銜雪，車衣弱向風。","□愁聞百舌，殘睡正朦朧。"]', '["駘蕩清明日，儲胥小苑东。","舞衫萱草綠，春鬢杏花紅。","马轡轻銜雪，车衣弱向风。","□愁闻百舌，殘睡正朦朧。"]', '诗', 'shi', '', NULL, '禁火日 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5841edd-bd55-42c2-b84e-0d7f743ff116', '嘲三月十八日雪', '嘲三月十八日雪', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["三月雪連夜，未應傷物華。","只緣春欲盡，留著伴梨花。"]', '["三月雪連夜，未應傷物华。","只緣春欲尽，留著伴梨花。"]', '诗', 'shi', '', NULL, '嘲三月十八日雪 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d31960c-d25a-4a87-bfb0-b98efa79bf47', '楊柳八首 一', '楊柳八首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["宜春苑外最長條。","閑褭春風伴舞腰，正是玉人腸斷處。","一渠春水赤闌橋。"]', '["宜春苑外最长條。","闲褭春风伴舞腰，正是玉人腸斷处。","一渠春水赤闌橋。"]', '诗', 'shi', '', NULL, '楊柳八首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4656ce47-275b-4a86-9dbd-da18c4c0ffbf', '楊柳八首 二', '楊柳八首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["南內牆東御路旁，預知春色柳絲黃。","杏花未肯無情思，何是情人最斷腸。"]', '["南內牆东御路旁，預知春色柳絲黄。","杏花未肯無情思，何是情人最斷腸。"]', '诗', 'shi', '', NULL, '楊柳八首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16c21dcb-a84e-4068-b934-c0a5518aa478', '楊柳八首 三', '楊柳八首 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蘇小門前柳萬條，毶毶金線拂平橋。","黃鶯不語東風起，深閉朱門伴細腰。"]', '["蘇小门前柳万條，毶毶金線拂平橋。","黄鶯不語东风起，深閉朱门伴細腰。"]', '诗', 'shi', '', NULL, '楊柳八首 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c03ffdd-3b92-4582-9930-b8a07a3ba179', '楊柳八首 四', '楊柳八首 四', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["金縷毶毶碧瓦溝，六宮眉黛惹春愁。","晚來更帶龍池雨，半拂闌干半入樓。"]', '["金縷毶毶碧瓦溝，六宮眉黛惹春愁。","晚来更带龙池雨，半拂闌干半入楼。"]', '诗', 'shi', '', NULL, '楊柳八首 四 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('654a58d7-6cfc-4435-a218-f733476a3e58', '楊柳八首 五', '楊柳八首 五', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["館娃宮外鄴城西，遠映征帆近拂堤。","繫得王孫歸意切，不關春草綠萋萋。"]', '["館娃宮外鄴城西，远映征帆近拂堤。","繫得王孫归意切，不关春草綠萋萋。"]', '诗', 'shi', '', NULL, '楊柳八首 五 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f86ff3bb-c21e-4aee-84f4-b40ad7141140', '楊柳八首 六', '楊柳八首 六', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["兩兩黃鸝色似金，褭枝啼露動芳音。","春來幸自長如線，可惜牽纏蕩子心。"]', '["兩兩黄鸝色似金，褭枝啼露动芳音。","春来幸自长如線，可惜牽纏蕩子心。"]', '诗', 'shi', '', NULL, '楊柳八首 六 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1322d148-cf71-42ff-90f1-1aae04a5726d', '楊柳八首 七', '楊柳八首 七', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["御柳如絲映九重，鳳皇窗柱繡芙蓉。","景陽樓畔千條露，一面新妝待曉鐘。"]', '["御柳如絲映九重，鳳皇窗柱繡芙蓉。","景陽楼畔千條露，一面新妝待晓鐘。"]', '诗', 'shi', '', NULL, '楊柳八首 七 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d777d8e-a869-415a-b8d3-b74b98b5288a', '楊柳八首 八', '楊柳八首 八', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["織錦機邊鶯語頻，停梭垂淚憶征人。","塞門三月猶蕭索，縱有垂楊未覺春。"]', '["织錦機邊鶯語頻，停梭垂泪憶征人。","塞门三月猶蕭索，縱有垂楊未覺春。"]', '诗', 'shi', '', NULL, '楊柳八首 八 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e65b8909-1235-4fbd-9f5d-40d81d4b3112', '客愁', '客愁', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["客愁看柳色，日日逐春深。","蕩漾春風裏，誰知歷亂心。"]', '["客愁看柳色，日日逐春深。","蕩漾春风裏，誰知歷亂心。"]', '诗', 'shi', '', NULL, '客愁 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa812073-86cf-4b9d-9539-3bee917a5cf2', '和周繇', '和周繇', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["齊馬馳千駟，盧姬逞十三。","玳筵方喜睞，金勒自䟃𧽼。","墮珥情初洽，鳴鞭戰未酣。","神交花冉冉，眉語柳毶毶。","却略青鸞鏡，翹翻翠鳳篸。","專城有佳對，寧肯顧春蠶。"]', '["齊马驰千駟，盧姬逞十三。","玳筵方喜睞，金勒自䟃𧽼。","墮珥情初洽，鳴鞭戰未酣。","神交花冉冉，眉語柳毶毶。","却略青鸾镜，翹翻翠鳳篸。","專城有佳对，寧肯顧春蠶。"]', '诗', 'shi', '', NULL, '和周繇 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b06a903-4fa6-48a9-9dd4-55ea26e92afc', '光風亭夜宴妓有醉毆者', '光风亭夜宴妓有醉毆者', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["吳國初成陣，王家欲解圍。","拂巾雙雉呌，飄瓦兩鴛飛。"]', '["吳国初成陣，王家欲解圍。","拂巾雙雉呌，飄瓦兩鴛飞。"]', '诗', 'shi', '', NULL, '光風亭夜宴妓有醉毆者 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('688fb8de-66a2-4b46-a27b-4de5336730b2', '南歌子詞二首 一', '南歌子词二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["一尺深紅勝麴塵，天生舊物不如新。","合歡桃核終堪恨，裏許元來別有人。"]', '["一尺深紅勝麴塵，天生旧物不如新。","合歡桃核終堪恨，裏許元来別有人。"]', '诗', 'shi', '', NULL, '南歌子詞二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c537e4db-502d-45dd-a795-aed2d2a95d6d', '南歌子詞二首 二', '南歌子词二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["井底點燈深燭伊，共郎長行莫圍棊。","玲瓏骰子安紅豆，入骨相思知不知。"]', '["井底点灯深燭伊，共郎长行莫圍棊。","玲瓏骰子安紅豆，入骨相思知不知。"]', '诗', 'shi', '', NULL, '南歌子詞二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c80158ca-6953-4032-a5c8-87891536a441', '題李衛公詩二首 一', '題李衛公诗二首 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蒿棘深春衛國門，九年於此盜乾坤。","兩行密疏傾天下，一夜陰謀達至尊。","肉視具僚忘匕箸，氣吞同列削寒溫。","當時誰是承恩者，肯有餘波達鬼邨。"]', '["蒿棘深春衛国门，九年於此盜乾坤。","兩行密疏傾天下，一夜陰謀達至尊。","肉視具僚忘匕箸，氣吞同列削寒溫。","當时誰是承恩者，肯有餘波達鬼邨。"]', '诗', 'shi', '', NULL, '題李衛公詩二首 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e707b6c3-ba99-478c-bd91-9accdb6409c5', '題李衛公詩二首 二', '題李衛公诗二首 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["勢欲凌雲威觸天，權傾諸夏力排山。","三年驥尾有人附，一日龍鬚無路攀。","畫閤不開梁燕去，朱門罷埽乳鴉還。","千巖萬壑應惆悵，流水斜傾出武關。"]', '["勢欲凌云威觸天，權傾諸夏力排山。","三年驥尾有人附，一日龙鬚無路攀。","畫閤不开梁燕去，朱门罷埽乳鴉還。","千巖万壑應惆悵，流水斜傾出武关。"]', '诗', 'shi', '', NULL, '題李衛公詩二首 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b2b013-93a2-4e0b-853a-5b005bac410c', '題谷隱蘭若', '題谷隐蘭若', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["風帶巢熊拗樹聲，老僧相引入雲行。","半坡新路畬纔了，一谷寒煙燒不成。"]', '["风带巢熊拗樹声，老僧相引入云行。","半坡新路畬纔了，一谷寒煙燒不成。"]', '诗', 'shi', '', NULL, '題谷隱蘭若 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30da3614-2556-4eaa-bfa8-a97145f54895', '觀棋', '观棋', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["閑對楸枰傾一壺，黃華坪上幾成盧。","他時謁帝銅龍水，便賭宣城太守無。"]', '["闲对楸枰傾一壺，黄华坪上幾成盧。","他时謁帝銅龙水，便賭宣城太守無。"]', '诗', 'shi', '', NULL, '觀棋 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64994a46-d3eb-436b-880f-a297a858fcc0', '句', '句', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["春水碧于天，畫船聽雨眠。","綠樹遶村含細雨，寒潮背郭捲平沙。"]', '["春水碧于天，畫船听雨眠。","綠樹遶村含細雨，寒潮背郭捲平沙。"]', '诗', 'shi', '', NULL, '句 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef67c8e4-b627-4ffa-a8b1-c5cdffa35591', '觀山燈獻徐尚書 一', '观山灯獻徐尚书 一', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["風杪影凌亂，露輕光陸離。","如霞散仙掌，似燒上峨嵋。","道樹千花發，扶桑九日移。","因山成衆像，不復藉蟠螭。"]', '["风杪影凌亂，露轻光陸離。","如霞散仙掌，似燒上峨嵋。","道樹千花發，扶桑九日移。","因山成衆像，不复藉蟠螭。"]', '诗', 'shi', '', NULL, '觀山燈獻徐尚書 一 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('324cd202-c348-4456-b024-6940f1f5dc50', '觀山燈獻徐尚書 二', '观山灯獻徐尚书 二', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["湧出多寶塔，往來飛錫僧。","分明三五月，傳照百千燈。","馴狖移高柱，慶雲遮半層。","夜深寒焰白，猶自綴金繩。"]', '["湧出多寶塔，往来飞錫僧。","分明三五月，傳照百千灯。","馴狖移高柱，慶云遮半層。","夜深寒焰白，猶自綴金繩。"]', '诗', 'shi', '', NULL, '觀山燈獻徐尚書 二 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9916f6e-0186-419c-9021-4ac53631f1fb', '觀山燈獻徐尚書 三', '观山灯獻徐尚书 三', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["磊落風初定，輕明雲乍妨。","疎中搖月彩，繁處雜星芒。","火樹枝柯密，燭龍鱗甲張。","窮愁讀書者，應得假餘光。"]', '["磊落风初定，轻明云乍妨。","疎中搖月彩，繁处杂星芒。","火樹枝柯密，燭龙鱗甲張。","窮愁读书者，應得假餘光。"]', '诗', 'shi', '', NULL, '觀山燈獻徐尚書 三 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eed3916-7d7a-42b6-817f-0c7f1dd360a6', '和徐商賀盧員外賜緋', '和徐商賀盧員外賜緋', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["雲雨軒懸鶯語新，一篇佳句占陽春。","銀黃年少偏欺酒，金紫風流不讓人。","連璧座中斜日滿，貫珠歌裏落花頻。","莫辭倒載吟歸去，看欲東山又吐茵。"]', '["云雨軒懸鶯語新，一篇佳句占陽春。","銀黄年少偏欺酒，金紫风流不讓人。","連璧座中斜日满，貫珠歌裏落花頻。","莫辞倒載吟归去，看欲东山又吐茵。"]', '诗', 'shi', '', NULL, '和徐商賀盧員外賜緋 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94171fc7-7ada-4034-85ec-2890c7e28be1', '河出榮光', '河出榮光', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["符命自陶唐，吾君應會昌。","千年清德水，九折滿榮花。","極岸浮佳氣，微波照夕陽。","澄輝明貝闕，散彩入龍堂。","近帶關雲紫，遙連日道黃。","馮夷矜海若，漢武貴宣房。","漸沒孤槎影，仍呈一葦航。","撫躬悲未濟，作頌喜時康。"]', '["符命自陶唐，吾君應會昌。","千年清德水，九折满榮花。","極岸浮佳氣，微波照夕陽。","澄輝明貝闕，散彩入龙堂。","近带关云紫，遙連日道黄。","馮夷矜海若，漢武貴宣房。","漸沒孤槎影，仍呈一葦航。","撫躬悲未濟，作頌喜时康。"]', '诗', 'shi', '', NULL, '河出榮光 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2e631ad-5333-434d-b1d5-d252fd9b8393', '哭李羣玉', '哭李羣玉', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["曾話黃陵事，今爲白日摧。","老無兒女累，誰哭到泉臺。"]', '["曾話黄陵事，今爲白日摧。","老無兒女累，誰哭到泉台。"]', '诗', 'shi', '', NULL, '哭李羣玉 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a112dc1-add5-4247-80d2-72e3528d17c4', '寄溫飛卿牋紙', '寄溫飞卿牋紙', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["三十六鱗充使時，數番猶得裹相思。","待將袍襖重抄了，盡寫襄陽播掿詞。"]', '["三十六鱗充使时，數番猶得裹相思。","待將袍襖重抄了，尽寫襄陽播掿词。"]', '诗', 'shi', '', NULL, '寄溫飛卿牋紙 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7e4aa99-98a3-49f0-a7fd-3e4eb5f4fd1f', '題石泉蘭若', '題石泉蘭若', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["矗竹爲籬松作門，石楠陰底藉芳蓀。","方袍近日少平叔，注得逍遙無處論。"]', '["矗竹爲籬松作门，石楠陰底藉芳蓀。","方袍近日少平叔，注得逍遙無处論。"]', '诗', 'shi', '', NULL, '題石泉蘭若 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fea28a6e-fb82-4fb2-ac7e-9eab32fded36', '怯酒贈周繇', '怯酒贈周繇', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["大白東西飛正狂，新芻石凍雜梅香。","詩中反語常回避，尤怯花前喚索郎。"]', '["大白东西飞正狂，新芻石凍杂梅香。","诗中反語常回避，尤怯花前喚索郎。"]', '诗', 'shi', '', NULL, '怯酒贈周繇 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7882462e-7b40-4dda-bbf6-a3ec9aec511a', '牛尊師宅看牡丹', '牛尊師宅看牡丹', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["洞裏仙春日更長，翠叢風翦紫霞芳。","若爲蕭史通家客，情願扛壺入醉鄉。"]', '["洞裏仙春日更长，翠叢风翦紫霞芳。","若爲蕭史通家客，情願扛壺入醉乡。"]', '诗', 'shi', '', NULL, '牛尊師宅看牡丹 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d63ba2fc-dc8e-4964-8cf5-255d31cdf17e', '觀碁', '观碁', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["閑對奕楸傾一壺，黃羊枰上幾成都。","他時謁帝銅池曉，便賭宣城太守無。"]', '["闲对奕楸傾一壺，黄羊枰上幾成都。","他时謁帝銅池晓，便賭宣城太守無。"]', '诗', 'shi', '', NULL, '觀碁 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7af29f8-ff7d-44bc-88ed-0466cf862779', '題僧壁', '題僧壁', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["有僧支頰撚眉毫，起就夕陽磨剃刀。","到此既知閑最樂，俗心何啻九牛毛。"]', '["有僧支頰撚眉毫，起就夕陽磨剃刀。","到此既知闲最乐，俗心何啻九牛毛。"]', '诗', 'shi', '', NULL, '題僧壁 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a346e1-7a5b-44f7-9d56-034cea386d71', '哭房處士', '哭房处士', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["獨上黃壇幾度盟，印開龍渥喜丹成。","豈同叔夜終無分，空向人間著養生。"]', '["独上黄壇幾度盟，印开龙渥喜丹成。","豈同叔夜終無分，空向人间著養生。"]', '诗', 'shi', '', NULL, '哭房處士 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('054c2d06-e7be-4819-bd77-5291c8b87c3c', '呈輪上人', '呈輪上人', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["虎到前頭心不驚，殘陽擇蝨嬾逢迎。","東林水石未勝此，要假遠公方有名。"]', '["虎到前头心不驚，殘陽擇蝨嬾逢迎。","东林水石未勝此，要假远公方有名。"]', '诗', 'shi', '', NULL, '呈輪上人 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07be5648-4397-4783-97c0-c8d21655f87f', '題谷隱蘭若三首 一', '題谷隐蘭若三首 一', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["風惹閑雲半谷陰，巖西隱者醉相尋。","草衰乍覺徑增險，葉盡却疑溪不深。"]', '["风惹闲云半谷陰，巖西隐者醉相尋。","草衰乍覺徑增險，葉尽却疑溪不深。"]', '诗', 'shi', '', NULL, '題谷隱蘭若三首 一 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed260a37-a23a-4ee9-bdab-8397e4c86f0d', '題谷隱蘭若三首 二', '題谷隐蘭若三首 二', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["鳥啄靈雛戀落暉，村情山趣頓忘機。","丹成道士過門數，葉盡寒猨下嶺稀。"]', '["鸟啄靈雛戀落暉，村情山趣頓忘機。","丹成道士過门數，葉尽寒猨下嶺稀。"]', '诗', 'shi', '', NULL, '題谷隱蘭若三首 二 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4dfb91d-4152-4314-814d-020a981a2a71', '題谷隱蘭若三首 三', '題谷隐蘭若三首 三', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["風帶巢熊拗樹聲，老僧相引入雲行。","半陂新路畬纔了，一谷寒煙燒不成。"]', '["风带巢熊拗樹声，老僧相引入云行。","半陂新路畬纔了，一谷寒煙燒不成。"]', '诗', 'shi', '', NULL, '題谷隱蘭若三首 三 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d596aaaf-fbb5-49fc-ac0a-b756881166b5', '不赴光風亭夜飲贈周繇', '不赴光风亭夜饮贈周繇', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["屏開屈膝見吳娃，蠻蠟同心四照花。","姹女不愁難管領，斬新鉛裏得黃牙。"]', '["屏开屈膝见吳娃，蠻蠟同心四照花。","姹女不愁难管領，斬新鉛裏得黄牙。"]', '诗', 'shi', '', NULL, '不赴光風亭夜飲贈周繇 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('949cd94d-bc84-46e1-82cb-6a8ad0755686', '嘲元中丞', '嘲元中丞', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["鶯裏花前選孟光，東山逋客酒初狂。","素蛾畢竟難防備，燒得河車莫遣嘗。"]', '["鶯裏花前選孟光，东山逋客酒初狂。","素蛾畢竟难防備，燒得河车莫遣嘗。"]', '诗', 'shi', '', NULL, '嘲元中丞 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece7564c-54dd-4d9d-8227-1de542eabea8', '寄周繇求人參', '寄周繇求人參', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["少賦令才猶強作，衆醫多識不能呼。","九莖仙草真難得，五葉靈根許惠無。"]', '["少賦令才猶強作，衆醫多識不能呼。","九莖仙草真难得，五葉靈根許惠無。"]', '诗', 'shi', '', NULL, '寄周繇求人參 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2753fe72-a9ae-4aeb-bf6a-5b6927f34008', '嘲飛卿七首 一', '嘲飞卿七首 一', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["曾見當壚一箇人，入時裝束好腰身。","少年花蔕多芳思，只向詩中寫取真。"]', '["曾见當壚一箇人，入时裝束好腰身。","少年花蔕多芳思，只向诗中寫取真。"]', '诗', 'shi', '', NULL, '嘲飛卿七首 一 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea16b91a-646a-403b-b0f9-5364d4cfc1f9', '嘲飛卿七首 二', '嘲飞卿七首 二', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["醉袂幾侵魚子纈，飄纓長罥鳳皇釵。","知君欲作閑情賦，應願將身作錦鞋。"]', '["醉袂幾侵鱼子纈，飄纓长罥鳳皇釵。","知君欲作闲情賦，應願將身作錦鞋。"]', '诗', 'shi', '', NULL, '嘲飛卿七首 二 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c2a808f-9501-4844-bf17-0b68563385aa', '嘲飛卿七首 三', '嘲飞卿七首 三', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["翠蝶密偎金叉首，青蟲危泊玉釵梁。","愁生半額不開靨，只爲多情團扇郎。"]', '["翠蝶密偎金叉首，青蟲危泊玉釵梁。","愁生半額不开靨，只爲多情團扇郎。"]', '诗', 'shi', '', NULL, '嘲飛卿七首 三 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3066e5dc-9ad7-414a-b8b9-f74e232ebe40', '嘲飛卿七首 四', '嘲飞卿七首 四', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["柳煙梅雪隱青樓，殘日黃鸝語未休。","見說自能裁袙腹，不知誰更著帩頭。"]', '["柳煙梅雪隐青楼，殘日黄鸝語未休。","见说自能裁袙腹，不知誰更著帩头。"]', '诗', 'shi', '', NULL, '嘲飛卿七首 四 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e4ce45e-4d5e-4f41-b612-f97516cd9259', '嘲飛卿七首 五', '嘲飞卿七首 五', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["愁機嬾織同心苣，悶繡先描連理枝。","多少風流詞句裏，愁中空詠早環詩。"]', '["愁機嬾织同心苣，悶繡先描連理枝。","多少风流词句裏，愁中空詠早环诗。"]', '诗', 'shi', '', NULL, '嘲飛卿七首 五 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('519fb22d-8b31-4765-b5b5-d66344b25f67', '嘲飛卿七首 六', '嘲飞卿七首 六', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["燕支山色重能輕，南陽水澤鬬分明。","不煩射雉先張翳，自有琴中威鳳聲。"]', '["燕支山色重能轻，南陽水澤鬬分明。","不煩射雉先張翳，自有琴中威鳳声。"]', '诗', 'shi', '', NULL, '嘲飛卿七首 六 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a6a50ec-56b7-4fe6-8dc0-24f0dc5141d3', '嘲飛卿七首 七', '嘲飞卿七首 七', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["半歲愁中鏡似荷，牽環撩鬢却須磨。","花前不復抱瓶渴，月底還應琢刺歌。"]', '["半歲愁中镜似荷，牽环撩鬢却須磨。","花前不复抱瓶渴，月底還應琢刺歌。"]', '诗', 'shi', '', NULL, '嘲飛卿七首 七 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ee69e73-407c-4a18-a049-427d1666af24', '柔卿解籍戲呈飛卿三首 一', '柔卿解籍戲呈飞卿三首 一', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["長擔犢車初入門，金牙新醞盈深罇。","良人爲漬木瓜粉，遮却紅腮交午痕。"]', '["长擔犢车初入门，金牙新醞盈深罇。","良人爲漬木瓜粉，遮却紅腮交午痕。"]', '诗', 'shi', '', NULL, '柔卿解籍戲呈飛卿三首 一 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca21417f-ab48-4a54-97ea-3aab8768c00e', '柔卿解籍戲呈飛卿三首 二', '柔卿解籍戲呈飞卿三首 二', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["最宜全幅碧鮫綃，自襞春羅等舞腰。","未有長錢求鄴錦，且令裁取一團嬌。"]', '["最宜全幅碧鮫綃，自襞春羅等舞腰。","未有长錢求鄴錦，且令裁取一團嬌。"]', '诗', 'shi', '', NULL, '柔卿解籍戲呈飛卿三首 二 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0394af6-ef6e-4a84-a033-155ce57ff9a6', '柔卿解籍戲呈飛卿三首 三', '柔卿解籍戲呈飞卿三首 三', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["出意挑鬟一尺長，金爲鈿鳥簇釵梁。","鬱金種得花茸細，添入春衫領裏香。"]', '["出意挑鬟一尺长，金爲鈿鸟簇釵梁。","鬱金種得花茸細，添入春衫領裏香。"]', '诗', 'shi', '', NULL, '柔卿解籍戲呈飛卿三首 三 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b17e4529-1eaa-4872-9471-b6c6df996998', '戲高侍御七首 一', '戲高侍御七首 一', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["百媚城中一箇人，紫羅垂手見精神。","青琴仙子長敎示，自小來來號阿真。"]', '["百媚城中一箇人，紫羅垂手见精神。","青琴仙子长敎示，自小来来號阿真。"]', '诗', 'shi', '', NULL, '戲高侍御七首 一 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3fab50-789a-484b-9a71-83f1f253c2bc', '戲高侍御七首 二', '戲高侍御七首 二', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["七尺髮猶三角梳，玳牛獨駕長檐車。","曾城自有三青鳥，不要蓮東雙鯉魚。"]', '["七尺髮猶三角梳，玳牛独駕长檐车。","曾城自有三青鸟，不要蓮东雙鯉鱼。"]', '诗', 'shi', '', NULL, '戲高侍御七首 二 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('453d27e6-cf0e-484f-bccb-da6583237e8f', '戲高侍御七首 三', '戲高侍御七首 三', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["花恨紅腰柳妬眉，東鄰牆短不曾窺。","猶憐最小分瓜日，奈許迎春得藕時。"]', '["花恨紅腰柳妬眉，东鄰牆短不曾窺。","猶怜最小分瓜日，奈許迎春得藕时。"]', '诗', 'shi', '', NULL, '戲高侍御七首 三 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2c9f40a-d762-4408-bf15-9740be986004', '戲高侍御七首 四', '戲高侍御七首 四', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["自等腰身尺六疆，兩重危鬢盡釵長。","欲熏羅薦嫌龍腦，須爲尋求石葉香。"]', '["自等腰身尺六疆，兩重危鬢尽釵长。","欲熏羅薦嫌龙腦，須爲尋求石葉香。"]', '诗', 'shi', '', NULL, '戲高侍御七首 四 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6c766cd-983a-4838-961b-e8a9df052f68', '戲高侍御七首 五', '戲高侍御七首 五', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["別起青樓作幾層，斜陽幔卷鹿盧繩。","厭裁魚子深紅纈，泥覓蜻蜓淺碧綾。"]', '["別起青楼作幾層，斜陽幔卷鹿盧繩。","厭裁鱼子深紅纈，泥覓蜻蜓淺碧綾。"]', '诗', 'shi', '', NULL, '戲高侍御七首 五 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('785ab22b-9918-4e6f-8e9b-765d349a3893', '戲高侍御七首 六', '戲高侍御七首 六', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["詐嫌嚼貝磨衣鈍，私帶男錢壓鬢低。","不獨邯鄲新嫁女，四枝鬟上插通犀。"]', '["詐嫌嚼貝磨衣鈍，私带男錢壓鬢低。","不独邯鄲新嫁女，四枝鬟上插通犀。"]', '诗', 'shi', '', NULL, '戲高侍御七首 六 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc7cc5a1-b2b6-4b0c-89bf-03aa69997924', '戲高侍御七首 七', '戲高侍御七首 七', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["可羨羅敷自有失，愁中漫捋白髭鬚。","豹錢驄子能擎舉，兼著連乾許換無。"]', '["可羨羅敷自有失，愁中漫捋白髭鬚。","豹錢驄子能擎舉，兼著連乾許換無。"]', '诗', 'shi', '', NULL, '戲高侍御七首 七 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1f0510b-fe10-4f67-8650-dcba336859b5', '送僧二首 一', '送僧二首 一', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["形神不滅論初成，愛馬乘閑入帝京。","四十三年虛過了，方知僧裏有唐生。"]', '["形神不滅論初成，愛马乘闲入帝京。","四十三年虛過了，方知僧裏有唐生。"]', '诗', 'shi', '', NULL, '送僧二首 一 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59558c6f-0387-4b99-bf67-a8a4b3d8b7d0', '送僧二首 二', '送僧二首 二', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["想到頭陀最上方，桂陰猶認惠宗房。","因行戀燒歸來晚，窗下猶殘一字香。"]', '["想到头陀最上方，桂陰猶認惠宗房。","因行戀燒归来晚，窗下猶殘一字香。"]', '诗', 'shi', '', NULL, '送僧二首 二 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('344de048-edd9-4c3b-8aef-698575b0eb52', '猨', '猨', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["却憶書齋值晚晴，挽枝閑嘯激蟬清。","影沈巴峽夜巖色，蹤絕石塘寒瀨聲。"]', '["却憶书斋值晚晴，挽枝闲嘯激蟬清。","影沈巴峽夜巖色，蹤絕石塘寒瀨声。"]', '诗', 'shi', '', NULL, '猨 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('661ac598-01ca-49f5-a3b3-f64b4b01e545', '送穆郎中赴闕', '送穆郎中赴闕', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["應念愁中恨索居，鸝歌聲裏且踟蹰。","若逢金馬門前客，爲說虞卿久著書。"]', '["應念愁中恨索居，鸝歌声裏且踟蹰。","若逢金马门前客，爲说虞卿久著书。"]', '诗', 'shi', '', NULL, '送穆郎中赴闕 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40858229-9008-4672-bf96-25fffd5a8059', '題商山廟', '題商山廟', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["偶出雲泉謁禮闈，篇章曾沐漢皇知。","無謀靜國東歸去，羞過商山四老祠。"]', '["偶出云泉謁禮闈，篇章曾沐漢皇知。","無謀静国东归去，羞過商山四老祠。"]', '诗', 'shi', '', NULL, '題商山廟 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8c901ac-db86-4ad5-a544-84adc0d82772', '折楊柳七首 一', '折楊柳七首 一', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["枝枝交影鎖長門，嫩色曾沾雨露恩。","鳳輦不來春欲盡，空留鶯語到黃昏。"]', '["枝枝交影鎖长门，嫩色曾沾雨露恩。","鳳輦不来春欲尽，空留鶯語到黄昏。"]', '诗', 'shi', '', NULL, '折楊柳七首 一 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c6ee3e-05db-4b36-960e-4ec6f98f0179', '折楊柳七首 二', '折楊柳七首 二', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["水殿年年占早芳，柔條偏惹御爐香。","而今萬乘多巡狩，輦路無陰綠草長。"]', '["水殿年年占早芳，柔條偏惹御爐香。","而今万乘多巡狩，輦路無陰綠草长。"]', '诗', 'shi', '', NULL, '折楊柳七首 二 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('547b5b7f-6ef0-42f8-8567-ae9b959c0686', '折楊柳七首 三', '折楊柳七首 三', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["玉樓煙薄不勝芳，金屋寒輕翠帶長。","公子驊騮往何處，綠陰堪繫紫遊韁。"]', '["玉楼煙薄不勝芳，金屋寒轻翠带长。","公子驊騮往何处，綠陰堪繫紫游韁。"]', '诗', 'shi', '', NULL, '折楊柳七首 三 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0357e3-ef40-46ff-97dd-1b281fd1b7d5', '折楊柳七首 四', '折楊柳七首 四', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["嫩葉初齊不耐寒，風和時拂玉欄干。","君王去日曾攀折，泣雨傷春翠黛殘。"]', '["嫩葉初齊不耐寒，风和时拂玉欄干。","君王去日曾攀折，泣雨傷春翠黛殘。"]', '诗', 'shi', '', NULL, '折楊柳七首 四 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92e44639-ccf9-45ef-8cb9-3b275fda625f', '折楊柳七首 五', '折楊柳七首 五', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["微黃纔綻未成陰，繡戶珠簾相映深。","長恨早梅無賴極，先將春色出前林。"]', '["微黄纔綻未成陰，繡戶珠簾相映深。","长恨早梅無賴極，先將春色出前林。"]', '诗', 'shi', '', NULL, '折楊柳七首 五 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87b51d41-c5ce-462d-8d58-2af2c68cfb7c', '折楊柳七首 六', '折楊柳七首 六', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["隋家堤上已成塵，漢將營邊不復春。","只向江南幷塞北，酒旗相伴惹行人。"]', '["隋家堤上已成塵，漢將營邊不复春。","只向江南幷塞北，酒旗相伴惹行人。"]', '诗', 'shi', '', NULL, '折楊柳七首 六 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0e7744c-d7c9-44bb-9887-812a44dc9a5b', '折楊柳七首 七', '折楊柳七首 七', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["陌上河邊千萬枝，怕寒愁雨盡低垂。","黃金穟短人多折，已恨東風不展眉。"]', '["陌上河邊千万枝，怕寒愁雨尽低垂。","黄金穟短人多折，已恨东风不展眉。"]', '诗', 'shi', '', NULL, '折楊柳七首 七 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb953f9d-e974-4b2a-b2d2-e577e58c5914', '哭李羣玉', '哭李羣玉', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["酒裏詩中三十年，縱橫唐突世喧喧。","明時不作禰衡死，傲盡公卿歸九泉。"]', '["酒裏诗中三十年，縱橫唐突世喧喧。","明时不作禰衡死，傲尽公卿归九泉。"]', '诗', 'shi', '', NULL, '哭李羣玉 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8b11e18-8072-4388-adca-8223bfe8efd1', '漢宮詞二首 一', '漢宮词二首 一', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["歌舞初承恩寵時，六宮學妾畫蛾眉。","君王厭世妾頭白，聞唱歌聲却淚垂。"]', '["歌舞初承恩寵时，六宮学妾畫蛾眉。","君王厭世妾头白，闻唱歌声却泪垂。"]', '诗', 'shi', '', NULL, '漢宮詞二首 一 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07dde93a-e961-47d2-9b95-851ff061836d', '漢宮詞二首 二', '漢宮词二首 二', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["二八能歌得進名，人言選入便光榮。","豈知妃后多嬌妬，不許君前唱一聲。"]', '["二八能歌得進名，人言選入便光榮。","豈知妃后多嬌妬，不許君前唱一声。"]', '诗', 'shi', '', NULL, '漢宮詞二首 二 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f27ff619-51ec-4698-93da-6b7751d8eaf2', '醉中吟', '醉中吟', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["只愛糟牀滴滴聲，長愁聲絕又醒醒。","人間榮辱不常定，唯有南山依舊青。"]', '["只愛糟牀滴滴声，长愁声絕又醒醒。","人间榮辱不常定，唯有南山依旧青。"]', '诗', 'shi', '', NULL, '醉中吟 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e061e66b-71f5-484e-b85b-a80285f86faf', '桃源僧舍看花', '桃源僧舍看花', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["前年帝里探春時，寺寺名花我盡知。","今日長安已灰燼，忍能南國對芳枝。"]', '["前年帝里探春时，寺寺名花我尽知。","今日长安已灰燼，忍能南国对芳枝。"]', '诗', 'shi', '', NULL, '桃源僧舍看花 段成式 shi');
